window.__D("text/likkutei-sichot/c180",{"p":[[1300281073,"כאשר יחפוץ“¹² — דערפאר איז דער פסוק מוסיף „וזה מעשה המנורה מקשה וגו׳“ אז דער דין „מקשה“ איז אויך שפעטער.\nמען קען אבער אזוי ניט מסביר זיין לויט פרש״י — ווארום אע״פ שי״ל אז אויך לדעת רש״י עה״ת זיינען די נרות ניט געווען איין חלק מיט דער מנורה¹³, ובמילא איז מקום לומר אז מ׳האט יעדן מאל אראפגענומען און מעלה געווען די נרות אויף דער מנורה, איז אבער\n[נוסף ע״ז וואס אין פשוטו של מקרא איז שווער צו זאגן אז דערפון וואס די נרות זיינען געווען באזונדער און מ׳האט זיי יעדן טאג מעלה געווען אויף דער מנורה זאל מען אפלערנען אויף דער גאנצער מנורה, וויבאלד אז במקום הציווי ע״ז אין פ׳ תרומה איז קלאר¹³ אז די גאנצע מנורה דארף זיין „מקשה“ (מלבד די נרות) — איז]\nאין דעם פירוש הכתוב „בהעלותך“ טייטשט רש״י בפירוש „על שם שהלהב עולה כתוב בהדלקתן לשון עלי׳ שצריך להדליק עד שתהא שלהבת עולה מאלי׳“. זעט מען, אז רש״י לערנט דעם פירוש אין „בהעלותך את הנרות“ ניט אז מ׳איז מעלה די נרות אויף דער מנורה (ווארום אויב אזוי איז דאך ניטא קיין מקור לפירושו¹⁴; דער פסוק רעדט (כפשוטו) וועגן „להב“ — „שהלהב עולה“ — און נרות מאן דכר שמי׳).\nבלייבט די שאלה: פארוואס שטייט דא דער פסוק „וזה מעשה גו׳ מקשה“¹⁵.\nג. אויך דארף מען פארשטיין: וואס איז די הוספה אין דער פרשה „בהעלותך את הנרות אל מול פני המנורה יאירו שבעת הנרות“? דער ציווי איז שוין געזאגט געווארן אין פ׳ תרומה¹⁶ „ועשית את נרותי׳ שבעה והעלה את נרותי׳ והאיר על עבר פני׳“¹⁷.\nנאכמער: וויבאלד אז די עשיית הנרות איז געווען אין אן אופן אז זיי קערן זיך כלפי דעם נר האמצעי, ווי רש״י איז מפרש אין פ׳ תרומה¹⁶ „והאיר על עבר פני׳ — עשה פי ששת הנרות שבראשי הקנים היוצאים מצדי׳ מסובים כלפי האמצעי כדי שיהיו הנרות כשתדליקם מאירים אל עבר פני׳ מוסב אורם אל צד פני הקנה האמצעי שהוא גוף המנורה“ — ווי פאסט בכלל א ציווי אויף דעם, בשעת אזוי איז דאס בדרך ממילא, די נרות דארפן געמאכט ווערן באופן זה ווי אנגעזאגט ביי דער עשי׳¹⁸.",[["12","12","לשון האוה״ח שם."],["13","13","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161324\" data-slug=\"likkutei-sichot\" data-id=\"1300161324\">לקו״ש חט״ז ע׳ 324</a>. וש״נ."],["14","14","וכן זה ד„דרשו רבותינו (שהביא רש״י שם) מכאן שמעלה היתה לפני המנורה שעלי׳ הכהן עומד ומטיב“."],["15","15","בחזקוני כאן: ענין מלאכת המנורה נאמרה במקום אחר ונשנה כאן בשביל פרח הירך שנתחדש בה הוא שנאמר כאן עד ירכה עד פרחה (וכ״ה במנחות כט, רע״א. רמב״ם הל׳ ביהב״ח רפ״ג). אבל, אף שבפ׳ תרומה (כה, לה) הביא רש״י מברייתא דמלאכת המשכן דלמדין מפרח דפרשתנו, בפרש״י כאן אינו מפרש כן, כדמוכח מפירושו עה״פ כאן (ואכ״מ)."],["16","16","כה, לז."],["17","17","דרש״י בתחלת פרשתנו מתרץ רק הסמיכות לפרשת הנשיאים, אבל אינו מבאר טעם כפל הציווי בכלל. ואין לומר שלפרש״י לא נתחדש כאן שום דבר בעצם הציווי ורק גודל הדלקת הנרות על ידי אהרן, ד„גדולה משלהם“, מחנוכת הנשיאים — כי: א) מלשון רש״י „למה נסמכה“ מובן שהשאלה היא על הסמיכות ולא ע״ז שנאמר בכלל (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181102\" data-slug=\"likkutei-sichot\" data-id=\"1300181102\">לקו״ש חי״ח ע׳ 92</a> ואילך). ב) לפ״ז לא הוצרך הכתוב להוסיף ציווי פרטי, כ״א ציווי כללי דהדלקת והטבת הנרות."],["18","18","כמו שהקשה בדברי דוד (להט״ז) תרומה שם. וראה הערה 23."]]],[1300281074,"וי״ל אז רש״י באווארנט עס. ער איז מפרש „יאירו שבעת הנרות — ששה¹⁹ שעל ששת הקנים שלשת המזרחיים פונים למול האמצעי הפתילות שבהן וכן שלשת המערביים ראשי²⁰ הפתילות למול האמצעי“. דערפון וואס רש״י איז משנה בלשונו דא „הפתילות . . ראשי הפתילות“ — ניט ווי בפירושו בפ׳ תרומה „פי ששת הנרות“ — איז מובן, אז דא איז א באזונדער ציווי צו אהרן, אז נוסף אויף דעם וואס פי ששת הנרות זיינען מסובים כלפי האמצעי²¹, דארף²² אהרן אויך מטה זיין די פתילות²³, זיי זאלן פונה זיין כלפי האמצעי, וואס פון דעם היינגט אפ ווי עס וועט זיין דער „יאירו (פון די) שבעת הנרות“.\nלפ״ז דארף מען אבער פארשטיין לשון הכתוב בפרשתנו „אל מול פני המנורה יאירו שבעת הנרות“: וויבאלד אז דא איז צוגעקומען א ציווי אין דער מעשה ההדלקה פון אהרן, האט דאך געדארפט שטיין בלשון ציווי לאהרן „תאיר שבעת הנרות“, און ניט „יאירו“, אז די נרות זאלן לייכטן²⁴?\nד. איז דער ביאור בזה — בהקדם:\nאין די פרשיות וואו עס רעדט זיך וועגן דער מנורה געפינט מען א מחלוקת צווישן רש״י און רמב״ן:\nא) אין פ׳ אמור²⁵, וואו עס שטייט דער ציווי „ויקחו אליך שמן זית זך כתית למאור להעלות נר תמיד מחוץ לפרוכת העדות באהל מועד יערוך אותו אהרן גו׳“ זאגט רש״י: זו פרשת מצות הנרות ופרשת ואתה תצוה לא נאמרה אלא על סדר מלאכת המשכן לפרש צורך המנורה.",[["19","19","ובחזקוני גורס ברש״י „הנרות שעל כו׳“ — „אלא שהסופרים כו׳“. וראה מושב זקנים כאן (סוף פסוק ב) בשם החזקוני."],["20","20","הוספה בהענין ותוספת ביאור — וקאי גם על המזרחיים."],["21","21","וראה גם פרש״י מגילה כא, ב ד״ה אל מול (וראה גם שוה״ג הא׳ להערה 23). וברמב״ם הל׳ ביהב״ח (פ״ג ה״ח): ששת הנרות הקבועים בששת הקנים היוצאים מן המנורה כולן פניהם לנר האמצעי שעל קני* המנורה. ומשמע שהוא דבר שנעשה ב(מעשה) המנורה, ולא פעולה בהפתילות."],["22","22","אבל ראה ס׳ זכרון כאן (ח, ב), דברי דוד ומשכיל לדוד תרומה שם."],["23","23","שצריך להטות הפתילות — כן משמע גם בפרש״י מנחות צח, ב ד״ה מצדד להו, אבל לאו דוקא שגם הנרות עצמן מצודדין*. אבל מפרש״י פרשתנו, שהוסיף „הפתילות שבהן . . ראשי הפתילות כו׳“ ולא הסתפק במ״ש „ששה שעל ששת הקנים כו׳ פונים למול האמצעי“ והי׳ מובן שפירושו כמ״ש בפ׳ תרומה, משמע שהיתה פעולה בפ״ע בהפתילות בעת שהדליק. וכ״כ בחת״ס עה״ת ריש פרשתנו**. אבל ראה מקומות שבהערה הקודמת."],["24","24","וכמו שהקשה באוה״ח כאן ד״ה בהעלותך. ובאוה״ח מתרץ (לשיטתו) כי הציווי רק על ההכנה (הנרות עצמן), אבל לפי המבואר בפנים לפרש״י, שהציווי כאן גם על אופן הנחת הפתילה — הקושיא במקומה עומדת."],["25","25","כד, ב־ג. *) כ״ה בדפוסים שלפנינו (וכן בדפוסים הראשונים דהרמב״ם). ובקרית ספר לרמב״ם שם „שעל קנה המנורה“. וכן הוא ברמב״ם שנדפס עם פירוש הר המורי׳ (אלא דיש שם טה״ד כנראה, שהתיבות לפנ״ז שם „פניהם לצד האמצעי“, ולא כלפנינו לנר האמצעי). ואוצ״ל: של קני. *) או י״ל להיפך, שרק הנרות מצודדין ולא הפתילות. **) בבאר מים חיים (לאחי המהר״ל) מפרש בפרשתנו, דהבזיכין „היו עגולות ושוין לכל צד ולא הי׳ להן שנצין, אלא שהכהן ממשיך הפתילות כפי רצונו וזה נלמד מדהוצרך לצוות את אהרן ולא ציוה את בצלאל לעשות היכר בנרות מקום שיניח בו הפתילות“, והיינו כבתחלת ההערה. וצ״ע: נוסף לזה שבפרש״י תרומה מוכח דהנרות עצמן מצודדין, הרי גם בעצמו מפרש שם „שהי׳ עושה לבזיכין עצמן כמין שנצין שהפתילה מונח בו“."]]],[1300281075,"דער רמב״ן דארטן אין פ׳ אמור איז חולק אויף רש״י און לערנט „צורך הפרשה הזאת“ (פ׳ אמור) לגבי הדלקת המנורה, אז „שם (בפ׳ תצוה) עוד לא אמר אלא יערוך אותו אהרן ובניו וגו׳ והי׳ במשמע על המנורה או בלא מנורה אם תשבר או תאבד כו׳ ועכשיו²⁶ אמר בפירוש על המנורה הטהורה²⁷ שלא ידליקו אלא על מנורה הטהורה“.\nד. ה. לויט רש״י איז פרשת אמור דער ציווי פון די „פרשת מצות הנרות“, און לויטן רמב״ן איז דאס א המשך און א פרט אין דער מצות הדלקת הנרות (שבפ׳ תצוה), אז זי דארף זיין דוקא על המנורה.\nב) בתחלת פרשתנו איז רש״י מפרש „למה נסמכה פרשת המנורה לפרשת הנשיאים לפי שכשראה אהרן חנוכת הנשיאים כו׳ אמר לו הקב״ה חייך שלך גדולה משלהם שאתה מדליק ומטיב את הנרות“.\nדער רמב״ן פרעגט אויף רש״י און לערנט אנדערש, אז כשם ווי די פרשה אין אמור איז א הוספה אויף דער פרשה פון ואתה תצוה (אז די הדלקה מוז זיין על המנורה דוקא), עד״ז איז די פרשה — „ובכאן כאשר השלים להזכיר הקמת המשכן השלים עוד כל דיני הנרות וצוה שיהיו שבעת הנרות כולן דולקות לדורות אל מול פני המנורה, כאשר הזכיר במעשה המנורה כו׳ לא בלתי מנורה ולא בלתי שיאירו כולם אל עבר פני׳“ (און אזוי זאל אויך זיין לדורות, וואס דערפאר „לא הזכיר בפרשה הזאת באה״מ ללמד שיהי׳ כן במקדש כו׳“).\nולפ״ז קומט אויס דער חילוק צווישן רש״י און רמב״ן:\nלויט רש״י זיינען פאראן דריי באזונדערע פרשיות בנוגע צו דער מנורה: דער ציווי בר״פ תצוה איז א טייל פון דעם ציווי וסדר מלאכת המשכן (פון פ׳ תרומה), בפ׳ אמור איז „פרשת מצות הנרות“, און פרשתנו „בהעלותך את הנרות“ איז „פרשת המנורה“ (ניט „פרשת . . הנרות“ — ווי אין פ׳ אמור);\nאבער לויטן רמב״ן, איז פ׳ תצוה די פרשה פון דער מצות הדלקת הנרות, און די ציוויים בפ׳ אמור ושבפרשתנו זיינען ביידע פרטים והשלמות אין דיני הדלקת הנרות (אז עס דארף זיין אויף א מנורה דוקא, ושיאירו אל עבר פני׳).\nה. ע״פ הנ״ל, קומט אויס א חילוק צווישן רש״י און רמב״ן — אויך בנוגע דעם פסוק „וזה מעשה המנורה מקשה גו׳“:\nלדעת הרמב״ן, וויבאלד דער תוכן הפרשה („בהעלותך את הנרות אל מול פני המנורה יאירו גו׳“) איז א המשך „לדיני הנרות“ — הדלקת המנורה, איז אויך דער סיום, דער פסוק „וזה מעשה המנורה מקשה גו׳“ א פרט און השלמה אין דיני הנרות — צוליב מקיים זיין מצות הדלקת הנרות: כשם ווי די הדלקה דארף זיין אויף א מנורה דוקא (און ניט „בלא מנורה“), דארף דאס זיין אויף א מנורה וואס איז „מקשה“, און אויב ניט איז דאס מעכב די הדלקת הנרות.\nלויט פרש״י אבער, וואס ער רופט אן די פרשה „פרשת המנורה“ (כנ״ל), קומט אויס, אז דער עיקר בפרשתנו איז וועגן מעשה המנורה (ניט הדלקת הנרות) וועלכע ווערט געזאגט אין דעם פסוק „וזה מעשה המנורה מקשה גו׳“.",[["26","26","וגם בנוגע להשמן — לדורות, כמבואר ברמב״ן שם (ובפרשתנו הזכיר בנוגע לפ׳ אמור — רק המובא בפנים)."],["27","27","שם, ד."]]],[1300281076,"ס׳איז אבער צריך ביאור: די פרשה רעדט דאך לכאורה (בעיקר) ניט וועגן דער מנורה גופא, נאר וועגן דער מצוה פון הדלקת הנרות, „אל מול פני המנורה יאירו שבעת הנרות“?\nאיז דערפון פארשטאנדיק, אז אויך דער ענין פון „אל מול פני המנורה“ איז נוגע (ניט אזוי צו דעם קיום מצות הדלקת הנרות, נאר) צו דעם עצם גוף המנורה.\nו. די הסברה אין דעם:\nאין די פסוקים בפ׳ תרומה, וואו עס ווערט גערעדט וועגן מעשה המנורה, שטייט²⁸ „ועשית מנורת זהב טהור מקשה תיעשה המנורה ירכה וקנה גביעי׳ כפתורי׳ ופרחי׳ ממנה יהיו“. דערנאך שטייט אין פסוק „וששה קנים יוצאים מצדי׳ שלשה קני מנורה מצדה האחד ושלשה קני מנורה מצדה השני“.\nקומט אויס, אז אע״פ וואס די גאנצע מנורה איז געווען „מקשה אחת זהב“²⁹ איז אבער דא א חילוק צווישן דעם קנה האמצעי „גופה של מנורה“ מיט די „ששה קנים“: אין גופה של מנורה האבן זיך ניט אנגעזען קיין באזונדערע חלקים, ס׳האט זיך קלאר געזען איין כלי, זאך; משא״כ די ששת הקנים כאטש עשייתם איז געווען פון דעם זעלבן „עשת . . זהב“³⁰, איז אבער לאחרי עשיית המנורה ניט געווען ניכר בגלוי ווי דאס איז איין זאך מיט „גופה של מנורה“.\nבשעת אבער אהרן איז מקיים „בהעלותך את הנרות אל מול פני המנורה יאירו שבעת הנרות“, איז דורכדעם וואס אלע ששת הנרות לייכטן אל פני המנורה, מול נר האמצעי, ווערט ניכר ניט בלויז ווי דאס איז איין מנורה, נאר ווי אלע נרות זיינען א חלק פון (ופרט טפל צו) גופה של מנורה, נר האמצעי³¹.\nקומט במילא אויס, אז אע״פ וואס בפועל איז דער ציווי דא נוגע צו דער מעשה ההדלקה פון אהרן, די פעולה פון אהרן אין די פתילות³² (ניט א פעולה פארבונדן מיט עשיית המנורה — די מעשה אין פי הנרות), איז אבער תוכנו וגדרו נוגע (אויך) צו דער מנורה גופא³³.\nאון דערפאר שטייט ניט אין פסוק דער לשון „תאיר שבעת הנרות“ בסגנון של ציווי צו אהרן, נאר „יאירו שבעת הנרות“, ווייל דער תוכן וגדר פון „אל מול פני המנורה“ איז (ניט נאר א דין ומצוה אין דער מעשה הדלקה של הגברא, נאר) א דין אין דער חפצא של המנורה.\nאון בכדי צו ארויסברענגען דעם ענין ווי „אל מול פני המנורה“ איז א חלק פון „פרשת המנורה“ — ניט פון „פרשת מצות הנרות“ — איז דער פסוק מוסיף",[["28","28","כה, לא ואילך."],["29","29","שם, לו."],["30","30","ל׳ רש״י פרשתנו ח, ד (ד״ה מקשה)."],["31","31","ועפ״ז יומתק זה שרש״י לא הביא דנר האמצעי — נר מערבי — כלפי שכינה (כבמגילה שם. וכ״כ ברמב״ם שם „כנגד קדש הקדשים“) — כי עיקר ההדגשה כאן הוא לא לבאר מקום הטיית הנרות, כ״א מה שעי״ז ניכר שששת הקנים הם אחד עם גופה של מנורה, נר האמצעי."],["32","32","והטעם כפי שמסיים בפרש״י „ולמה כדי שלא יאמרו לאורה הוא צריך“. וראה הערה הבאה."],["33","33","וזה מודגש גם בהטעם דפרש״י „שלא יאמרו לאורה הוא צריך“ [ראה מפרשים (באר היטב. צידה לדרך. ועוד) דכאשר כולם פונים אל האמצעי אין האור מתפשט ומאיר (כ״כ)] וא״כ ע״י שפעולת ההדלקה היא אל מול פני המנורה, ניכר שהמנורה לא לאורה כו׳ נמצא שתוכן פעולת אהרן היא לא רק הדלקת נרות — שמאיר אור, כ״א גם גמר מעשה המנורה."]]],[1300281077,"דא „וזה מעשה המנורה מקשה זהב עד ירכה עד פרחה מקשה היא“; און נאכמער: דער פסוק רעכנט דא ניט אויס באזונדער די מנורה, גופה של מנורה מיט די קנים גביעים כפתורים ופרחים ווי אין פ׳ תרומה, נאר אין כללות׳דיקן לשון „המנורה . . עד פרחה“.\nויש לומר אז דאס איז דער דיוק הלשון אין פרש״י „גופה של מנורה כולה וכל התלוי בה“, ווייל דא איז נוגע ניט (נאר) די עצם זאך אז „כולה מקשה אחת“ אין דעם אופן העשי׳ (ווי אין פ׳ תרומה), נאר ווי אלץ איז א חלק פון דעם גוף המנורה „גופה של מנורה וכל התלוי בה“.\nז. לכאורה קען מען אבער פרעגן:\nרש״י בתחלת הפרשה פירט אויס, אז דערויף וואס „חלשה אז דעתו (של אהרן) כשלא הי׳ עמהם בחנוכה לא הוא ולא שבטו“, האט אים דער אויבערשטער מנחם געווען „שאתה מדליק ומטיב את הנרות“. הייסט עס דאך אז די פרשה רעדט בעיקר וועגן „מדליק ומטיב את הנרות“, ווי שטימט עס מיט הנ״ל אז דער תוכן הפרשה איז (ניט די עצם מעשה הדלקה והטבה של הנרות, נאר) „פרשת המנורה“, וואס איז נוגע צו דעם גוף המנורה?\nאיז דער ביאור אין דעם:\nשוין גערעדט אמאל בארוכה³⁴ אז דיבור ה׳ „(חייך שלך גדולה משלהם) שאתה מדליק ומטיב את הנרות“ מיינט ניט (נאר) די הדלקת הנרות פון אהרן כשלעצמה (און אז דאס איז גרעסער ווי די חנוכת המזבח פון די נשיאים)³⁵, נאר ס׳מיינט אז דאס וואס „אתה מדליק ומטיב את הנרות“ איז א גדר פון חנוכת המנורה: אין די אלע צוועלף טעג וואס די נשיאים האבן געבראכט זייערע קרבנות לחנוכת המזבח — איז די אלע צוועלף טעג אהרן מדליק ומטיב את הנרות, וואס דאס איז א גדר פון חנוכת המנורה (און דער „שלך גדולה“ איז אין כו״כ פרטים כמבואר אז³⁴),\nאון עיקרו ותוכנו פון ענין החנוכה איז ניט אזוי די פעולת העבודה, די (הקרבה ו)הדלקה של הגברא, נאר דאס וואס ער פועל׳ט דעם גמר המעשה וקדושת החפצא — המנורה, וואס מאכט מעגלעך דעם המשך העבודה — הדלקה והטבה של המנורה — בשלימות.\nח. דער ביאור בפנימיות הענינים:\nדי³⁶ נשמה ווערט אנגערופן נר, כמ״ש³⁷ נר ה׳ נשמת אדם, אז כללות נשמות ישראל ווערט אנגערופן מנורה, וואס אין דער מנורה זיינען דא שבעה נרות, וועלכע זיינען די זיבן מדריגות אין עבודת ה׳.\nאיז אין דעם פאראן צוויי ענינים³⁸: ווי די נשמות ישראל זיינען מצד שרשן, וואו „כולן מתאימות ואב אחד לכולנה“³⁹, זיי שטייען אלע בהתכללות ובהתאחדות, ביז אז אלע אידן זיינען איין זאך⁴⁰. דערנאך, לאחרי ווי יעדער נשמה ווערט נמשך פון דעם שורש, ווערט יעדער איד א מציאות בפ״ע, מחולק פון דעם צווייטן, יעדער איינער",[["34","34","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181104\" data-slug=\"likkutei-sichot\" data-id=\"1300181104\">לקו״ש חי״ח ע׳ 94</a> ואילך."],["35","35","דלפ״ז קשה קושיות הרמב״ן על פרש״י. ועוד כו״כ שאלות כמשנ״ת ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181103\" data-slug=\"likkutei-sichot\" data-id=\"1300181103\">לקו״ש שם (ע׳ 93</a> ואילך)."],["36","36","בהבא לקמן ראה דרושי בהעלותך בלקו״ת ואוה״ת. תו״א דרושי חנוכה. ועוד."],["37","37","משלי כ, כז."],["38","38","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231056\" data-slug=\"likkutei-sichot\" data-id=\"1300231056\">לקו״ש חכ״ג ע׳ 56</a> ואילך. וש״נ."],["39","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פל״ב</a>."],["40","40","ראה בארוכה קונטרס אהבת ישראל. וש״נ."]]],[1300281078,"פון זיי פארמאגט זיינע מעלות פרטיות וואס בהתאם לזה איז שליחותו „נבראתי לשמש את קוני“⁴¹.\nאון דאס זיינען די צוויי ענינים אין דער מנורה:\n„וזה מעשה המנורה מקשה זהב עד ירכה עד פרחה מקשה היא“ — ווייזט⁴² אויף די התאחדות פון אידן ווי זיי שטייען בשרשם — „מקשה אחת זהב טהור“, זיי שטייען בהתאחדות גמורה, בלי התחלקות מדריגות ביניהם⁴³.\nדערנאך ווערן זיי פאנאנדערגעטיילט אויף זיבן באזונדערע קנים, זיבן באזונדערע אופנים אין עבודת ה׳.\nאון⁴² דאס זאגט דער פסוק: „בהעלותך את הנרות“, ווי אזוי דארף זיין ווען יעדער נר ה׳ נשמת אדם טוט זיין עבודה פרטית? — דארף דאס זיין באופן פון „אל מול פני המנורה יאירו שבעת הנרות“, עס זאל זיין ניכר אויך בגלוי אז יעדן איינעמ׳ס עבודה פרטית איז ניט קיין ענין בפ״ע, נאר זיי אלע זיינען פארבונדן; אין יעדערן איז ניכר אז עיקרה ותוכנה פון דער עבודה פרטית זיינע — איז די נקודה כללית פון „(אני נבראתי) לשמש את קוני“⁴¹, וועלכע איז מאיר בשווה אין יעדן אופן העבודה.\nט. און אין דעם גופא זיינען פאראן צוויי אופנים: צי „וזה מעשה המנורה מקשה זהב“ איז נוגע און א פרט אין הדלקת הנרות (כדעת הרמב״ן), אדער פארקערט — אז „אל מול פני המנורה יאירו גו׳“ איז גומר ומשלים די מעשה המנורה (ווי לויט דעת רש״י).\nאין דער פעולה פון אהרן אין נשמות ישראל — „בהעלותך את הנרות“ — איז דא ווי ס׳איז לפי פשוטה און ווי דאס איז לפי פנימיותה ומטרתה:\nרש״י, וואס ענינו איז פשוטו של מקרא איז מפרש פעולת אהרן פון „בהעלותך את הנרות“ (כפשוטה), אז ער פועל׳ט ביי נשמות ישראל אז יעדער בפ״ע זאל זיין בעלי׳, זיך ציען לשרשו ומקורו, וואס דאס איז מדריגת אהרן — שושבינא דמטרוניתא⁴⁴ — וואס ער איז מעלה נשמות ישראל צו זייער שורש ומקור⁴⁵, וואס דארטן שטייען זיי באופן פון „מקשה אחת“.\nקומט אויס, אז די פעולת ההדלקה איז תוכנה די העלאה צו בחי׳ מקשה. דערפאר לערנט רש״י אז דער עיקר הענין בפרשתנו איז „פרשת המנורה“ — מעשה המנורה, ד. ה. דאס וואס די מנורה איז באופן של „מקשה“, און די הדלקת המנורה באופן פון „אל מול פני המנורה“ איז א חלק פון „מקשה“, דאס איז משלים די אחדות פון מקשה שבמעשה המנורה.\nדער רמב״ן אבער, וואס זיין פירוש איז ניט נאר „פשטים“ נאר אויך „דברים נעימים ליודעי חן“⁴⁶ — סודות התורה — איז זיין פירוש בהתאם מיט דער פנימיות ומטרה פון העלאת הנרות שעל ידי אהרן: דער תכלית פון דער העלאת נשמות ישראל איז דאך בכדי אויפטאן (מאכן) א דירה לו ית׳ בתחתונים⁴⁷, דוקא",[["41","41","סוף קידושין."],["42","42","ראה בכמה מפרשי התורה פרשתנו — אלשיך, צרור המור, ספורנו. ובכ״מ."],["43","43","ראה לקו״ת פרשתנו (לג, ג) באו״א קצת."],["44","44","זח״א רסו, ב. לקו״ת שם ל, א. וראה ס׳ הערכים חב״ד ערך אהרן ס״ד ובהנסמן שם."],["45","45","ראה בפרטיות בס׳ הערכים שם ס״ו."],["46","46","כמו שכתב בהקדמתו לפירושו עה״ת."],["47","47","תנחומא נשא טז. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל״ו</a>."]]],[1300281079,"אין עוה״ז התחתון, דער ארט פון רשות הרבים,\nאיז דערפון פארשטאנדיק, אז דער תכלית פון מקשה — די אחדות פון אידן ווי זיי זיינען מצד שרשם ומקורם — איז צו ממשיך זיין אט די אחדות (אויך) אין דעם ארט וואו די נשמות שטייען בהתחלקות אין זיבן באזונדערע נרות, באזונדערע אופני עבודה, אז אויך דארטן זאל נמשך ווערן די אחדות מצד זייער שורש³⁸, וואס דאס דריקט זיך אויס אין דעם „אל מול פני המנורה יאירו שבעת הנרות“.\nולפ״ז קומט אויס אז לויטן רמב״ן איז דער עיקר דא די הדלקה, נאר בכדי די הדלקה זאל זיין כדבעי, איז דאס דורך דעם וואס אין דער הדלקה איז ניכר די אחדות פון „מקשה“, שמצד עצם הנשמה.\n(משיחת ש״פ בהעלותך תש״ל)"],[1300281080,"<h3>בהעלותך ב</h3>\nא. אין היינטיקער סדרה, נאכדעם ווי די תורה דערציילט¹ וועגן דעם פסח שעשו ישראל במדבר (בשנה השנית לצאתם מארץ מצרים), שטייט²: ויהי אנשים אשר היו טמאים לנפש אדם ולא יכלו לעשות הפסח גו' ויאמרו גו' אנחנו טמאים לנפש אדם למה נגרע לבלתי הקריב את קרבן ה' במועדו גו'.\nדארפן פארשטיין אין וואס איז באשטאנען זייער טענה „למה נגרע\"³: זיי אליין האבן דאך מדגיש געווען (און אלס הקדמה צו דער טענה גופא) „אנחנו טמאים לנפש אדם\", ד.ה. זיי האבן געוואוסט אז דאס איז די סיבה צוליב וועלכער זיי קענען ניט מאכן דעם פסח („ולא יכלו לעשות הפסח\") — און ווי מ'האט שוין פריער⁴ אנגעזאגט „וישלחו מן המחנה גו' וכל טמא לנפש\" — איז וואס איז די טענה „(אנחנו טמאים גו' —) למה נגרע\"?!\nרש\"י איז מבאר⁵: „למה נגרע, אמר להם אין קדשים קרבים בטומאה, אמרו לו יזרק הדם עלינו בכהנים טהורים ויאכל הבשר לטמאים\".\nזאגן מפרשים⁶, אז דאס וואס עס שטייט אין רש\"י „ויאכל הבשר לטמאים\" איז א טעות סופר — ווארום א טמא טאר דאך ניט עסן קיין קדשים⁷ — און עס דארף שטיין ווי אין ספרי⁵ (דער מקור פון דעם פירוש רש\"י) „ויאכל הבשר לטהורים\"⁸.\nאון זיינען מסביר⁹, אז כוונת רש\"י מיט „ויאכל הבשר לטהורים\" איז (ע\"ד ווי מען לערנט¹⁰ איין אין ספרי) — לויטן מ\"ד¹¹ אז „חל שביעי שלהם (פון",[["1","1","ט, א־ה."],["2","2","שם, ו־ז."],["3","3","ראה רא\"ם, גו\"א ועוד — בפרש\"י דלקמן בפנים. בנחלת יעקב כאן, דאינו מוכרח שהיתה טענה, כי אפ\"ל דלמה נגרע לא הי' קושיא אלא שאלה בעלמא אם יש להם איזו תקנה (וע\"ש דכן מוכרח לפי הדיעות שהטמאים לנפש היו יכולים ליטהר לפנ\"ז) — אבל פשטות הלשון „למה נגרע\" היא טענה ותביעה (ולא „שאלה בעלמא אם יש להם תקנה\")."],["4","4","נשא ה, ב (ובפרש\"י שם: פרשה זו נאמרה ביום שהוקם המשכן*)."],["5","5","פרשתנו שם, ז."],["6","6","ס' זכרון, נחלת יעקב, משכיל לדוד, באר יצחק ועוד."],["7","7","כמפורש לעיל — צו ז, כ־כא."],["8","8","וכ\"ה בדפוס ראשון דפרש\"י, ובכת\"י רש\"י שתח\"י. וכן הועתק ברא\"ם, גו\"א ועוד. ובדפוס שני: לכהני'. וראה לקמן סעיף ז."],["9","9","מפרשים שנסמנו בהערה 6. רא\"ם ורע\"ב כאן. ועוד."],["10","10","ראה זית רענן (ליל\"ש עה\"פ). ספרי דבי רב, תולדות אדם, ועוד (לספרי שם). וראה תיב\"ע כאן. רמב\"ם וראב\"ד הל' ק\"פ פ\"ו ה\"ב ובנ\"כ שם. תוד\"ה שחל — פסחים צ, ב. ועוד."],["11","11","שהובא בספרי שם לפני זה (פסוק ו). פסחים שם. סוכה כה, ריש ע\"ב. וכ\"ה בתיב\"ע כאן. *) בפרש\"י לש\"ס (גיטין ס, סע\"א) דגם פרשה זו ד„ויהי אנשים גו'\" היא מהח' פרשיות שנאמרו ביום זה. אבל ע\"פ פשש\"מ הרי מפורש שהי' „ביום ההוא\" (דעשיית הפסח). ועכצ\"ל דלפרש\"י עה\"ת (דקפיד על פשש\"מ) פ' טמאים שהוזכרה בש\"ס שם (והובא בפרש\"י עה\"ת — נשא שם) היא פ' אחרת (וראה תוס' גיטין שם (ועוד)). או שיש לרש\"י פי' אחר בפשש\"מ: ולא הביאו בפי' כאן — כיון שהכרחו רק כשיודעים שנמנית פרשתנו בש\"ס, וזה לא הועתק בפרש\"י נשא. — ובכל אופן גם לפרש\"י לש\"ס, פרשת „ויהי אנשים גו'\" נאמרה לאחרי פרשת שילוח טמאים, כמפורש בפרש\"י שם. —"]]],[1300281081,"די טמאים לנפש אדם) להיות ערב פסח\", ובמילא, קענען זיי בליל פסח שוין עסן, ווייל זיי זיינען „טהורים\". און דאס איז געווען זייער טענה „יזרק הדם עלינו כו' ויאכל הבשר לטהורים\" — אע\"פ וואס ביום י\"ד זיינען זיי נאך טמאים, קען מען אבער זורק זיין אויף זיי דעם דם וויבאלד אז בזמן אכילת הפסח (בליל חמשה עשר בניסן) וועלן זיי שוין זיין טהורים¹².\nאבער דער פירוש איז צע\"ג, ווארום: א) רש\"י דערמאנט ניט, אפילו ניט ברמז, אז „חל שביעי שלהם להיות ערב פסח\"¹³. ב) זייער טענה איז דאך געווען „אנחנו טמאים גו' למה נגרע גו'\" — ניט אז זיי וועלן זיין טהורים בזמן אכילת הפסח, נאר פארקערט — אז אע\"פ וואס „אנחנו טמאים גו' (פונדעסטוועגן) למה נגרע לבלתי הקריב גו'\"¹⁴.\nב. אנדערע לערנען¹⁵ דעם פשט אין דברי הספרי „והבשר נאכל (יאכל¹⁶) לטהורים\" — „שימנו¹⁷ שאר אנשים עמהם על הפסח ויאכלוהו שאר אנשים\". ד.ה. די זריקה וועט זיין אויך אויף זיי (די טמאים, ובמילא האבן זיי מקריב געווען „קרבן ה' במועדו\") און די אכילת הפסח וועט זיין דורך אנדערע.\n[און אויף דעם ברענגט דער ספרי דעם ק\"ו פון חטאת וואס „דמה נזרק על הטומאה (הטמאים¹⁶) ובשרה נאכל לטהורים\" — כאטש די בעלים (יולדת ומצורע¹⁸) זיינען נאך טמא, פונדעסטוועגן איז „דמה נזרק על הטומאה ובשרה נאכל לטהורים (כהנים טהורים¹⁸)\"].\nועפ\"ז וואלט מען געקענט זאגן אז דאס איז אויך כוונת רש\"י¹⁹ „ויאכל הבשר לטהורים\" — אז אנדערע (וועלכע זיינען ניט ווי „אנחנו טמאים\", נאר) טהורים וועלן עסן דעם פסח.\nאבער לכאורה איז שווער אזוי איינצולערנען אין פירוש רש\"י, ווארום דער עיקר ענין הפסח (אויך ע\"ד הפשט²⁰) איז — אכילת הפסח²¹, וואס דערפאר מוז זיין מינוי — „איש²² לפי אכלו תכוסו על השה\".\nובמילא: וואס איז דער אויפטו פון „יזרק הדם עלינו\", בשעת עס פעלט דער עיקר המצוה — אכילת הפסח?",[["12","12","ולדעת הראב\"ד שם גם על פי הלכה מותרים לזרוק עליהם באופן כזה (אלא ששאלו אחר זמן שחיטה). וכ\"ה דעת התוס' פסחים שם (ושם: דשמא כן עשו כו'). וראה נ\"כ הרמב\"ם שם. רא\"ם ומפרשי רש\"י והספרי בארוכה. ואכ\"מ."],["13","13","וע\"פ פשש\"מ מלכתחילה אין מקום לשאלה מי היו הטמאים לנפש אדם, וכמ\"ש בראב\"ע (ט, ו): לא יתכן כו'."],["14","14","ראה גם באר מים חיים (לאחי המהר\"ל) כאן."],["15","15","זית רענן שם. עמק הנצי\"ב. ועד\"ז בספרי דבי רב שם — בפי' דעת ר' חדקא בשם שמעון השקמוני (שבספרי שם לאח\"ז)."],["16","16","ראה ספרי מהדורת האראוויטץ."],["17","17","ל' הזית רענן."],["18","18","ראה מפרשי הספרי (רבינו הלל. ועוד)."],["19","19","כי הענין ד„דמה נזרק על הטומאה\" הוא גם ע\"פ פשוטו של מקרא — ראה פרש\"י תזריע (יב, ז) „מכלל שעד כאן קרוי' טמאה\" (וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271083\" data-slug=\"likkutei-sichot\" data-id=\"1300271083\">לקו\"ש חכ\"ז ע' 83</a> ואילך), ואינה אוכלת בקדשים (רש\"י שם ד\"ה והקריבו)."],["20","20","וכש\"כ ע\"ד ההלכה — ראה פסחים עו, ב (במשנה): שלא בא מתחילתו אלא לאכילה. וראה שם סא, א ואילך. ועוד. — וגם לדעת ר\"נ דאכילה לא מעכבא ה\"ז רק אכילת הבשר, אבל בעינן גברא דחזי לאכילה (שם עח, ב). ועוד. ואכ\"מ."],["21","21","שהרי רוב הדינים דפסח בפ' בא הם אודות אכילת הפסח, ואדרבה — בפשש\"מ דפ' בא — לא נדבר (בפירוש) כלל אודות „הקרבת\" הפסח (וכדלקמן סעיף ה' בארוכה. וראה לקמן הערה 34 ובשוה\"ג שם)."],["22","22","בא יב, ד ובפרש\"י שם. אבל ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081077\" data-slug=\"likkutei-sichot\" data-id=\"1300081077\">לקו\"ש ח\"ח ע' 67</a> ובהערה 26 שם."]]],[1300281082,"נאך מער: וויבאלד אז מען דארף נמנה ווערן על הפסח (נאך איידער מען ברענגט אים), לייגט זיך בפשטות צו זאגן, אז דער וואס איז ניט בכלל פון „לפי אכלו\", ניט ראוי צו אכילת הפסח קען ניט נמנה ווערן על הפסח, ובמילא קען מען אויף אים ניט זורק זיין דעם דם²³.\n[און ווי מפרשים²⁴ זיינען מבאר, אז דערפאר האט משה רבינו ניט אנגענומען זייער ק\"ו פון חטאת (און געזאגט „עמדו ואשמעה גו'\"²⁵) — ווייל ביי חטאת זיינען דאך די כהנים אוכלים — ניט די בעלים טמאים (און אפילו ביי קדשים קלים וואו ס'איז דא אכילת בעלים — איז דאך די אכילה אן ענין וואס איז ניט מעכב זריקת הדם²⁶),\nאיז במילא ניטא קיין ראי' דערפון אויף קרבן פסח, וואס עיקר מצותו איז אכילת בעלים, אז מען קען זורק זיין אויף בעלים וועלכע זיינען ניט ראוי צו אכילת הפסח].\nועוד — וג\"ז עיקר: בפרש\"י דא איז ניטא קיין רמז אפילו אויף כל הנ\"ל.\nג. וועט מען דאס פארשטיין בהקדם כמה דיוקים בלשון רש\"י:\nא) רש\"י איז מעתיק בלויז די ווערטער „למה נגרע\" און איז אפילו ניט מוסיף „וגו'\" — ולכאורה, מיט זיין פירוש „יזרק הדם כו'\" איז רש\"י מפרש די ווייטערדיקע ווערטער „לבלתי הקריב את קרבן ה'\", וועלכע רש\"י איז, כנ\"ל, אפילו ניט מרמז?\nב) וואס זאגט רש\"י „אמר להם אין קדשים קרבים בטומאה\" — דאס איז דאך א דבר הפשוט וואס אויך זיי האבן זיכער געוואוסט (כנ\"ל סעיף א); האט רש\"י געדארפט אנהויבן פירושו גלייך מיט זייער טענה „אמרו לו יזרק הדם כו'\"²⁷?\nמפרשים²⁸ לערנען אז דאס האט זיי משה פריער געזאגט, בשעת ער האט זיי ניט געלאזט ברענגען דעם פסח (וואס דערפאר זיינען זיי געקומען מיט דער טענה „למה נגרע\"), און זייער טענה „למה נגרע\" איז געקומען דערנאך — „יזרק הדם כו'\".\nאבער פון פשטות המשך לשון רש\"י איז משמע, אז „א\"ל אין קדשים כו'\" איז געקומען אלס ענטפער אויף „למה נגרע\", און ערשט דערנאך איז געקומען א צווייטע שאלה „יזרק הדם עלינו כו'\".\nאיז ניט מובן: (א) אין וואס באשטייט די שאלה „למה נגרע\" (איידער מען זאגט די סברא פון „יזרק הדם גו'\")? ועד\"ז, כנ\"ל — וואס האט זיי משה רבינו מחדש געווען בתשובתו „אין קדשים קרבים כו'\"²⁹? ועוד (ב) פון וואנעט",[["23","23","ראה — ע\"ד ההלכה — הנסמן בהערה 20."],["24","24","משכיל לדוד. ספרי דבי רב לספרי שם. עמק הנצי\"ב שם."],["25","25","פרשתנו שם, ח — וכהמשך דברי הספרי ורש\"י."],["26","26","שלכן גם אם נטמא הבשר זורק הדם (משנה פסחים עח, ב). ועוד."],["27","27","וכן הקשה בדברי דוד (להט\"ז) כאן. וראה הערה 29."],["28","28","ראה גו\"א, דבק טוב ועוד כאן."],["29","29","ברא\"ם כאן „השיב להם מיד אין כו' והם חזרו ואמרו כו' כלומר שמתחלה לא שאלנו אלא על זה\". אבל לכאורה דוחק הוא, דלמה „השיב להם מיד\" ולא המתין לסיום וביאור שאלתם. בדברי דוד מפרש הקס\"ד שלהם ע\"פ פרש\"י לעיל פסוק ב „במועדו אף בטומאה\", ולכן טענו דבודאי יש חילוק בין פסח לשאר קדשים, וא\"כ „למה נגרע מן שאר בני אדם שהתרת\" להביאו בטומאה (וראה גם פי' הרא\"ש וכלי יקר כאן). וע\"ז ענה משה ד„אין קדשים קרבים בטומאה\", ובנוגע לפסח „חילוק אחר"]]],[1300281083,"נעמט רש\"י (מפשוטו של מקרא) אז דא איז געווען (ניט איין שאלה — „למה נגרע לבלתי הקריב גו'\" — נאר) א שקו\"ט צווישן זיי מיט משה — פריער די שאלה „למה נגרע\", דערנאך תשובת משה „אין קדשים כו'\", און דערנאך א צווייטע שאלה „יזרק הדם כו'\"?\nג) „(יזרק הדם עלינו) בכהנים טהורים\" — מאי קמ\"ל? אפילו אויב זיי וואלטן געהאלטן אז זיי מעגן מקריב זיין דעם פסח בטומאה (ניט נאר „יזרק הדם עלינו\"), איז דאך פשוט אז זריקת הדם ע\"ג המזבח ווערט געטאן דוקא דורך כהנים (ובמילא — כהנים טהורים) — וואס איז דא רש\"י מוסיף „בכהנים טהורים\"?\nנאך מער פליאה: די ווערטער שטייען ניט אין ספרי³⁰, נאר זיי זיינען א הוספת ביאור פון רש\"י,\nאיז תמוה: וואס פעלט אין דעם ענין „יזרק הדם עלינו\" וואס רש\"י דארף מוסיף זיין „בכהנים טהורים\"?\nד. דער ביאור בכל זה:\nלערנענדיק דעם פסוק „למה נגרע לבלתי הקריב את קרבן ה' במועדו\" שטעלט זיך גלייך די שאלה: פריער נוצט די תורה כסדר דעם לשון עשיית הפסח (ויעשו בנ\"י את הפסח; תעשו אותו; לעשות את הפסח; ויעשו את הפסח; ולא יכלו לעשות הפסח); פארוואס האבן די טמאים לנפש אדם משנה געווען און געזאגט (ניט „לבלתי עשות הפסח\", נאר) „לבלתי הקריב את קרבן ה'\"?\nאיז דערפון משמע, אז דאס איז אן ענין וואס איז ביי זיי ערשט דא נתחדש געווארן: פריער האט מען נאר געוואוסט אז עס איז דא עשיית הפסח, און איצט איז ביי זיי געווארן א חידוש, אז קרבן הפסח איז אן ענין פון „הקריב את קרבן ה'\". כדלקמן סעיף ה בארוכה.\nוועלכער ענין איז צוגעקומען אינצווישן — פון וועלכן זיי האבן ארויסגעלערנט אט דעם חידוש? איז רש\"י מעתיק פון פסוק „למה נגרע\" און זאגט „אמר להם אין קדשים קרבים בטומאה, אמרו לו יזרק הדם עלינו בכהנים טהורים ויאכל הבשר כו'\":\nדורך מעתיק זיין די ווערטער „למה נגרע\" און ניט מוסיף זיין „וגו'\" מאכט רש\"י קלאר, אז „למה נגרע\" איז געווען א שאלה בפ\"ע, וואס אויף דער שאלה האט זיי משה געענטפערט „אין קדשים קרבים בטומאה\"; און בשעת משה האט זיי געזאגט דעם ענטפער (אז „אין קדשים קרבים בטומאה\") איז ביי זיי נתחדש געווארן אז פסח איז אן ענין פון הקרבת קדשים (קרבן ה') — האט דער חידוש מחדש געווען ביי זיי די (צווייטע) שאלה — וויבאלד „לבלתי³¹ הקריב את קרבן ה'\", איז „יזרק הדם עלינו כו'\".",[["","","יש\" (ומשה חשב שהדין ד„במועדו אף בטומאה\" נאמר רק בצבור). וע\"ז היתה שאלתם „יזרק הדם כו'\", כי אולי החילוק בפסח הוא דכאשר הזריקה בטהורים — „יאכל הבשר לטמאים\". ובאה תשובת הקב\"ה (כדעת משה) „איש איש כי יהי' טמא גו'\" (לקמן פסוק יו\"ד), דהיינו יחידים שאין הטומאה נדחית להם (ו„במועדו אף בטומאה\" היינו בצבור). אבל לכאורה קשה לפרש כן כוונת רש\"י — שלא הזכיר בפירושו כלל (גם לא ברמז) החילוק בין יחיד וצבור* — והרי ע\"פ הנ\"ל זהו התירוץ על טענתם (למה נגרע) הדין ד„במועדו אף בטומאה\"."],["30","30","וגם לא ביל\"ש פרשתנו עה\"פ — אף שתחילת הלשון שם הוא (כפרש\"י) „יזרק הדם עלינו\"."],["31","31","עפ\"ז תומתק — תיבת „לבלתי\", דהל\"ל *) אף שחילוק זה מוכרח הוא בלאה\"כ. וצ\"ל דלפרש\"י מלכתחילה פשוט הוא ד„במועדו אף בטומאה\" קאי רק בצבור (כמו „במועדו אף בשבת\" שהוא בקרבנות הצבור)."]]],[1300281084,"ועפ\"ז איז פארענטפערט וואס רש\"י איז מוסיף די ווערטער „(יזרק כו') בכהנים טהורים\": דערמיט איז רש\"י מדגיש, אז ערשט איצט איז ביי זיי נתחדש געווארן אז פסח איז א „קרבן ה'\" (קדשים) וואס פאדערט זריקה בכהנים טהורים; משא\"כ פריער, בעת'ן טענה'ן „למה נגרע\", האבן זיי גערעכנט אז קרבן הפסח איז ניט קיין קרבן ה' (וואס במילא פאדערט עס ניט קיין זריקה ע\"ג המזבח בכהנים טהורים), און דערפאר האבן זיי געהאלטן אז זיי מעגן דאס ברענגען בטומאה.\nה. די הסברה אין דעם, ובהקדים:\nע\"ד הפשט האט פסח מצרים ניט געהאט קיין גדר פון קרבן: ע\"פ פשוטו של מקרא, איז פסח מצרים געווען א מצוה מיוחדת: צו שחט'ן א שה און עסן אים בליל פסח (צלי אש) צוזאמען מיט מצות ומרורים — ותו לא. דערביי איז ניט געווען קיין ענין וציווי פון הקרבת קרבן לה'³².\n(און דאס וואס עס האט געדארפט זיין „ולקחו³³ מן הדם ונתנו על שתי המזוזות גו'\" איז ניט געווען ע\"ד ווי זריקת הדם על המזבח³⁴, נאר כמפורש בקרא צו מאכן אן אות אויפן בית, אז בשעת „ועברתי בארץ מצרים . . והכיתי גו' וראיתי את הדם גו' ופסחתי עליכם גו'\"³⁵).\nוואס דערפאר געפינט מען ניט ביי פסח מצרים אז עס זאל אנגערופן ווערן בשם קרבן³⁶, נאר בלויז בשם „זבח\" („ואמרתם זבח פסח הוא\"³⁷) — וואס דער ווארט „זבח\" מיינט ניט דוקא א קרבן לה', נאר יעדע שחיטה לאכילה ווערט גערופן זבח³⁸.\nאון דאס איז געווען די טענה פון די טמאים לנפש אדם:\nדא רעדט זיך דאך וועגן דער „שנה השנית לצאתם מארץ מצרים\"³⁹, וואס פאר דעם איז בלויז געווען איין פסח, דער פסח מצרים. איז דערפון פארשטאנדיק, אז בשעת מ'האט אנגעזאגט „ויעשו בנ\"י את הפסח במועדו . . ככל חוקותיו וככל משפטיו תעשו אותו\"⁴⁰ — האט עס געמיינט, אז דער פסח מדבר זאל זיין אין דעם זעלבן אופן וגדר פון פסח מצרים.\n[ובפרט ע\"פ פרש\"י לעיל⁴¹ „תלה הכתוב מצוה זו בביאתם לארץ ולא נתחייבו במדבר אלא בפסח אחד שעשו",[["","","(בקיצור) „למה נגרע מלהקריב\" — כי בזה מודגש שכאן מתחיל ענין חדש."],["32","32","ע\"ד ההלכה — ראה פסחים צו, א. צפע\"נ עה\"ת בא יב, ז. וראה הערה 34."],["33","33","בא שם."],["34","34","ואף שפרש\"י שם „זו קבלת הדם\", ובפרש\"י שם, כב: לשלש המתנות (וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181003\" data-slug=\"likkutei-sichot\" data-id=\"1300181003\">לקו\"ש חי\"ח ס\"ע 3</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261078\" data-slug=\"likkutei-sichot\" data-id=\"1300261078\">חכ\"ו ע' 78</a>. וש\"נ) — ע\"ד הפשט ה\"ז רק דוגמת עבודת הקבלה וזריקה* (וכן יש איסור נותר — שם, י), אבל אין כאן ענין של הקרבה לה' בפועל [ולשון הכתוב (בא שם, יא. שם, כז) „פסח הוא לה'\" — היינו כי „קרוי פסח על שם . . שהקב\"ה מדלג כו'\" (פרש\"י שם, יא. וראה לקמן הערה 36). או מפני שעושה בזה מצות ה']."],["35","35","בא שם, יב־יג. וכן שם, כג."],["36","36","ורק בפרש\"י (בא שם, יא) „הקרבן הוא קרוי פסח כו'\", אבל י\"ל הכוונה שהוא דוגמת קרבן, ע\"ד הנ\"ל הערה 34."],["37","37","בא שם, כז."],["38","38","ראה לעיל ויצא (לא, נד) ובפרש\"י שם. ועד\"ז בכ\"מ."],["39","39","פרשתנו ט, א."],["40","40","שם, ב־ג. וראה פרש\"י שם ובמפרשיו."],["41","41","בא יב, כה. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231065\" data-slug=\"likkutei-sichot\" data-id=\"1300231065\">לקו\"ש חכ\"ג ע' 65</a> ואילך (אבל ראה שם ע' 69 הערה 51). *) ולהעיר מס' זכרון על מ\"ש רש\"י כאן „יזרק הדם\": וא\"ת והרי לא מצינו שנזכר בפסח שום זריקת הדם בכתוב"]]],[1300281085,"בשנה השנית על פי הדבור\", לייגט זיך צו זאגן אז דער פסח מדבר האט ניט געהאט דעם גדר פון פסח דורות (וועלכער איז פארבונדן מיט „ביאתם לארץ\"), נאר ס'איז געווען א המשך פון פסח מצרים (און בא די וועלכע האבן געמאכט⁴² פסח מצרים)].\nועפ\"ז — האבן די אנשים הנ\"ל געטענה'ט — דארף מען זאגן, אז דער ציווי „ויעשו בנ\"י את הפסח במועדו\" מיינט עשיית הפסח פונקט ווי פסח מצרים⁴³, וועלכער איז ניט קיין קרבן וואס ווערט געבראכט ע\"ג המזבח, נאר אדרבא יעדערער — אפילו טמאים⁴⁴ — איז זובח א שה (בביתו — לעבן זיין משקוף והמזוזות⁴⁵) און עסט עס בביתו דוקא, בליל חמשה עשר בניסן (צוזאמען און פונקט ווי ער עסט מצה ומרור — שאינם קדשים כלל). און דעריבער, ווען משה האט זיי ניט געלאזן זיך צו משתתף זיין אין עשיית הפסח⁴⁶, זיינען זיי געקומען מיט דער טענה „למה נגרע\"⁴⁷.\nאון דאס האט משה זיי מחדש געווען — „אין קדשים קרבים בטומאה\": פסח איז ניט בלויז א זבח, נאר קדשים וואס ווערן נקרב ע\"ג המזבח, ובמילא — איז אייער שאלה בענין וואס דער ענטפער איז: אין קדשים קרבים בטומאה.\nו. עפ\"ז וועט מען אויך פארשטיין זייער (צווייטע) שאלה — „יזרק הדם עלינו כו' ויאכל הבשר לטהורים\" (און היות אז זיי זיינען געווען „טמאים לנפש אדם\", דארף מען זאגן, אז רש\"י מיינט דערמיט אנדערע טהורים, כנ\"ל סעיף ב):\nוויבאלד אז ביי פסח מצרים איז ניט געווען קיין ענין פון הקרבה לה' (ע\"ג המזבח) נאר בלויז די מצוה בפ\"ע פון (זבח ו)אכילת הפסח — האבן די טמאים לנפש אדם געהאלטן, אז דאס וואס יעצט (נאך הקמת המשכן) איז עס א גדר קרבן, איז דאס א צוגעקומענער באזונדער ענין, וועלכער איז ניט גורע, ופשיטא ניט שולל, די מצוה פון אכילת הפסח ווי ס'איז געווען בא פסח ביז יעצט. און פארוואס זאל דען ווערן א",[["42","42","או בסמיכות ממש לגיל (דקטן) הראוי להמנות על פסח מצרים."],["43","43","שלכן גם את\"ל שידעו אודות פסח דורות (וראה פרש\"י בא יב, ו. שם, מז) ושהוא נקרב ע\"ג מזבח (ראה משפטים כג, יח. תשא לד, כה. ולהעיר גם מרש\"י תולדות כז, ט) — ס\"ל שפסח מדבר הי' בגדר (ובמילא — כדיני) פסח מצרים, כנ\"ל. ולהעיר — גם בנוגע לפסח דורות — מדעת היראים (סת\"ה. ובהשלם — סתט\"ו) דמצות ק\"פ היא: צוה הקב\"ה את ישראל שיעשו את הפסח . . ועשיית הפסח היינו שחיטתו וזריקת דמו והקטר אימוריו . . ואע\"פ שזריקת דמו כו' כהנים עושין ולא ישראל כיון שהקרבן של ישראל ובמצות ישראל עושין כו'."],["44","44","והצורך בהציווי „במועדו\" (לדעתם) הי' (לא בשביל „אף בטומאה\" — שהרי חשבו שאינו קרבן — כ\"א) בשביל „אף בשבת\"."],["45","45","ואף שלקמן בפ' ראה (יב, כ) פרש\"י ד„במדבר נאסר להם בשר חולין אא\"כ מקדישה ומקריבה שלמים\" (אבל ראה פרש\"י אחרי יז, ג: במוקדשין הכתוב מדבר, ובמפרשי רש\"י שם. וראה מפרשי רש\"י ראה שם) — ה\"ז רק (ע\"ד לשון רש\"י ראה שם בד\"ה שלפנ\"ז) בשר תאוה, משא\"כ בנדו\"ד שהמדובר בזבח מצוה."],["46","46","אבל לפ\"ז צ\"ל לכאורה שבאו לשאול קודם זמן שחיטת הפסח, שעדיין לא ידעו שנקרב ע\"ג המזבח, ומפשטות הכתובים לא משמע כן (וראה הנסמן בהערה 12). ואולי י\"ל שטענתם היתה, דאף ששאר בנ\"י הטהורים הקריבוהו בפועל ע\"ג המזבח, מ\"מ אין זה מוכרח מצד גדר הפסח (וע\"ד שנאסר להם בשר חולין, כנ\"ל הערה הקודמת), ולכן טמאים יכולים לעשותו בטומאה (בלי הקרבה)."],["47","47","ולהעיר מחזקוני כאן „למה אין אנו רשאין לאכול קדשים בטומאה הרי אשתקד אכלנו הפסח במצרים אפילו בטומאה\". וראה באר מים חיים כאן."]]],[1300281086,"שינוי (ובפרט א שלילה) אין מצות אכילת הפסח?!\nקומט אויס, אז אין פסח זיינען פאראן צוויי באזונדערע ענינים (וועלכע זיינען ניט תלוי זה בזה)⁴⁸: א) מען ברענגט א קרבן לה' (אויפן מזבח) אלס זכר (והודי') אויפן ענין פון גאולת מצרים, „ופסח ה'\". ב) עס איז דא די מצוה פון אכילת הפסח בליל ט\"ו — (ניט אלס אכילת קרבן דוקא, נאר) ע\"ד ווי די מצוה פון אכילת מצה ומרור.\nאון דאס האבן זיי געטענה'ט „לבלתי הקריב את קרבן ה' במועדו\": וויבאלד אז דער ענין וואס פסח איז „קרבן ה'\" איז א באזונדער ענין פון אכילת הפסח, איז — „יזרק הדם עלינו כו' ויאכל הבשר לטהורים\":\nאע\"פ וואס זייענדיק א „קרבן לה'\" (קדשים) טארן זיי ניט עסן פון דעם פסח (ווייל א טמא טאר ניט עסן קיין קדשים) — ובמילא „יאכל הבשר לטהורים (אחרים)\" — פארוואס זאלן זיי אבער דארפן פארפעלן דעם נייעם צוגעקומענעם ענין אין פסח — „להקריב את קרבן ה' במועדו\", וואס קען געטאן ווערן בלי זייער אריינגיין אין משכן⁴⁸*, ובמילא — „יזרק הדם עלינו בכהנים טהורים\"⁴⁹.\nז. לויט דעם ביאור אין פירוש רש\"י קען מען אויך מקיים זיין די גירסת הספרים „ויאכל הבשר לטמאים\"⁵⁰ (וואס פון דעם גופא וואס כו\"כ מפרשי רש\"י פאריכטן די גירסא⁵¹, איז מוכח, אז שוין בימיהם איז געווען די גירסא הנפוצה „לטמאים\")\n— ובפרט ע\"פ המדובר כמה פעמים אז בשעת מען וויל מברר זיין וואס עס איז דער נוסח האמיתי, דארף מען חוקר זיין פון וואנעט, ווי אזוי קען קומען א טעות — מען מאכט ניט קיין טעות במזיד.\nובנדו\"ד: אויב מ'זאל זאגן אז אין רש\"י איז געשטאנען „לטמאים\", איז פארשטאנדיק פארוואס א מעתיק (או מדפיס) האט עס געביטן צו „לטהורים\"; אויב אבער ס'איז געשטאנען „לטהורים\" — פארוואס זאל ווער עס איז דאס משנה זיין און שרייבן „לטמאים\", וואס איז (א) היפך נוסח הספרי, און (ב) ועיקר: היפך דעם דין מפורש ומפורסם לכל, אז א טמא טאר ניט עסן קיין קדשים⁵²?! —\nאיז דער ביאור בזה: וויבאלד אז די מצוה פון אכילת הפסח איז (לפי סברת האנשים ההמה) ניט א גדר פון אכילת קרבן נאר א מצוה בפ\"ע (ניט פארבונדן מיט הקרבת קרבן) — האט אן ארט צו זאגן (לויטן לימוד ע\"ד הפשט) אז דער",[["48","48","ולהעיר גם ע\"ד ההלכה דשחיטת הפסח ואכילתו הן שתי מצות (סהמ\"צ להרמב\"ם מ\"ע נה־נו. ועוד) — כידוע השקו\"ט בזה (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161102\" data-slug=\"likkutei-sichot\" data-id=\"1300161102\">לקו\"ש חט\"ז ע' 102</a> ואילך. וש\"נ). 48*) ראה לעיל הערה 19."],["49","49","אלא שלפי המסקנא אינו כן — כי שני הענינים בק\"פ (הקרבתו ואכילתו) תלויים זב\"ז וא\"א להפריד ביניהם (כנ\"ל סעיף ב), ולכן הוצרך להיות הציווי דפסח שני."],["50","50","וכ\"ה לפי הדברי דוד (הנ\"ל הערה 29)."],["51","51","נסמן לעיל הערה 6."],["52","52","בנחלת יעקב כאן: „ואיזה תלמיד טועה כתב כן לפי שראה שאנשים היו טמאים והפסח נאכל לבעלים דוקא . . לפי' כתב ויאכל הבשר לטמאים\", אבל צ\"ע שיטעה בדבר הפשוט שטמא מותר באכילת קדשים, כבפנים."]]],[1300281087,"בשר הפסח קען געגעסן ווערן אפילו בטומאה.\nדאס וואס די תורה אסר'ט א טמא צו עסן קדשים, איז דוקא ווען ער עסט עס אלס אכילת קדשים. וכדיוק לשון הכתוב⁵³ „והנפש אשר תאכל בשר מזבח השלמים אשר לה' וטומאתו עליו\". משא\"כ אכילת הפסח איז (ניט אלס אכילת קדשים, נאר) אלס א מצוה בפ\"ע (וואס תורה האט אנגעזאגט ווען ס'איז ניט געווען קדשים),\nהאט דערפאר אן ארט צו זאגן, אז אין דעם פאל קען עס געגעסן ווערן אפילו בטומאה.\nח. לויט דעם ביאור — להגירסא „ויאכל הבשר לטמאים\" — איז אבער לכאורה ניט גלאטיק: וויבאלד אז זיי האבן געהאלטן אז זיי וועלן אויך האבן די מצוה פון אכילת הפסח — פארוואס האבן זיי געמאנט בלויז „לבלתי הקריב את קרבן ה' במועדו\", ניט דערמאנענדיק דעם ענין האכילה⁵⁴?\nאיז דער ענין אין דעם⁵⁵: בשעת זיי האבן געהערט אז דער ענין פון פסח איז א קרבן ה' — איז דאס געווארן ביי זיי דער עיקר הענין פון פסח; ביי זיי האט שלא בערך מער תופס מקום געווען דאס וואס זיי האבן די מעגליכקייט צו מקריב זיין „קרבן ה' במועדו\" (כאטש דאס וועט געטאן ווערן דורך אנדערע), ווי די מצוה וואס איז פארבונדן מיט זייער אכילה, אכילת הפסח.\nווייל דער גרעסטער תענוג בא זיי (פון א אידן) איז, בשעת ער טוט אויף דעם („לחמי לאשי\"⁵⁶, וואס איז גורם דעם „אשה ריח ניחוח לה'\"⁵⁷) — „נחת רוח לפני שאמרתי ונעשה רצוני\"⁵⁸.\nט. ובעבודה ובפנימיות:\nדער ענין — אז מ'האט געמאנט נאר דעם „הקריב את קרבן ה'\" — איז ווי עס איז מצד דעם אידן. בשעת אבער דער אויבערשטער האט אנגעזאגט אידן אויף פסח שני, אז מען קען משלים זיין⁵⁹ דעם ענין הפסח — איז דער עיקר הדגשה (ניט אזוי אויפן ענין הקרבן — „פסח לה'\"⁶⁰ — נאר) אויף עשיית הפסח און אכילת הפסח⁶¹\n— ווייל עיקר כוונת הפסח איז ניט אזוי די הקרבה ע\"ג המזבח, העלאה ממטה למעלה — מעלה זיין דעם חלב ודם ע\"ג המזבח, אלס קרבן לה', נאר דוקא די המשכה למטה, אין גוף הגשמי, אכילת האדם. דוקא דורך דעם פירט זיך דורך די כוונת הבריאה, לעשות לו יתברך דירה בתחתונים.\n(משיחות ש\"פ שלח וש\"פ פינחס תשכ\"ו)",[["53","53","צו ז, כ. ועד\"ז שם, כא."],["54","54","וכן קשה להפירוש שהובא לעיל סעיף א."],["55","55","וע\"פ המבואר בפנים בפרש\"י י\"ל בפשטות, דמכיון שמשה חידש להם שהפסח הוא קרבן ה' (קדשים) שלכן אינו נקרב בטומאה, לכן הדגישו בשאלתם הב' פרט זה — „לבלתי הקריב גו'\", שגם מצד ענין הקרבן יכולים לעשותו."],["56","56","ל' הכתוב פינחס כח, ב. וראה אמור כא, ו. שם, ח. ובכ\"מ."],["57","57","ויקרא א, ט. ובכ\"מ."],["58","58","פרש\"י ויקרא שם. פינחס כח, ח."],["59","59","משא\"כ כשהמדובר במי ש„חדל לעשות הפסח\", שלכן ונכרתה הנפש גו' — מבאר הכתוב הטעם „כי קרבן ה' לא הקריב במועדו\" (פרשתנו ט, יג)."],["60","60","כלשון הכתוב פרשתנו ט, י. שם, יד."],["61","61","שם, י־יא."]]],[1300281088,"<h3>י\"ב סיון</h3>\nא. דער אַלטער רבי פסק'נט בסידורו¹ אַז מען זאָגט ניט קיין תחנון — „מר\"ח סיון עד י\"ב² בו ועד בכלל דהיינו ה' ימים אחר חג השבועות כי החג יש לו תשלומין כל שבעה\" — און ווי די גמרא³ לערנט עס אָפּ (אַז אויך חגה\"ש האָט תשלומין) פון פסוק⁴ „בחג המצות ובחג השבועות ובחג הסוכות\" — מקיש חג השבועות לחג המצות מה חג המצות יש לה תשלומין כל שבעה אף חג השבועות יש לה תשלומין כל שבעה.\nדאַרף מען פאַרשטיין: ביי חג המצות און חג הסוכות זיינען די ימי התשלומין אין טעג וועלכע זיינען אַ טייל פון דעם חג, טעג פון חול המועד והחג. און בכמה ענינים זיינען זיי יו\"ט⁵; משא\"כ ביי חג השבועות זיינען די ימי התשלומין „חול גמור\"⁶. איז ניט גלאַטיק: ווי אַזוי קען מען אָפּלערנען תשלומין פון חג השבועות פון די תשלומין של פסח וסוכות, בשעת אַז ביי חג השבועות קומט צו אַ חידוש גדול — מקריב זיין קרבן החג ביום חול גמור?\nנאָך מער: ביי די תשלומין פון פסח וסוכות איז פאַראַן אַ פלוגתא⁷ צי „תשלומין לראשון\" אָדער „תשלומין זה לזה\": „תשלומין לראשון\" מיינט אַז „יום אחד עשה הכתוב עיקר בכולן\"⁸ [און דערפאַר, איינער וואָס איז ניט געווען אַ בר חיובא ביום ראשון און ערשט אין די שפעטערדיקע טעג איז ער געוואָרן אַ בר חיובא, איז ער ניט מחוייב צו ברענגען די קרבנות, ווייל בשעת החיוב (ביום ראשון) איז ער ניט געווען קיין בר חיובא]; און „תשלומין זה לזה\" מיינט אַז „אין לך יום בהם שאין חובתו תלוי' בו בעצמו\"⁹ (און דעריבער, אפילו איינער וואָס איז ניט ראוי צו ברענגען דעם קרבן ביום ראשון, ווערט אויף אים אַ חיוב אין דעם יום שלאח\"ז).\nשטייט אין תוספות⁶, אַז אָט־די פלוגתא איז בלויז ביי פסח וסוכות, אָבער ביי עצרת וואָס די ימי התשלומין זיינען „חול גמור\" איז „לא מסתבר למימר תשלומין זה לזה\" (אַז אין די ימי החול שלאחרי היו\"ט זאָל זיין „חובתו תלוי' בו בעצמו\").\nקומט אויס, אַז די תשלומין פון שבועות האָבן (לויטן מ\"ד „תשלומין זה לזה\") אַן אַנדער גדר ווי די תשלומין פון פסח וסוכות — איז דאָך ניטאָ אַ היקש (גמור) פון חה\"ש צו די צוויי¹⁰?",[["1","1","לפני ובא לציון — ודלא כמ\"ש בשו\"ע שלו (או\"ח סו\"ס תצד) דא\"א תחנון (רק) עד ח' בו."],["2","2","ודלא כי\"א דגם בי\"ג משום ספיקא דיומא (הובא בשע\"ת או\"ח סקל\"א סקי\"ט). וי\"ל טעמי' דאדה\"ז, מפני דכל ענין תשלומין אלו הוא רק בענין קרבנות, ולית תמן ספיקא דיומא. וראה שיחת ליל י\"ב סיון תשד\"מ."],["3","3","חגיגה יז, א (וש\"נ). וראה רמב\"ם הל' חגיגה פ\"א ה\"ז."],["4","4","ראה טז, טז."],["5","5","ראה שו\"ע אדה\"ז או\"ח סתקכ\"ט ס\"י דחג הם. וראה מ\"מ לשו\"ע שלו (על הגליון) סי' רמב ס\"א דלענין קרבנות (שזהו ענין התשלומין) קרוי גם מקרא קדש. וראה אנציקלופדי' תלמודית ערך חול המועד בתחלתו. וש\"נ."],["6","6","תוד\"ה תשלומין — חגיגה ט, א."],["7","7","חגיגה ב, א. שם ט, א. וראה ירושלמי שם פ\"א ה\"א ובמפרשים שם."],["8","8","רש\"י ד\"ה כולן תשלומין לראשון, חגיגה ט, א."],["9","9","רש\"י חגיגה שם ד\"ה כולן תשלומין זל\"ז. וראה גם רש\"י שם ב, א ד\"ה הניחא; לשון הירושלמי שם."],["10","10","כן הקשה בשפת אמת לחגיגה יז, א. וראה גם שו\"ת חת\"ס ח\"ו סכ\"ח."]]],[1300281089,"ב. ויש לומר דעם ביאור אין דעם:\nדער ענין פון תשלומין איז בהתאם צום תוכן היו\"ט. ועד\"ז ביי חג השבועות: דאָס וואָס די ימי התשלומין פון חג השבועות זיינען אין ימות החול, איז ניט אַ בדרך ממילא ענין — וויבאַלד שבועות איז בלויז איין טאָג איז מוכרח אַז די ימי התשלומין פון שבועות זיינען בימי החול — נאָר דאָס איז בדיוק: דער תוכן פון שבועות איז גורם אַז די תשלומין שלו זאָלן זיין אין ימות החול (כדלקמן סעיף יא).\n[נאָך מער: וויבאַלד אַז אַלע עניני התורה זיינען בתכלית הדיוק, דאַרף מען זאָגן, אַז אַזוי ווי בפשטות הענינים, זיינען די ימי התשלומין פון שבועות ימי החול דערפאַר וואָס שבועות איז יום אחד — עד\"ז בתוכן הענינים, אַז אָט־דער תוכן אין חג השבועות וואָס איז מחייב אַז די תשלומין שלו זאָלן זיין בימי החול, איז ער אויך פאַרבונדן מיט דעם וואָס חג השבועות איז יום אחד].\nאון דערפאַר קען מען אָפּלערנען די תשלומין פון שבועות פון פסח וסוכות (אויך לויט דער דיעה אַז „תשלומין זל\"ז\"): דער לימוד איז אויף דעם כללות הענין אַז אויך ביי חג השבועות איז דאָ אַן ענין פון תשלומין; אָבער נאָך דעם ווי מען ווייס אַז אויך ביי חגה\"ש איז דאָ תשלומין, איז „אוקי באתרא\"¹¹, אַז דער גדר התשלומין שלו איז בהתאם צום תוכן פון שבועות.\nג. ענין הנ\"ל — אַז דאָס וואָס די תשלומין פון חגה\"ש זיינען אין ימי החול איז פאַרבונדן מיטן תוכן החג, איז נאָך מער מוכרח לויטן ביאור אין דעם לשון חז\"ל הנ\"ל (בנוגע ימי התשלומין פון די ג' רגלים) — „תשלומין כל שבעה\". דלכאורה תמוה:\nהקרבת קרבנות החג אין יו\"ט ראשון איז דאָך ניט קיין תשלומין, נאָר דאָס איז זמן חיובם, עיקר החיוב¹²; ובפרט לויט דער (דעה ו)הלכה¹³ אַז „כולן תשלומין לראשון\", איז דאָך זיכער אַז עיקר החיוב איז ביום הראשון — איז ווי זאָגט מען „תשלומין כל שבעה\", בשעת תשלומין איז נאָר אין די ששה ימים וואָס קומען נאָכן יום ראשון¹⁴?\nאיינער פון די ביאורים אין דעם¹⁵: עס איז דאָ אַן אונטערשייד צווישן דעם ענין התשלומין ביי קרבנות החג און דעם ענין התשלומין ביי אַנדערע עניני תורה:\nבכלל איז דער באַדייט פון תשלומין — אַז מ'איז משלים אַ דבר חסר. ד.ה. מ'איז משלים אַ זאַך וואָס מ'האָט פריער פאַרפעלט. איז דערפון גופא פאַרשטאַנדיק, אַז דער ענין פון תשלומין איז אַ „בדיעבד'דיקער\" ענין, דאָס איז ניט דער זמן פון דעם ענין.\n[ולדוגמא — דער ענין פון פסח שני, וואָס מען דאַרף ברענגען „את הפסח במועדו, תעשו אותו במועדו\"¹⁶, ס'איז נאָר אַז אויב איינער האָט פאַרפעלט דעם חיוב, גיט אים דאַמאָלס תורה אַ מעגלעכקייט דאָס צו משלים זיין בזמן",[["11","11","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231022\" data-slug=\"likkutei-sichot\" data-id=\"1300231022\">לקו\"ש חכ\"ג (ע' 22</a> ואילך) דוגמאות מכמה ענינים בתורה עד\"ז."],["12","12","ראה חגיגה ז, א „בעיקר הרגל\" (וברש\"י שם). וראה רש\"י ד\"ה ביו\"ט (שם, ב) דעיקר מצותן ביום ראשון (וראה לקמן הערה 27). וראה שם ט, א: אותו אתה חוגג . . למה נאמר שבעה לתשלומין."],["13","13","רמב\"ם הל' חגיגה פ\"א ה\"ד. שם פ\"ב ה\"ה."],["14","14","ולהעיר מלשון הרמב\"ם שם פ\"א ה\"ז: ויש לו תשלומין כל ששת ימים שלאחר חגה\"ש."],["15","15","ראה עוד ביאור — שיחת ליל י\"ב סיון תשמ\"ב."],["16","16","בהעלתך ט, ב. שם, ג."]]],[1300281090,"אחר — בפסח שני¹⁷. אָבער מלכתחילה טאָר מען זיך ניט סומך זיין אויף פסח שני, ווייל מען דאַרף מקריב זיין דעם פסח ראשון אין זיין זמן — י\"ד ניסן].\nאָבער די ימי תשלומין פון די קרבנות החג זיינען אַנדערש — ביי זיי גיט תורה מלכתחילה שבעת ימים אויף ברענגען דעם קרבן, אַזוי, אַז דער זמן הקרבן איז מלכתחילה שבעת ימים.\nואע\"פ אַז דער וואָס קען מקדים זיין און ברענגען זיין קרבן ביום ראשון של חג טאָר ניט מאחר זיין און ברענגען דעם קרבן אין די תשלומין טעג, און ווי דער רמב\"ם פסק'נט¹⁸ „מצוה להקדים ולהקריב בראשון . . וכל המאחר הרי זה מגונה ועליו נאמר¹⁹ נוגי ממועד אספתי\" — איז דאָס אָבער ניט אַ דין מצד דעם זמן הקרבן (אַז מ'האָט פאַרפעלט ברענגען דעם קרבן בזמן הקרבן), נאָר בלויז אַז דער מאחר איז מגונה, חסרון בהגברא²⁰: דער מאחר זיין בשעת מען קען מקדים זיין, איז אַ הנהגת הגברא „מגונה\". אָבער אויך ווען מען ברענגט אים באיחור, נאָך דעם יום ראשון, איז עס אַ קרבן „בזמנו\"²¹.",[["17","17","ואין זה שייך להפלוגתא (פסחים צג, א-ב. הובאה בחגיגה וירושלמי שנסמנו בסוף ההערה) אי פ\"ש הוי תשלומין דראשון או תקנתא דראשון או רגל בפ\"ע — כי לכו\"ע ענינו של פ\"ש בפשטות הוא (כפשוטו של מקרא) עבור זה שלא הקריב קרבן פסח במועדו ובא להשלים חיובו [אלא שלמ\"ד רגל בפ\"ע גם אם לא הי' חייב בראשון מביא פ\"ש (פסחים שם). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181135\" data-slug=\"likkutei-sichot\" data-id=\"1300181135\">לקו\"ש חי\"ח ע' 126</a> ואילך]. ולכו\"ע אסור לאדם לסמוך לכתחילה על פסח שני ולא להביא פסח ראשון [כי גם למ\"ד תקנתא דראשון ואינו חייב כרת עד שלא יקריב בשני — ה\"ז בגדר „תקנתא\"*, תיקון העבר]. ומובן ג\"כ, דאף שבעיקר ענינו התשלומין דקרבנות החג שונה מפסח שני (כדלקמן בפנים) — אין זה סותר שלמדין כמה פרטים זמ\"ז (ראה חגיגה ט, סע\"א ואילך. ירושלמי חגיגה שם. ועוד). ואכ\"מ."],["18","18","הל' חגיגה פ\"א ה\"ה. *) לדעת הרמב\"ם (הל' ק\"פ פ\"ה ה\"א-ב) כ\"ה גם למ\"ד רגל בפ\"ע, ובצפע\"נ לרמב\"ם בתחלתו (א, סע\"ב) דלשיטת הרמב\"ם גם פסח שני לא הוי גדר השלמה. אבל לכאורה אין כוונתו בזה שזהו כמו ז' ימי החג להסברא ד„חד זמן הוא\" (ראה לקמן הערה 21), שהרי (גם) בס' היד נמנו פסח ראשון ופ\"ש כשתי מצות (ראה הכותרת להל' ק\"פ. שם פ\"ה ה\"א). ולכאורה כוונתו רק שפ\"ש נקרא „זמן\" קרבן, אבל הוא זמן בפ\"ע. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181137\" data-slug=\"likkutei-sichot\" data-id=\"1300181137\">לקו\"ש חי\"ח ע' 128</a> ואילך. ואכ\"מ."],["19","19","צפני' ג, יח."],["20","20","ראה יתירה מזו טורי אבן לר\"ה (ד, ב ד\"ה ורבנן. וכן טו\"א לחגיגה ט, ב ד\"ה אלא למ\"ד) ד„לאו איסורא איכא למאחר אלא זירוז בעלמא הוא מדרבנן משום דזריזין מקדימים למצות\". וראה מגילה ה, סע\"א וברש\"י שם ד\"ה כ\"ז חגיגה. פני יהושע למשנה מגילה שם. ולהעיר מחגיגה ז, ריש ע\"ב: פושעים . . זריזין (וברש\"י שם). אבל גם את\"ל שלדעת הרמב\"ם הוא איסור גמור, לכאורה ה\"ז ענין רק בהגברא, ולא שחסר בזמן ההקרבה. [בהגהות יד איתן והר המורי' לרמב\"ם שם, דמקור הרמב\"ם הוא מברכות כח, סע\"א: דאחרו זמני מועדיא דבירושלים. ולפ\"ז צ\"ל לכאו' שחסר בזמן הקרבן. אבל מלשון הרמב\"ם „ה\"ז מגונה\" משמע שהחסרון הוא רק מצד הגברא (ולא שחסר בזמן הקרבן). ולהעיר מצפע\"נ הפלאה בהשמטות (נד, ג) דשחרית הוא „זמן נמשך\" (ולא זמן תשלומין) ומ\"מ שייך בי' „נוגי ממועד גו'\" אלא רק „לישנא דצערא הוא\" (ברכות שם). ע\"ש. ואכ\"מ]."],["21","21","ראה גם טורי אבן ופנ\"י (שבהערה הקודמת). ולהעיר מצפע\"נ לרמב\"ם בתחלתו (א, סע\"ב. וכן בהשמטות לשם — בצפע\"נ הפלאה בסופו (נד, ד). מהד\"ת כו, א) דיש מ\"ד בירושלמי חגיגה פ\"א דכל ז' ימי החג הוי זמן חגיגה ולא גדר השלמה, „גדר נמשך וחד זמן הוא\". אבל ע\"פ המבואר לקמן בפנים (סעיף ה) דגדר התשלומין כאן הוא רק מצד הגברא — י\"ל דלכו\"ע הוי זמן חגיגה, גם למ\"ד תשלומין דראשון (כדלקמן שם והערה 28). במאירי למשנה חגיגה (ט, א. ועד\"ז במאירי פסחים עא, א) „שיש לקרבנות . . תשלומין . . שלא נאמר עליו עבר יומו בטל קרבנו אלא יש לו תשלומין כל ז'\", ומשמע שזמן התשלומין אינו „יומו\" (וראה לשונו שהועתק לקמן הערה 28). אבל י\"ל שלאחרי שהתורה חידשה שיש תשלומין, שוב ה\"ז „יומו\" וזמנו. ועצ\"ע."]]],[1300281091,"ד. אַ הוכחה אויף דעם:\nאיינער פון די קרבנות אין וועלכע מ'איז מחוייב בימי הרגל איז עולת ראי'²². און וויבאַלד דאָס איז אַ קרבן עולה וועלכער איז כולו לה'²³, האַלטן בית שמאי אַז מען טאָר עס ניט מקריב זיין ביו\"ט²⁴, ווייל עס איז ניטאָ דערביי קיין צורך „אוכל נפש\", דאָ איז בלויז פאַראַן אכילת גבוה אָבער ניט „לכם\"²⁵. און לשיטתם ברענגט מען די עולות ראי' ערשט במוצאי יו\"ט ראשון.\nאיז לכאורה תמוה ביותר — לויט ב\"ש קומט אויס אַ דבר והיפוכו: תורה איז מחייב אַ אידן אין אַ קרבן און זאָגט אַז עיקר החיוב איז ביו\"ט ראשון, און צוזאַמען דערמיט אסר'ט תורה אַ אידן צו ברענגען דעם קרבן בזמן פון עיקר החיוב, נאָר הייסט אים ברענגען בזמן תשלומין!\n[און לויט ווי דער אַלטער רבי שרייבט בשולחן ערוך שלו²⁶ — האָבן אויך בית הלל (און „הרבה מישראל\") זיך געפירט אין דעם ענין ווי ב\"ש און געבראַכט די עולות ראי' במוצאי יו\"ט].\nנאָך מער: בחג השבועות קומט גאָר אויס, אַז די הקרבה פון עולת ראי' של יו\"ט איז דוקא בימי החול — נאָכדעם ווי דער יו\"ט איז שוין אדורך!\nאיז דערפון גופא געדרונגען²⁶*, אַז דער ענין פון תשלומין בנוגע די קרבנות החג איז ניט אַן ענין פון בדיעבד, נאָר דאָס איז מלכתחילה זמן הקרבן. און דעריבער האַלטן ב\"ש²⁷ אַז מ'טאָר ניט דוחה זיין יו\"ט צוליב הקרבת עולת ראי' ביי וועלכע עס איז ניטאָ קיין צורך אוכל נפש, ווייל אויך למחרתו איז עס בזמנו.\nה. ועפ\"ז יובן דער לשון „תשלומין כל שבעה\":\nע\"פ הנ\"ל אַז אַלע שבעת ימים זיינען „זמן\" הקרבן, דאַרף מען זאָגן, אַז דער גדר פון תשלומין אין דעם ענין איז בלויז מצד ה„גברא\". ד.ה. אַז אפילו איינער וואָס אים פעלט זריזות און האָט ניט מקריב געווען ביום ראשון — גיט אים תורה די אפשריות צו משלים זיין און ברענגען די קרבנות אין די ימים שלאח\"ז.\n[ס'איז ניט קיין סתירה פון דער הלכה¹³ אַז „כולן תשלומין לראשון\" פון וועלכער ס'איז משמע אַז דער עיקר החיוב איז ביום ראשון און די שפעטערדיקע טעג זיינען בלויז „תשלומין\" —",[["22","22","ריש חגיגה. שם ו, ב. רמב\"ם ריש הל' חגיגה."],["23","23","ראה חגיגה שם (ו, ב) „שהראיי' עולה כולה לגבוה\"."],["24","24","ביצה יט, א. חגיגה ז, ב. יז, א."],["25","25","פרש\"י (במקומות שבהערה הקודמת) — ע\"פ ביצה (כ, ב). וראה רש\"י חגיגה יז, א ד\"ה יום טבוח (ובתוס' שם) דלב\"ש גם החגיגה אינה קריבה ביו\"ט. ואכ\"מ."],["26","26","או\"ח סתצ\"ד סי\"ט. — מקורו של אדה\"ז נת' לעיל ע' 24 ואילך. 26*) וראה שו\"ת חת\"ס הנ\"ל (הערה 10) ד\"ה ובמחילת כבודם."],["27","27","ומכיון שבדבר זה „עשו ב\"ה כדבריהם\" (כנ\"ל משו\"ע אדה\"ז) — עכצ\"ל שגם ב\"ה ס\"ל שעכ\"פ זהו „זמן\" הקרבן ולא רק „השלמה\" (דאל\"כ איך הקילו לעשות כב\"ש ולא הקריבו בזמן). וראה לעיל שם הערה 52. בפרש\"י חגיגה (ז, ב ד\"ה ביו\"ט) דזה ש„שרו ב\"ה בעולת ראי' (ביו\"ט) . . אע\"פ שיש להן תשלומין\" הוא משום ד„עיקר מצותן ביום ראשון\". אבל ראה שפת אמת חגיגה שם ש(נוסף לזה שברש\"י ביצה (יט, א ד\"ה אבל. כ, ב ד\"ה אף זו) פי' הטעם „שמא יאנס ולא יקריבנה בשאר הימים\" — הנה) כוונת רש\"י היא (לא שאם יקריב אח\"כ יחסר „עיקר מצותן\", כ\"א) שמפני זה נחשב זמנה קבוע, וכמפורש בביצה (כ, ב. ובתוס' שבהערה 25 בשם הירושלמי) שזהו טעמם דב\"ה שדחי יו\"ט. ועפ\"ז מתרץ שם קושיית הטו\"א (שם) על פרש\"י דאם „עיקר מצותן ביום ראשון\" א\"כ חגיגה וראי' לא יקריבו ביו\"ט אחרון (גם לב\"ה) כיון שאין עיקר מצותן בימים אלו — כי גם בימי תשלומין הוי זמנה קבוע. ע\"ש."]]],[1300281092,"ווייל דער ענין פון „תשלומין לראשון\" איז בלויז בנוגע צו חלות החיוב, ד.ה. אַז דער חיוב צו ברענגען דעם קרבן לייגט זיך (ניט אויף יעדערן פון די שבעת ימים פאַר זיך — „אין לך יום בהם שאין חובתו תלוי' בו בעצמו\" — נאָר דער חיוב איז חל) אויף יום ראשון, און דער חיוב פון די שפעטערדיקע טעג איז בלויז אַ המשך פון דעם חיוב ביום ראשון (ובמילא, אויב עס איז ניטאָ קיין חיוב ביום ראשון, קען במילא ניט זיין קיין המשך, אַ קרבן אין די ימים שלאח\"ז).\nאָבער לכו\"ע, איז דער ברענגען די קרבנות לאחרי יום ראשון ניט קיין הקרבה „בדיעבד\", וואָס מען פאַרפעלט „זמן\" קרבן, נאָר דאָס איז זמן הקרבן²⁸].\nאון וויבאַלד אַז דער גדר התשלומין איז (בעיקר) אַן ענין מצד זריזות הגברא²⁹ — איז דאָך שייך דער ענין פון תשלומין אויך בנוגע צו יום ראשון. וואָרום מצד ענין הזריזות דאַרף מען מקדים זיין צו ברענגען דעם קרבן וואָס פריער ביום ראשון גופא, גלייך „בצפרא\"³⁰. ובמילא ווען איינער איז זיך ניט מזדרז צו ברענגען די קרבנות גלייך „בצפרא\", איז דער ברענגען שפעטער אין טאָג (ביום ראשון גופא) אַ גדר פון תשלומין — קומט אויס, אַז דער ענין התשלומין איז דאָ „כל שבעה\"³¹.\n— וואָס ע\"פ כל הנ\"ל (אַז די שבעת ימים זיינען „זמן\" הקרבן) קומט אויס, אַז ביי חג השבועות האָט תורה מלכתחילה אויסגעשטעלט דעם „זמן\" פון די קרבנות החג שלו אין אַן אופן, אַז די „שבעת ימים\" פון זמן הקרבנות זיינען כולל סיי דעם יו\"ט (ובפרט שלאחרי ה„צפרא\") און סיי די ימות החול (שלאחרי היו\"ט) בשווה!\nו. דער ביאור אין דעם:\nעס איז ידוע אַז בעת מתן תורה איז געווען די בחירה אין עם ישראל. ווי דער פסק דין פון מגן אברהם³² — אַראָפּגעבראַכט אין אַלטן רבי'נס שולחן ערוך³³ — אַז ביים זאָגן (אין ברכות ק\"ש) „ובנו בחרת מכל עם ולשון\" דאַרף מען מכוין זיין אויף מתן תורה³⁴.\nאין וואָס באַשטייט דער חידוש פון „בחירה\" אין עם ישראל לגבי פריער? אויך פאַר מ\"ת זיינען אידן שוין געווען אויסגעטיילט פון אַלע אַנדערע אומות. ווי מען געפינט נאָך פאַר יציאת מצרים אַז שוין דעמאָלט ווערן אידן אָנגערופן „בני בכורי ישראל\"³⁵; איז פאַרוואָס זאָגט מען אַז ערשט ביי מ\"ת האָט דער אויבערשטער בוחר געווען אין אידן?",[["28","28","ולשון רש\"י (חגיגה ט, א ד\"ה כולן תשלומין לראשון) „יום אחד עשה הכתוב עיקר\" — י\"ל הכוונה שאז חלות החיוב. ואולי יש לפרש כן גם לשון המאירי שם: עיקר החיוב בראי' בחגיגה בראשון הוא ולא בשאר הימים וכשהוא חוגג בשאר הימים אינו חוגג אלא בתורת תשלומין של ראשון. ודוחק. וראה לעיל הערה 21."],["29","29","ולכאורה מוכרח לומר כן להמ\"ד „תשלומין זה לזה\", וכפרש\"י חגיגה שם (ד\"ה כולן תשלומין זל\"ז) שלמ\"ד זה „יום ראשון שהוא נראה להביא עיקר לדידי' וימיו שלאחריו תשלומין לו\" — דלכאורה, איפה מרומז בקרא שעיקר זמן קרבן הוא ב„יום ראשון שהוא נראה להביא\" (והוא „עיקר\" רק „לדידי'\")? ועכצ\"ל שהו\"ע בהגברא, כבפנים."],["30","30","ראה פסחים ד, א."],["31","31","ואולי בלשון זה נרמז ג\"כ שכל השבעת ימים הם נקודה אחת (או בלשון הצפע\"נ הנ\"ל הערה 21 „חד זמן\")."],["32","32","סי' ס סק\"ב."],["33","33","שם סעיף ד."],["34","34","ראה גם אבודרהם בקידוש ליל שבת בטעם שאין אומרים בשבת אשר בחר בנו כו', אתה בחרתנו כו'."],["35","35","שמות ד, כב (וראה שם, כג)."]]],[1300281093,"וההסברה בזה (ווי גערעדט שוין כמה פעמים³⁶): דער אמת'ער באַדייט פון בחירה איז — אַז מען קלייבט אויס אַ זאַך בבחירה חפשית; דער וואָרט „בחירה\" מיינט אַז מען קלייבט אויס די זאַך נאָר מצד דעם אייגענעם רצון הטוב, אָן קיין שום זאַך וואָס איז מכריח דעם בוחר.\nדערפון איז פאַרשטאַנדיק, אַז די אמיתית ענין הבחירה איז ניט פאַרבונדן מיט די מעלות וואָס דער דבר הנבחר פאַרמאָגט — ווייל ווען מען וויל אַ זאַך צוליב אירע מעלות — איז עס ניט קיין בחירה חפשית: דער אדם איז מוכרח צו וועלן די זאַך צוליב די מעלות וואָס זי פאַרמאָגט.\nז. און דאָס איז אויך דער עילוי וואָס האָט זיך אויפגעטאָן ביי מתן תורה לגבי פריער:\nבשעת מ'קלייבט אויס אַ זאַך צוליב די מעלות אירע, איז דער עצם האדם „ניטאָ\" אין דעם קלייבן, די סיבת הבחירה איז (ניט ער — ניט פון אים, נאָר) די מעלות וועלכע זיינען דאָ אין דער זאַך (שמחוץ הימנו).\nדוקא ווען מען קלייבט אויס אַ זאַך אין אַן אופן פון בחירה חפשית — וואָס קומט בלויז מצד הבוחר — אין דעם איז פאַראַן דער עצם פון דעם בוחר.\nועד\"ז בענינינו: פאַר מ\"ת איז די אויסגעטיילטקייט פון אידן געווען מצד זייערע גרויסע מעלות וקדושה. און דערפאַר, אע\"פ וואָס דער אויבערשטער האָט זיך „פאַרבונדן\" מיט אידן, איז דאָס ניט דער ענין פון בחירת העצמות.\nדוקא ביי מ\"ת, ווען „אתה בחרתנו מכל העמים\" — ניט (נאָר) מצד די מעלות פון אידן, נאָר ווייל אַזוי האָט דער אויבערשטער בוחר געווען, בבחירתו החפשית — דאַן האָט זיך אויפגעטאָן אַ פאַרבונד צווישן אידן מיטן אויבערשטן מצד מהותו ועצמותו ית'.\nח. כשם ווי דאָס איז בנוגע בחירת הקב\"ה בבנ\"י — עד\"ז איז מצד אידן, אַז ביי מ\"ת האָט זיך אויפגעטאָן אַז זייער עבודה איז מצד ענין הבחירה³⁷:\nפאַר מ\"ת איז די עבודה פון אידן געקומען מצד דעם וואָס זיי האָבן דערהערט דעם גודל המעלה צו זיין אַן עובד ה' כו' אלקי אבי אברהם כו' בורא העולם וכו'. און וויבאַלד אַז די סיבה פון זייער התקשרות צום אויבערשטן איז געווען מצד דער מעלה פון עבודת ה', איז זייער עצם ניט געווען אין דעם. עס האָט ניט דורכגענומען זייער עצם.\nביי מ\"ת, ווען דער אויבערשטער האָט בוחר געווען אין אידן, דאָס האָט פועל געווען בבני ישראל אַז זיי זאָלן בוחר זיין אין דעם אויבערשטן. דאָס וואָס אַ איד דינט דעם אויבערשטן איז ניט נאָר מצד די „חשבונות\" ווי עבודת ה' איז אַ גוטע זאַך, נאָר ווייל אַזוי איז ער בוחר בבחירתו החפשית: אַ איד קלייבט אויס, אָן קיין שום טעם וסיבה (מבחוץ), צו זיין אַן עובד ה'. און וויבאַלד אַז די סיבה אויף זיין עבודה איז (ניט נאָר די מעלה כו' פון עבודת ה', נאָר) זיין בחירה,",[["36","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041308\" data-slug=\"likkutei-sichot\" data-id=\"1300041308\">לקו\"ש ח\"ד ע' 1309</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111005\" data-slug=\"likkutei-sichot\" data-id=\"1300111005\">חי\"א ע' 5</a> ואילך (ובהערות שם). ועוד."],["37","37","ראה בארוכה לקו\"ש חי\"א <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111088\" data-slug=\"likkutei-sichot\" data-id=\"1300111088\">שם. — ואע\"פ</a> שנאמר „(אנכי ה\"א) אשר הוצאתיך מאמ\"צ גו'\" — אין זה טעם למה שקודמו, כ\"א ענין שני (לדוגמא — שולל דקארו לו אלקא דאלקיא (סוף מנחות) — ראה פרש\"י עה\"פ). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261126\" data-slug=\"likkutei-sichot\" data-id=\"1300261126\">לקו\"ש חכ\"ו ע' 126</a> ואילך."]]],[1300281094,"דעריבער ווערט זיין גאַנצער עצם „פאַרנומען\" אין דער עבודה.\nעפ\"ז וועט מען פאַרשטיין³⁸ וואָס דער פסוק³⁹ זאָגט „החיים והמות נתתי לפניך הברכה והקללה ובחרת בחיים\". דלכאורה תמוה⁴⁰: וויבאַלד אַז דער אויבערשטער ווייזט אָן אַ אידן⁴¹ ווי דורך „טוב\" באַקומט מען „חיים\" און דורך „רע\" ווערט „מות\"⁴² — וואָס קומט דערנאָך דער ציווי „ובחרת בחיים\"? צי דען דאַרף מען אָנזאָגן אַ מענטשן אַז ער זאָל אויסקלייבן „חיים\" אַנשטאָט „מות\"?!\nאיז איינער פון די ביאורים בזה, אַז דער דיוק דאָ איז „ובחרת בחיים\": די תורה זאָגט אָן אַ אידן, אמת טאַקע אַז „נתתי לפניך\" חיים וטוב אַזוי אַז דו זעסט מיט דיינע אויגן ווי דורך „טוב\" דערגרייכט מען „חיים\" — פונדעסטוועגן, אין וואָס פאַר אַן אופן דאַרף זיין עבודת ה', איז אַן אופן פון „ובחרת בחיים\". דער טעם פון דיין טאָן „טוב\" זאָל זיין ניט נאָר ווייל דיין שכל וועט דיר מכריח זיין ווייל טוב ברענגט צו חיים, נאָר טו אַזוי בבחירתך החפשית: דו קלייב אויס „חיים\" (אפילו ווען אין דעם וואָלט ניט געווען קיין שום מעלה), און מיש ניט אַריין חשבונות פון שכל⁴³.\nט. ענין הנ\"ל, אַז מ\"ת האָט אויפגעטאָן אַז די עבודה פון אידן זאָל זיין מצד בחירה — דריקט זיך אויס אין מתן תורה גופא. והביאור בזה:\nדי עשרת הדברות זיינען דברים הכי פשוטים⁴⁴, וואָס אויך דער שכל אנושי איז זיי מחייב. נאָך מער: חז\"ל זאָגן⁴⁵ אַז ביי „כל דיבור ודיבור של הקב\"ה יצתה נשמתן\". ולכאורה⁴⁶: בשלמא דער דיבור „אנכי\" און „לא יהי' לך\" זיינען ענינים עיקריים וואָס רירן אָן דעם עצם פון אַ אידן (ביז אַז ביי זיי איז דער דין אַז „יהרג ואל יעבור\"). אָבער וואָס פאַר אַ שייכות האָבן „כבד את אביך\", „לא תגנוב\", וכיו\"ב, מיט פרחה נשמתן⁴⁷?\nנאָר אין דעם האָט זיך אויסגעדריקט דער אויפטו פון מ\"ת, אַז אפילו ענינים וועלכע זיינען פאַרשטאַנדיק אין שכל האדם — טוט זיי אַ איד ניט מצד זיין שכל און פאַרשטאַנד בטיב הדבר ההוא, נאָר דערפאַר וואָס אַזוי איז ער בוחר צו טאָן.\nאון וויבאַלד מען טוט עס מצד בחירה, ליגט מען אין דעם מיט דעם גאַנצעם עצם, און ווי גערעדט פריער, אַז בחירה דערגרייכט ביז אין עצם האדם. און דערפאַר האָבן אַזוי אויך די שפעטערדיקע דברות (וועלכע זיינען דברים פשוטים) אָנגערירט אין דעם עצם פון אידן און געבראַכט צו פרחה נשמתן.\nיוד. דער אויבנדערמאָנטער ביאור בהנוגע צו מתן תורה גיט אויך אַ הסברה אין דעם וואָס יעדער יו\"ט האָט",[["38","38","בהבא לקמן — להעיר ג\"כ מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041339\" data-slug=\"likkutei-sichot\" data-id=\"1300041339\">לקו\"ש ח\"ד ע' 1340</a> ואילך."],["39","39","נצבים ל, יט."],["40","40","ראה גם לקו\"ת ואתחנן יא, ב ואילך. ד\"ה אם בחוקותי ה'ש\"ת פ\"א-ב. ועוד."],["41","41","ראה פרש\"י עה\"פ (ונת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191287\" data-slug=\"likkutei-sichot\" data-id=\"1300191287\">לקו\"ש חי\"ט ע' 274</a> ואילך)."],["42","42","ראה פרש\"י נצבים שם, טו-יח."],["43","43","ראה גם לקו\"ש חי\"ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191293\" data-slug=\"likkutei-sichot\" data-id=\"1300191293\">שם (ע' 280</a> ואילך)."],["44","44","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380370\" data-slug=\"likkutei-torah\" data-id=\"4001380370\">לקו\"ת במדבר טו, סע\"ג</a>. ובכ\"מ."],["45","45","שבת פח, ב."],["46","46","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171284\" data-slug=\"likkutei-sichot\" data-id=\"1300171284\">לקו\"ש חי\"ז ע' 284</a>."],["47","47","להעיר משמו\"ר (פכ\"ט, ד) „ונגלה להם פרחה נשמתם\", ובשהש\"ר (פ\"ה, ו) „מקול דיבורו הראשון\". אבל בשבת שם מפורש שהי' „בכל דיבור ודיבור\" (וראה גם חדא\"ג מהרש\"א שם)."]]],[1300281095,"מצות וועלכע זיינען ספעציעל פאַר דעם יו\"ט (בחג המצות — סיפור ביצי\"מ, אכילת מצה כו'; בחג הסוכות — ישיבה בסוכה, ד' מינים), דאַקעגן חג השבועות האָט ניט קיין מצוה מיוחדת.\n[וואָס דאָס איז איינער פון די טעמים⁴⁸ פאַרוואָס ער ווערט אָנגערופן „עצרת\" — ווייל די זאַך וואָס טיילט אויס דעם יו\"ט פון ימי החול איז „עצרת\", דאָס אָפּהאַלטן זיך פון טאָן מלאכה, וועלכע איז דאָ באַ אַלע יו\"ט].\nאיז דער ענין אין דעם: די אַנדערע יו\"ט דריקן אויס ענינים פרטיים ומעלות פרטיות אין דעם פאַרבונד, כביכול, פון דעם אויבערשטן מיט אידן ד.ה. דאָ רעדט מען וועגן דעם פאַרבונד צווישן דעם אויבערשטן מיט אידן אין אַן אופן מסוים, און בהתאם לזה זיינען געגעבן געוואָרן מצוות וועלכע זאָלן אויסדריקן דעם תוכן פרטי פון דעם יו\"ט מסוים.\nאָבער חג השבועות, זמן מתן תורתנו, דריקט אויס די בחירה פון אויבערשטן אין אידן און די בחירה פון אידן אין אויבערשטן — וואָס דאָס איז ניט קיין ענין פרטי, און דאָס האָט ניט קיין „ציור\" (עס איז ניט באַגרענעצט צו איין אופן אָדער אַ צווייטן אופן אין דער התקשרות) — נאָר דאָס איז וואָס דער עצם פון אלקות איז בוחר אין עמו ישראל און דער עצם פון אידן איז בוחר בהקב\"ה. און דערפאַר קען מען דאָס ניט פאַרבינדן מיט אַ מצוה פרטית (די עצירה ממלאכה והשמחה — זיינען „משותפים\" בכל המועדים).\nיא. און דאָס איז אויך די הסברה אין דעם וואָס די תשלומין פון חג השבועות זיינען אין ימי החול:\nדי אַנדערע יו\"ט וואָס זיי דריקן אויס דעם פאַרבונד צווישן דעם אויבערשטן מיט אידן מצד אַ תוכן ומעלה פרטית — זיינען זיי פאַרבונדן מיט אַן אויסגעטיילטן זמן. דער תוכן פרטי פון דעם יו\"ט מאַכט אַז דער זמן פון יו\"ט זאָל זיין אויסגעטיילט פון אַנדערע טעג, וואָס אין דעם זמן איז מאיר דער ענין מיוחד פון דעם יו\"ט.\nאון דעריבער האָט ניט קיין אָרט אַז די קרבנות פון דעם חג זאָל זיין אין אַ זמן וואָס האָט ניט קיין שייכות מיט דעם יו\"ט (שכולל גם — חול המועד).\nאָבער חג השבועות דריקט אויס די התקשרות פון אויבערשטן מיט אידן מצד בחירה וועלכע האָט ניט קיין „ציור\" און דערפאַר האָט זי ניט קיינע הגבלות (וכנ\"ל אַז דערפאַר האָט ניט חג השבועות קיין מצוה מיוחדת).\nאון מהאי טעמא איז די „עבודה\" וועלכע איז פאַרבונדן מיט חג השבועות — די קרבנות השייכים צו דעם חג — ניט באַגרענעצט צו דעם זמן היו\"ט, נאָר מען קען ברענגען די קרבנות פון שבועות אויך אין ימים וועלכע זיינען ימי חול; און נאָך מער: די עולות ראי' פלעגן „הרבה מישראל\" מלכתחילה ברענגען נאָך יו\"ט (כנ\"ל סעיף ד) — ווייל דער ענין הבחירה איז העכער פון דעם „ציור\" און אויסגעטיילטקייט פון זמן (היו\"ט).\nיב. עפ\"ז וועט מען אויך פאַרשטיין די שייכות פון דעם ענין הנ\"ל (בנוגע די",[["48","48","קדושת לוי דרוש לשבועות בתחלתו. — ויש לחלקה ממצות שמחת המועד — ע\"פ המבואר בד\"ה אתה אחד לאדהאמ\"צ (וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151239\" data-slug=\"likkutei-sichot\" data-id=\"1300151239\">לקו\"ש חט\"ו ע' 227</a> ואילך. סה\"מ מלוקט ח\"א ע' תיד) לענין השביתה דשבת, שהיא קשורה עם בחי' יחידה דוקא. ע\"ש."]]],[1300281096,"תשלומין פון שבועות) צו דעם וואָס שבועות איז יום אחד:\nדער אַלטער רבי איז מבאר⁴⁹ דעם טעם פאַרוואָס חג השבועות „אינו אלא יום אחד בלבד משא\"כ בפסח וסוכות שהן ז' ימים\" — אַז פסח וסוכות זיינען פאַרבונדן מיט די ז' מדות, און דערפאַר קומט עס אַראָפּ אין זמן פון שבעת ימים; משא\"כ חגה\"ש זמן קבלת התורה, „הוא בחי' יחידה שלמעלה מהתחלקות ז' מדות\", און דערפאַר קומט עס אַראָפּ אין זמן אין אַן אופן פון „יום אחד\" (דער מספר ווי ער איז העכער פון התחלקות).\nד.ה.: פסח און סוכות זיינען פאַרבונדן מיט דער התגלות אלקות וואָס איז מלובש אין די ז' מדות, דער גילוי איז פאַרבונדן מיט אַ „ציור\" כביכול און מיט אַ תוכן פרטי (למעלה, ועד\"ז למטה ביים אדם); משא\"כ בחגה\"ש איז די התקשרות אַזאַ וועלכע איז העכער פון התחלקות למעלה, און פאַרבונדן מיט דער פשיטות פון יחידה, ווייל שבועות איז דער זמן פון בחירה. און דערפאַר איז עס יום אחד בלבד⁵⁰, יחיד שלמעלה מאחד סתם⁵¹.\nקומט אויס, אַז אויך אין דעם „זמן\" פון שבועות איז מודגש ווי שבועות איז בעצם אַן ענין וואָס איז העכער פון התחלקות הזמן; און דעריבער ווערט אַזוי נסתעף בנוגע דעם זמן פון די קרבנות החג, אַז עס איז העכער פון די התחלקות פון יו\"ט וחול, די שבעת ימים זיינען כולל סיי דעם טאָג פון יו\"ט און סיי די ימי החול (שלאחרי היו\"ט) — כאחד.\n(משיחות יום ב' דחגה\"ש וש\"פ נשא תשמ\"ג)",[["49","49","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370486\" data-slug=\"torah-or\" data-id=\"3901370486\">תו\"א יתרו בהוספות קט, סע\"ד</a> ואילך."],["50","50","עפ\"ז יש לבאר השייכות דקרבנות של אשר — „שהקריבו קרבנו ע\"ש הבחירה שבחר הקב\"ה בישראל\" (במדב\"ר פי\"ד, י. ע\"ש) — ליום עשתי עשר (נשא ז, עב), מספר י\"א המורה על בחי' הכתר* (שלמעלה מיו\"ד ספירות) — ראה תו\"א שם, שמ\"ת שייך לכתר."],["51","51","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460058\" data-slug=\"or-hatorah-hb\" data-id=\"8316460058\">אוה\"ת יתרו ריש ע' תתעג</a>. *) להעיר מראב\"ע נשא שם: והוא סוד גדול. וראה ס' השיחות תשמ\"ט ח\"א (קה\"ת, תש\"נ) ע' 389 ואילך."]]],[1300281097,"<h3>שלח</h3>\nא. אין היינטיקער סדרה ווערט דערציילט וועגן חטא המרגלים, זייער הוצאת דיבה על הארץ¹, און צווישן די עניני דיבה וואָס זיי האָבן געזאָגט איז געווען — „ושם² ראינו את הנפילים בני ענק מן הנפילים ונהי בעינינו כחגבים וכן היינו בעיניהם\".\nשטעלט זיך רש\"י אויפן וואָרט „הנפילים\" און איז מפרש: ענקים מבני שמחזאי ועזאל שנפלו מן השמים בימי דור אנוש.\nלערנען מפרשים³, אַז רש\"י באַוואָרנט די שוועריקייט פונעם כפל לשון „נפילים\" אין פסוק (— „הנפילים . . מן הנפילים\")⁴, איז רש\"י מסביר, אַז די צוויי מאָל „נפילים\" האָבן יעדער פון זיי אַן אַנדער אָפטייטש: דער ערשטער „נפילים\" מיינט — „ענקים\" (ווי רש\"י טייטשט אין פ' בראשית⁵ אַז „נפילים\" — „בלשון עברית לשון ענקים הוא\"), און דער צווייטער מאָל — „(בני ענק) מן הנפילים\" — איז „מלשון נפילה שנפלו מן השמים\", און דער פשט אין פסוק איז, אַז זיי האָבן געזען די ענקים וואָס האָבן געשטאַמט „מאותם שנפלו מן השמים שהם שמחזאי ועזאל\".\nמען דאַרף אָבער פאַרשטיין (נוסף אויף דער שוועריקייט אין זייער פירוש, כדלקמן סעיף ג): למאי נפק\"מ אין פשוטו של מקרא צו וויסן (א) אַז די נפילים שנפלו מן השמים האָבן געהייסן שמחזאי ועזאל, און (ב) אַז זייער נפילה איז געווען „בימי דור אנוש\"⁶?!\nנאָך מער איז די תמי': ביים פסוק „הנפילים היו בארץ\" (אין פ' בראשית⁵) געפינט מען ניט אַז רש\"י זאָל מודיע זיין די נעמען פון די נפילים — איז תמוה: וויבאַלד אַז במקום סיפור המאורע (אין פ' בראשית) האָט רש\"י ניט געפונען פאַר נויטיק צו בריינגען די נעמען פון די „נפילים\" — דוקא בפרשתנו, וואו דער ענין הנפילים ווערט דערמאָנט נאָר בדרך אגב, דאַרף רש\"י לאָזן וויסן זייערע נעמען⁷?!\nאויך דאַרף האָבן אַ ביאור: בנוגע די נעמען פון די „נפילים\" שנפלו מן השמים געפינט מען אין חז\"ל צוויי דעות: אין מס' יומא⁸ ווערט געזאָגט „מעשה עוזא ועזאל\" (און אַזוי ברענגט זיך בכ\"מ במדרשים⁹); אָבער תרגום יונתן¹⁰ זאָגט „שמחזאי ועוזיאל\" (ועד\"ז אין מס' נדה¹¹: סיחון ועוג בני אחי' בר",[["1","1","יג, לב."],["2","2","שם, לג."],["3","3","רא\"ם. ועוד."],["4","4","„ועוד שאין טעם לומר ושם ראינו את הנפילים מן הנפילים\" (רא\"ם שם)."],["5","5","ו, ד."],["6","6","ועוד: בפרש\"י בראשית שם (ד\"ה בימים ההם) כ' „בימי דור אנוש ובני קין\" — וכאן משמיט רש\"י „ובני קין\" (וברמב\"ן בראשית שם מעתיק מרש\"י רק „בימי דור אנוש\")."],["7","7","ומובן שאין לומר, דמאחר שהכתוב (לעיל פסוק כב) הודיע שמות הענקים שראו, מוכרח רש\"י לכתוב השמות של הנפילים הראשונים. וראה רשב\"ם ורמב\"ן כאן."],["8","8","סז, ב — וכן נעתק בהד\"ה בפרש\"י שם."],["9","9","דב\"ר ספי\"א. זח\"א לז, א. ועוד."],["10","10","בראשית שם."],["11","11","סא, סע\"א."]]],[1300281098,"שמחזאי. ובפרש\"י שם: שבא משמחזאי ועזאל¹²) און אַזוי ברענגט זיך אין נאָך ערטער¹³.\n— פאַרוואָס קלייבט אויס רש\"י דוקא די דעה „שמחזאי ועזאל\", און ניט „עוזא ועזאל\"¹⁴?\nב. נוסף אויף דער הוספה פון רש\"י דאָ בנוגע די שמות הנפילים — איז אין דעם עצם אָפטייטש פון וואָרט „נפילים\" פאַראַן לכאורה אַ שינוי אין פרש\"י:\nדאָ בפרשתנו זאָגט רש\"י „שנפלו מן השמים\", משא\"כ אויפן פסוק⁵ „הנפילים היו בארץ\" טייטשט רש\"י¹⁵ „על שם שנפלו והפילו את העולם\", וואָס דער טייטש פון „נפלו\" (בפשטות) איז¹⁶, אַז זיי זיינען נאבד געוואָרן מן העולם (ע\"ד „הפילו את העולם\" שבפרש\"י תיכף לאח\"ז).\n[עס זיינען פאַראַן מפרשים¹⁷ וואָס זאָגן, אַז כוונת רש\"י דאָרט איז „נפלו מן העולם¹⁸ ר\"ל מן העולם העליון שהם שמים\", אַזוי ווי רש\"י טייטשט דאָ בפרשתנו „שנפלו מן השמים\". אָבער לכאורה צע\"ג צי מ'קען אַזוי זאָגן דעם פירוש, היות ס'איז אויף דעם ניטאָ קיין רמז אפילו בלשון רש\"י, ואדרבה, כנ\"ל, רש\"י זאָגט ביידע בחדא מחתא „שנפלו והפילו את העולם\"¹⁹].\nאיז תמוה ביותר: פאַרוואָס איז רש\"י דאָ משנה פון זיין פירוש אין פ' בראשית און זאָגט אַ נייעם פירוש „שנפלו מן השמים\"?\n[וואָרום אויך לויט דעם פירוש „שנפלו והפילו את העולם\" איז פאַרשטאַנדיק ווי די הדגשה „מן הנפילים\" וועט אָנוואַרפן אַ פחד אויף אידן²⁰ (ובפרט — לויטן צווייטן פירוש אין רש\"י דאָרט¹⁵ אויף די ווערטער „אנשי השם\" — „אנשי שממון ששממו את העולם\")].\nנאָך מער: דער שינוי אין פרש\"י פון „נפילים\", מאַכט אַ שינוי ניט נאָר אינעם אופן נפילתם (צי נפלו מן העולם, אָדער נפלו מן השמים) — נאָר אויך אין דעם מהות „הנפילים\":\nלויט פרש\"י אין בראשית, זיינען די „נפילים\" געווען בני אדם (און מלאכים און שמים — מאן דכר שמייהו) וואָס „נפלו והפילו את העולם\" דורך זייערע חטאים. ועד\"ז איז רש\"י מפרש (בפירושו הראשון והעיקרי²¹) די ווערטער",[["12","12","ולכאורה משמע שכן — עזאל — גריס בש\"ס שם, ולא לאפושי מחלוקת. וראה גם בעה\"ט בראשית שם."],["13","13","יל\"ש בראשית שם (רמז מד)."],["14","14","ולהעיר שבפרש\"י אחרי (טז, ח) מפרש „עזאזל\" — „הר עז כו'\" (ע\"פ דעות הראשונות ביומא שם), ולא כתנא דבי ר\"י (ביומא שם) „שמכפר על מעשה עוזא ועזאל\" (והטעם י\"ל כי אינו ע\"ד הפשט כלל)."],["15","15","ע\"פ ב\"ר ספכ\"ו."],["16","16","כמ\"ש בס' זכרון, רא\"ם, גו\"א ועוד שם. וכ\"כ ביפ\"ת (השלם) לב\"ר שם. פי' מהרז\"ו שם. ועוד."],["17","17","נחלת יעקב (הובא בשפ\"ח) בראשית שם."],["18","18","לשון המדרש שם."],["19","19","ולהעיר שרש\"י משמיט ענין הג' (בב\"ר שם) „ושמלאו את העולם נפלים כו'\"."],["20","20","ועוד ועיקר: עצם הענין שהענקים מתייחסים לנפילים הקדמונים דפ' בראשית ש„המה הגבורים אשר מעולם\" (בראשית שם) יש בו כדי להפחיד את בנ\"י (ראה רמב\"ן כאן בסופו)."],["21","21","משא\"כ בפי' הב' שם „הם השרים* ההולכים בשליחותו של מקום אף הם היו מתערבים בהם\". אבל להעיר (נוסף ע\"ז שבכת\"י רש\"י אחדים (שתח\"י) ליתא. וראה גם רש\"י עה\"ת הוצאת *) ראה רש\"י עה\"ת הוצאת בערלינער שיש גירסא „שדים\"."]]],[1300281099,"(בפ' בראשית שם²²) „בני האלקים\" — ניט מלאכים²³ נאָר „בני השרים והשופטים\".\nמשא\"כ לויט פרש\"י בפרשתנו — „שנפלו מן השמים\" — זיינען די נפילים געווען מלאכים.\nאיז תמוה ביותר, פאַרוואָס איז רש\"י מחדש אַ נייעם פירוש אין „נפילים\"?\nג. ויש לומר דעם ביאור אין דעם אַלעם:\nדי שאלה אין פסוק וואָס רש\"י קומט פאַרענטפערן, איז ניט (אַזוי) דער כפל אין פסוק „הנפילים . . מן הנפילים\"\n— וואָרום ראשית כל, איז דער כפל ל' „נפילים\" כשלעצמו ניט קיין (גרויסער) חידוש, מען געפינט כמה פעמים אַז די תורה איז כופל אַ לשון צוליב תוספת הדגשה²⁴\n[וע\"ד התואר²⁵ „צדיק בן צדיק\", וואָס קומט אונטערשטרייכן גודל הצדקות של הבן, ועד\"ז בעניננו, אַז דורך זאָגן „נפילים (ענקים) . . מן הנפילים\" קומט צו אַ הדגשה יתירה אין דעם, ובמילא — אין דער הפחדה פון אידן (ולכן איז ניטאָ קיין הכרח צו זאָגן אַז די צוויי מאָל „נפילים\" זיינען משונה זמ\"ז — האָבן פאַרשידענע טייטשן)],\nאון נוסף לזה, אויב די שווערקייט איז מצד כפל ל' „נפילים\", האָט רש\"י געדאַרפט מעתיק זיין (אין דבור המתחיל) אויך (ואדרבה — בעיקר) די ווערטער „מן הנפילים\", וואָס זיי זיינען די הכפלה —\nנאָר די שאלה (פון רש\"י) איז: אין די פריערדיקע פסוקים ווערט דערציילט ווי די מרגלים האָבן מתאר געווען די שטאַרקייט פון די יושבי הארץ — „אפס כי עז העם גו' והערים גו' וגם ילידי הענק ראינו שם\"²⁶. שטעלט זיך די שאלה: וואָס האָבן די מרגלים דאָ (ביי „ויוציאו דיבת הארץ\") מחדש געווען לגבי זייערע פריערדיקע רייד „וגם ילידי הענק ראינו שם\"²⁷ (חוץ פון צוגעבן דעם תואר „נפילים\")²⁸?\nאיז רש\"י מפרש, אַז „נפילים\" מיינט די „ענקים מבני שמחזאי ועזאל שנפלו מן השמים\", וואָס דערמיט ווערט מובן ווי די מרגלים האָבן דאָ מוסיף געווען",[["","","בערלינער): א) ההמשך בפרש\"י „כל אלקים שבמקרא לשון מרות כו'\" קאי (לכאורה) על פירוש הראשון** (אבל ראה לבוש שם). ב) גם בפירוש זה לא כתב רש\"י (כפדר\"א פכ\"ב. ועד\"ז שם פ\"ז) „מלאכים\" אלא „שרים\". ולהעיר מראב\"ע בראשית שם. ואכ\"מ."],["22","22","ו, ב. — שמזה מובן שכ\"ה הפירוש גם בפסוק ד שם."],["23","23","כדעת הפדר\"א שם."],["24","24","ולהעיר מפרש\"י (לך יד, י): בארות בארות, בארות הרבה. — אלא שבנדו\"ד אין הכוונה שהוא כפל (כמו „בארות בארות\"), אלא דזה שהמרגלים חדשו והודיעו „הנפילים . . מן הנפילים\", שמוצאם מנפילים, היתה הדגשה יתירה ב„ענקיות\" שלהם — שגם אבותיהם היו ענקים — בכדי להוסיף בההפחדה כו'."],["25","25","רש\"י תולדות כה, כא."],["26","26","יג, כח."],["27","27","ראה גם משכיל לדוד כאן ד\"ה ענק."],["28","28","ברמב\"ן כאן (בסופו) „ועתה חזרו להפליג להם בחזקת הענקים . . לקרא אותם נפילים . . והם מן הנפילים הקדמונים אשר שמעתם עליהם כו'\". אבל: (א) לכאורה פרט זה (והם מן הנפילים הקדמונים) אינו הפלגה כ\"כ בחוזק שלהם. (ב) ועיקר: בפסוק הא' של הוצאת דיבת הארץ נאמרו רק דברים חדשים לגמרי („ארץ אוכלת יושבי' גו' וכל העם גו'\", וכפרש\"י — נעתק לקמן הערה 34), ולכן מסתבר שגם בפסוק זה יש דבר חדש לגמרי. **) ובא' מכת\"י רש\"י (שתח\"י) ענין זה (כל אלקים כו') בא לפני „ד\"א\"."]]],[1300281100,"אַן ענין חדש לגמרי: דאָס זיינען לגמרי ניט פון דעם סוג אפילו פון די „ילידי הענק\" וועלכע זיי האָבן פריער דערמאָנט (וואָס וועגן זיי האָט מען געלערנט אין פ' בראשית, „הנפילים היו בארץ\"²⁹) — ד.ה. מענטשן וואָס די הפחדה זייערע איז נאָר דאָס וואָס זיי זיינען גרויס און הויך אין וואוקס, ריזן — נאָר דאָ ווערן געמיינט „נפילים\" (ענקים כנ\"ל, אָבער) וועלכע האָבן געשטאַמט פון מלאכים, „שנפלו מן השמים\".\nד. און דאָס איז אויך דער טעם פאַרוואָס די מרגלים האָבן דאָס געזאָגט דוקא דאָ, ביי „ויוציאו דיבת הארץ\" — ווייל דער ענין איז פאַרבונדן מיט דעם חידוש וואָס איז פאַרגעקומען בהזמן צווישן זייערע פריערדיקע דיבורים און די דיבורים:\nדי תורה דערציילט, אַז ווען די מרגלים האָבן פאַרענדיקט זייערע רייד וועגן דער שטאַרקייט פון די יושבי הארץ, איז נאָכדעם געווען דער „ויהס כלב את העם גו' ויאמר עלה נעלה וירשנו אותה כי יכול נוכל לה\"³⁰, און ווי רש\"י איז מפרש, אַז כלב האָט משתיק געווען, אָפגעשלאָגן די טענת המרגלים (אַז „עז העם גו'\"), זאָגנדיק אַז משה האָט באַוויזן גאָר גרויסע נסים, שלמעלה מן הטבע לגמרי („והלא קרע לנו את הים והוריד לנו את המן והגיז לנו את השליו\"), און דעריבער איז „עלה נעלה, אפילו בשמים והוא אומר עשו סולמות ועלו שם נצליח בכל דבריו\"³¹.\nאויף דעם האָבן די מרגלים געענטפערט „לא נוכל לעלות אל העם כי חזק הוא ממנו\"³², און ווי רש\"י איז מפרש „כביכול כלפי מעלה אמרו\". וואָרום אויב „ממנו\" מיינט נאָר די אידן, איז עס אינגאַנצן ניט קיין ענטפער אויף דעם וואָס כלב האָט אויפגעוויזן, אַז דער אויבערשטער קען מאַכן נסים צו העלפן אידן. מוז מען בכן מפרש זיין³³, אַז דערמיט האָבן זיי געמיינט „כלפי מעלה\".\nאָבער מיט דעם אַליין האָבן זיך די מרגלים ניט געקענט באַגנוגענען, ווייל סוף־סוף ווי קען זיך אָפלייגן ביי אידן (וועלכע האָבן געזען די אַלע נסים) אַז עס קען זיין אַ מציאות פון „חזק הוא ממנו\" (כלפי מעלה)?\nדעריבער האָבן די מרגלים מוסיף געווען נייע ענינים — „ויוציאו דיבת הארץ גו'\" — וועלכע גיבן כאילו אַן אָרט אויף אַ מציאות פון „חזק הוא . . כלפי מעלה\"³⁴.\nאון דאָס איז וואָס די מרגלים האָבן דאָ מוסיף געווען „ושם ראינו את הנפילים גו'\": זיי האָבן ניט געמיינט די שטאַרקייט זייערע מצד זייער גשמיות'דיקער הויכקייט (אַלס ענקים) — ווייל, כמובן בפשטות, האָט גשמיות'דיקע הויכקייט ניט קיין באַטרעף קעגן „מעלה\"³⁵ — נאָר אַ תוקף וחוזק מיוחד",[["29","29","ועפ\"ז יתורץ (עכ\"פ יומתק) זה שרש\"י לא הביא כאן (כרשב\"ם ורמב\"ן) הקרא ד„הנפילים היו בארץ\"."],["30","30","שם, ל."],["31","31","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081097\" data-slug=\"likkutei-sichot\" data-id=\"1300081097\">לקו\"ש ח\"ח ע' 86</a> ואילך."],["32","32","שם, לא."],["33","33","ראה גם לבוש על פרש\"י שם."],["34","34","ולכן הדגישו ב„דיבת הארץ\" (שם, לב) דברים בלתי טבעיים: ארץ אוכלת יושבי' — בכל מקום שעברנו מצאנום קוברי מתים (רש\"י). וכל העם אשר ראינו בתוכה אנשי מדות (גדולים וגבוהים. רש\"י)."],["35","35","להעיר מנח יא, ה ובפרש\"י שם, א. רש\"י (חקת כא, לד. דברים ג, ב) בנוגע לעוג."]]],[1300281101,"וואָס ווערט געמיינט אין וואָרט „נפילים\": „ענקים מבני שמחזאי ועזאל שנפלו מן השמים\", אַז זיי זיינען געווען ניט סתם „ענקים\", נאָר זיי האָבן געשטאַמט (פון מלאכים „שנפלו) מן השמים\", און דערפאַר איז בכחם צו מורד זיין קעגן שמים כו'.\nה. ביים „בן חמש למקרא\" איז דאָס אָבער פאָרט ניט גלאַטיק — (א) אַז אַ מלאך זאָל מורד זיין בהקב\"ה³⁶, (ב) אַז אַ מלאך אפילו זאָל קענען האָבן עפעס אַ כח דורכצופירן זיין מרידה קעגן אויבערשטן³⁶*.\n— דערפאַר איז רש\"י מוסיף אַז „(נפלו מן השמים) בימי דור אנוש\", וואָס דערמיט ווערן באַוואָרנט ביידע ענינים הנ\"ל:\nא) וועגן דור אנוש זאָגט דער פסוק³⁷ „אז הוחל לקרוא בשם ה'\", און ווי רש\"י איז דאָס מפרש „לקרוא את שמות האדם . . בשמו של הקב\"ה לעשותן אלילים כו'\" — איז פאַרשטאַנדיק, אַז אויך די נפילה פון די מלאכים מן השמים אין יענעם דור איז פאַרבונדן מיט אַ מרידה נגד ה'.\nב) וויבאַלד די נפילים שטאַמען פון די מלאכים „שנפלו מן השמים בימי דור אנוש\", זיינען זיי דאָך ניט נאבד געוואָרן דורכן מבול³⁸. ד.ה. אע\"פ אַז די מי המבול זיינען געווען דורך ארובות השמים נפתחו³⁹, גשם מן השמים⁴⁰, רותחין⁴¹ און „וימח את כל היקום\"⁴², האָט עס אָבער ניט אָפגעמעקט יוצאי חלציהם פון די נפילים, און דאָס באַווייזט, אַז זייער שטאַרקייט איז עד כדי כך, אַז אפילו אַן עונש מן השמים האָט דער אויבערשטער געוואָלט אַז עס זאָל אויף זיי קיין שליטה ניט האָבן⁴³!\nו. עפ\"ז וועט מען אויך פאַרשטיין פאַרוואָס רש\"י ברענגט די נעמען פון די נפילים — „שמחזאי ועזאל\" — ווייל דאָס איז נאָך מער מדגיש זייער שטאַרקן „כח\" למרוד נגד ה':\nביי די נפילים בפ' בראשית⁵ זאָגט דער פסוק „אנשי השם\", און רש\"י איז דערויף מפרש „אותם שנקבו בשמות . . שנקבו ע\"ש אבדן שנמוחו והותשו\", והיינו אַז אין די שמות פון די נפילים איז מרומז אַן ענין וואָס איז פאַרבונדן מיט זייער מהות.\nועד\"ז בעניננו, אַז די נעמען „שמחזאי ועזאל\" זיינען מרמז אויף זייער תוכן — און רש\"י דאַרף ניט אויסטייטשן אין וואָס דאָס באַשטייט, ווייל דאָס איז דער פירוש הפשוט פון די שמות:",[["36","36","ברש\"י יומא שם „מלאכי חבלה\" — אבל (בפשטות) גם אלו הם בשליחותו של מקום (וראה רש\"י בראשית ג, כד). 36*) להעיר מרש\"י וירא יט, כב."],["37","37","בראשית ד, כו."],["38","38","ראה רש\"י לך יד, יג (לפי מדרשו. ובמקומו (דברים ג, יא) מפרש רק לפי פשוטו) „עוג שפלט מדור המבול\". — וראה פני דוד (להחיד\"א) פרשתנו כאן (בשם הרי\"ד) שהענקים (דפרשתנו) „מבני עוג יצאו\" (ונולדו לאחר המבול). ולהעיר מראב\"ע כאן ד„מן הנפילים\" הוא ע\"ד מ\"ש בבראשית שם „וגם אחרי כן גו'\", שלפי הראב\"ע (משא\"כ לפרש\"י) שם, היינו שנמלטו „אחר המבול\" (ראה רמב\"ן שם). וראה רמב\"ן פרשתנו יג, כב (בנוגע לאחימן גו' וארבע. ולהעיר מרש\"י ח\"ש כג, ב). ועוד. ואכ\"מ."],["39","39","נח ז, יא."],["40","40","שם ח, ב."],["41","41","סנהדרין קח, ב. ועוד. — אבל ראה השקו\"ט אם כ\"ה שיטת רש\"י בפירושו עה\"ת (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051051\" data-slug=\"likkutei-sichot\" data-id=\"1300051051\">לקו\"ש ח\"ה ע' 51</a> הערה 32. ח\"י ע' 35 ובהערה 46 שם)."],["42","42","נח ז, כג."],["43","43","ראה עד\"ז אלשיך פרשתנו כאן. וראה הערה 38."]]],[1300281102,"„שמחזאי\" באַשטייט פון צוויי ווערטער — „שם חזאי\", ד.ה. אַז ווען מען קוקט (חזאי) אויף אים זעט מען שממה („שם\" איז פון לשון „שממה\", און ווי רש\"י טייטשט (בפירושו הב') אויף אנשי השם — „אנשי שממון ששממו את העולם\");\nאון דער נאָמען „עזאל\", איז נוסף לזה וואָס דער נאָמען כמו שהוא ווייזט אויף דער שטאַרקייט פון דעם מלאך (עזאל, מלשון עז), דערמאָנט ער אויך אויפן שם „עזאזל\" (וואָס מ'האָט שוין געלערנט אין פ' אחרי⁴⁴), וואָס רש\"י פאַרטייטשט עס „הר עז וקשה צוק גבוה\", אַז דאָס איז ניט סתם שטאַרקייט, נאָר פון אַ מקום „עז וקשה\", וואָס איז אַ מקום שממה — ניט מן הישוב.\nדי נעמען פון די צוויי מלאכים ווייזן אַז ענינם איז עוז און צו ברענגען שממה וחורבן העולם לשחת הארץ⁴⁵ (היפך הברית מיט נח'ן לאח\"ז און רצונו של הקב\"ה, אַז עס זאָל זיין ישוב העולם).\nז. ע\"פ הנ\"ל יומתק דער המשך פירושי רש\"י אויף די ווייטערדיקע ווערטער אין פסוק „(ושם ראינו את הנפילים גו') ונהי בעינינו כחגבים וכן היינו בעיניהם\":\n„וכן היינו בעיניהם\" איז רש\"י מפרש „שמענו אומרים זה לזה נמלים⁴⁶ יש בכרמים כאנשים\", און דערנאָך איז רש\"י מעתיק דעם וואָרט „ענק\" און איז מפרש „שמעניקים חמה בקומתן\".\nאיז ניט מובן: א) פאַרוואָס דאַרף רש\"י בכלל זוכן אַ פירוש אויפן לשון „ענק\"? ב) באם מוכרח — פאַרוואָס זאָגט עס ניט רש\"י פריער⁴⁷, אין פסוק⁴⁸ „וגם ילידי הענק ראינו שם\"? ג) פאַרוואָס איז רש\"י מפרש דעם וואָרט „ענק\" נאָך זיין פירוש אויף „וכן היינו בעיניהם\" — היפך זייער סדר אין פסוק⁴⁹ („בני ענק . . ונהי בעינינו . . וכן היינו בעיניהם\")?\nאיז דער ביאור אין דעם:\nווען ס'רעדט זיך וועגן סתם ענקים, אנשים גבוהים, איז אנשים בגובה הרגיל ניט שייך אַז זיי זאָלן לגבי זיי אויסזען ווי „נמלים (יש בכרמים)\". וואָרום דער ערך הגובה פון אַן ענק⁵⁰ לגבי סתם אַן אדם (שגובהו ג' אמות⁵¹) איז לגמרי ניט בערך ווי צווישן אנשים און נמלים. און דעריבער, דוקא לאחרי ווי רש\"י איז מפרש „שמעתי אומרים זל\"ז נמלים כו'\", מוז ער זאָגן אַז דאָ איז דער טייטש פון „ענק\" — „שמעניקים חמה בקומתן\".\nאון דאָס איז מתאים מיט'ן חילוק שנתבאר לעיל צווישן די צוויי פסוקים:",[["44","44","טז, ח."],["45","45","נח ט, יא. — היפך בריאתה שהי' באופן כי טוב מאד וציווי השם מלאו את הארץ וכבשוה."],["46","46","ברא\"ם כ' שט\"ס הוא וצ\"ל „כחגבים\". וראה בארוכה השקו\"ט במפרשי רש\"י."],["47","47","כמו שהקשה בשפ\"ח. קיצור מזרחי (בשם מהר\"ן)."],["48","48","יג, כח. ולפנ\"ז (שם, כב) ושם גו' ילידי הענק."],["49","49","ראה דבק טוב. קיצור מזרחי שם. — ובס' זכרון „לפי דעתי חלוף סופרים הוא זה\"."],["50","50","אפילו עוג* (שע\"פ הרמז) אשר בפרש\"י שבס\"פ חוקת (ע\"פ ברכות נד, ב) — היו עד קרסוליו רק שלשים אמה — וראה דברים (ג, יא): באמת איש, ובפרש\"י וכו' שם. בפרש\"י בפסוק שלפנ\"ז (ד\"ה אנשי מדות) כגון גלית גבהו שש אמות וזרת (אבל לא קאי ב„ענק\" אלא ב„אנשי מדות\", שזה הי' אצל „כל העם גו'\")."],["51","51","ראה רש\"י בשלח טז, כט: ג' לגופו כו'. *) שהי' מבני שמחזאי כו' (כנ\"ל סוס\"א מנדה סא, סע\"א) — סוג הב' שבפנים — שהרי נמלט מן המבול (כנ\"ל הערה 38)."]]],[1300281103,"דעם ערשטן מאָל ווען זיי האָבן געזאָגט „וגם ילידי הענק ראינו שם\" האָבן זיי געמיינט סתם ענקים; דוקא דאָ, וואו עס רעדט זיך וועגן „נפילים . . שנפלו מן השמים\", זיינען זיי אַזעלכע ענקים „שמעניקים חמה בקומתן\"⁵², וואָס דערפאַר „ונהי בעינינו כחגבים וכן היינו בעיניהם\".\nח. פון יינה של תורה שבפירוש רש\"י זה:\nדי הוספה פון רש\"י — אַז מיט „ושם ראינו את הנפילים גו'\" האָבן די מרגלים געמיינט די מלאכים „שנפלו מן השמים\" — איז מתאים צום תוכן הטענה פון די מרגלים ווי עס ווערט מבואר אין פנימיות התורה.\nעס איז ידוע דער ביאור פון אַלטן רבי'ן⁵³ בנוגע חטא המרגלים, אַז זייער סברא — ניט צו וועלן אַריינגיין אין ארץ ישראל — איז באַשטאַנען אין דעם, וואָס זיי האָבן געוואָלט בלייבן אין מדבר ווייל דאָרט איז מען אויסגעטאָן פון טרדות בעניני פרנסה (ובכלל — פונעם עסק בגשמיות העולם), כדי מען זאָל זיך קענען אָפגעבן אינגאַנצן מיט עבודה רוחנית. משא\"כ אַריינגייענדיק אין ארץ ישראל, ארץ נושבת⁵⁴, וואו עס הויבט זיך אָן דער סדר פון „שש שנים תזרע שדך גו'\"⁵⁵, וועט דאָס זיי אָפרייסן פון עבודה רוחנית.\nאון דער שורש הטעות איז געווען זייער הנחה, אַז רוחניות און גשמיות מוזן זיין בסתירה זה לזה, מען קען ניט זיין פאַרנומען מיט גשמית'דיקע ענינים און גלייכצייטיק זיין צוגעבונדן צו רוחניות.\nאון דאָס איז וואָס די מרגלים האָבן געזאָגט „ארץ אוכלת יושבי'\" — אַז אויב מ'איז זיך „מתיישב\", מ'טוט זיך אַריין אין עניני ארץ, ווערט מען „אויפגעגעסן\" איינגעזונקען אין די טרדות פון עניני הארץ, „אוכלת יושבי'\".\nעפ\"ז איז מובן דער המשך הענין (וואָס זיי האָבן געזאָגט) „ושם ראינו את הנפילים גו'\" — וכפרש\"י אַז דאָס מיינט „מבני שמחזאי ועזאל שנפלו מן השמים בימי דור אנוש\": ווי דערציילט בארוכה אין חז\"ל⁵⁶, איז מלכתחילה זיינען זיי אַראָפגעקומען מיט אַ כוונה לשם שמים, נאָר זיי האָבן ניט געקענט בייקומען די חומריות ונסיונות פון עוה\"ז און נפלו ממדריגתם כו'. ניט קוקנדיק אויף זייער גרויסער מעלה זייענדיק בעולמות עליונים, איז בירידתם למטה האָבן זיי ניט נאָר ניט געקענט אָנהאַלטן זייער פריערדיקע מדריגה, נאָר אדרבה, דאָס האָט אין זיי גורם געווען אַ נפילה ממדריגתם.\nועד\"ז — האָבן די מרגלים געטענה'ט — איז בנוגע לבנ\"י: אע\"פ אַז אין מדבר זיינען זיי געשטאַנען אויף גאָר אַ הויכער מדריגה, אָפגעריסן פון עניני העולם (בדוגמא צו מלאכים), וועט אָבער די כניסה אין א\"י גורם זיין אין זיי אַ נפילה ממדריגתם.\nט. אויף דעם האָבן יהושע וכלב געענטפערט⁵⁷: „אם חפץ בנו ה' והביא",[["52","52","ולהעיר שזה מורה ג\"כ על כחם בשמים — מעניקים חמה כו'."],["53","53","לקו\"ת ריש פרשתנו (ע\"ש). דרמ\"צ קפא, א ואילך. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041043\" data-slug=\"likkutei-sichot\" data-id=\"1300041043\">לקו\"ש ח\"ד</a> פ' שלח. ובכ\"מ."],["54","54","ל' הכתוב — בשלח טז, לה."],["55","55","ר\"פ בהר."],["56","56","ראה בארוכה יל\"ש בראשית שבהערה 13. ועוד."],["57","57","ראה הנסמן בהערה 53."]]],[1300281104,"אותנו אל הארץ הזאת גו' אל תיראו את עם הארץ כי לחמנו הם גו' וה' אתנו\"⁵⁸ —\nאע\"פ אַז בנוגע מלאכים איז אַראָפקומענדיק למטה אין גשמיות העולם ווערן זיי נפילים (נפילה ממדריגתם) — זיינען אָבער אידן אַנדערש⁵⁹, ווייל ביי אידן איז „חפץ בנו ה'\", דעם אויבערשטנ'ס חפץ ותענוג איז אין די אידן און אין זייער עבודה (למטה). און דערפאַר האָבן אידן שלא בערך העכערע כוחות ווי מלאכים. די נשמה פון אידן איז „חלק אלקה ממעל ממש\"⁶⁰, ישראל וקוב\"ה כולא חד כביכול, און דעריבער איז ביי אידן פאַראַן כחו של הקב\"ה צו קענען מחבר זיין צוויי הפכים, גשמיות ורוחניות גם יחד, בהגברת⁶¹ הרוח (והצורה שבהגשם עצמו).\nביז, אַז אַ איד קען, נוסף צום זיין צוגעבונדן צו רוחניות אויך ווען ער געפינט זיך אין גשמיות העולם, אויפטאָן נאָכמער, ער קען איבעראַרבעטן די גשמיות העולם גופא און דערפון מאַכן אַ דירה לו יתברך.\nאון דאָס האָבן יהושע וכלב געזאָגט „אם חפץ בנו ה' והביא אותנו גו'\", אַז וויבאַלד „חפץ בנו ה'\" האָבן אידן ניט וואָס מורא צו האָבן פון עם הארץ, און נאָכמער — „לחמנו הם\": ניט נאָר וועט ניט זיין אַז „ארץ אוכלת יושבי'\", נאָר להיפך „לחמנו הם\" דער (עם ה)ארץ, אידן וועלן עס מברר ומזכך זיין, ווערן אַ בעה\"ב אויף דער ארץ און איר איבער מאַכן — מאַכן פון איר אַ דירה לו יתברך.\n(משיחת ש\"פ שלח תשמ\"ב)",[["58","58","פרשתנו יד, ח־ט."],["59","59","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו\"ת ברכה צח, סע\"א</a>. ובכ\"מ בארוכה."],["60","60","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["61","61","ועיין <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פל\"ב</a> „נמאס כו' טפלה כו' ולהעלות . . על כו'\". ואכ\"מ."]]],[1300281105,"<h3>שלח ב</h3>\nא. אין סוף פרשתנו¹ ברענגט רש\"י פון רבי משה הדרשן: למה נסמכה פרשת מקושש לפרשת ע\"א לומר שהמחלל את השבת כעובד ע\"א שאף היא שקולה ככל המצות כו'².\nאין תוס'³ שטייט: מעשה המקושש הי' בתחילת ארבעים מיד אחר מעשה מרגלים דאמר במדרש דלשם שמים נתכוין שהיו אומרים ישראל כיון שנגזר עליהן שלא ליכנס לארץ ממעשה מרגלים שוב אין מחויבין במצות עמד וחילל שבת כדי שיהרג ויראו אחרים. ולפי\"ז איז מובן די סמיכות פון פ' מקושש צו כללות פרשתנו, וואו ס'רעדט זיך וועגן חטא המרגלים (וואס איז דער עיקר סיפור בפרשתנו און על שמה ווערט אנגערופן די גאנצע סדרה — פ' שלח), ווארום מעשה מקושש איז געקומען אלס תוצאה פון מעשה המרגלים.\nוויבאלד תורה שטעלט פ' ע\"א צווישן מעשה מרגלים און פ' מקושש, איז מובן, אז אויך לדעת התוס' איז פ' מקושש שייך צו פ' ע\"א ע\"ד ווי רש\"י ברענגט פון ר\"מ הדרשן, און ווי תוס'⁴ איז מסביר די גמרא⁵ \"יודע הי' משה רבינו שהמקושש במיתה שנאמר⁶ מחללי' מות יומת אבל לא הי' יודע באיזו מיתה⁷\", אז \"אע\"ג⁷* דמיתה סתם חנק היא, מתוך הסברא הי' מדמה לעובד עבודת כוכבים דבסקילה דמחלל שבת בפרהסיא ככופר בעיקר דכופר במעשה בראשית\"⁸.\nויש להוסיף: אט די שייכות (פון פ' מקושש צו פ' ע\"א) איז (נאר) אין דעם עצם חטא פון שבת וע\"ז. אבער פון דעם וואס די סמיכות איז ניט סתם אין א חטא סתם פון חילול שבת, נאר צום חטא פון",[["1","1","ולא הביאו במקומו לפנ\"ז בריש פ' מקושש (טו, לב) כי (כמדובר כמ\"פ) אין סמיכות הפרשיות קושיא ודבר הצריך ביאור בפשש\"מ — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181150\" data-slug=\"likkutei-sichot\" data-id=\"1300181150\">לקו\"ש חי\"ח ע' 141</a> ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231062\" data-slug=\"likkutei-sichot\" data-id=\"1300231062\">לקו\"ש חכ\"ג ע' 62</a> ואילך."],["2","2","ראה חולין ה, סע\"א ובפרש\"י שם (ושם הוא נוגע להלכה). וראה רמב\"ם סוף הל' שבת (הובאו לקמן הערה 8) ובמפרשי רש\"י כאן."],["3","3","ב\"ב קיט, ב ד\"ה אפילו."],["4","4","ב\"ב שם ע\"א ד\"ה שנאמר. סנהדרין עח, ב ד\"ה לא הי' יודע. וראה גם חידושי הרשב\"א ב\"ב שם."],["5","5","ב\"ב וסנהדרין שם. ועד\"ז הוא בספרי פרשתנו טו, לד."],["6","6","תשא לא, יד."],["7","7","הובא גם בפרש\"י פרשתנו שם, לד. אבל רש\"י משנה וכותב \"לא היו יודעים . . אבל יודעים כו'\" (ועד\"ז הוא בפרש\"י אמור כד, יב) והוא כבתו\"כ אמור שם, ולא כבגמ' וספרי שמשה לא הי' יודע. ואכ\"מ. 7*) ל' התוס' סנהדרין שם."],["8","8","ובפרש\"י חולין שם: העובד עבודת כוכבים כופר בהקב\"ה והמחלל שבת כופר במעשיו ומעיד שקר שלא שבת הקב\"ה במעשה בראשית. ולהעיר מדיוק לשון הרמב\"ם שם: השבת ועבודת כוכבים ומזלות* כל אחת משתיהן שקולה כנגד שאר כל מצות התורה (וממשיך) והשבת היא האות שבין הקב\"ה ובינינו לעולם לפיכך כו' אבל המחלל שבת בפרהסיא הרי הוא כעובד עבודת כוכבים ומזלות* ושניהם כעובדי כוכבים ומזלות** לכל דבריהם. — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410194\" data-slug=\"likkutei-sichot\" data-id=\"1301410194\">לקו\"ש ח\"ל ע' 130</a> הערה 37. ואכ\"מ. *) והוא שינוי הצענזור כבכ\"מ ברמב\"ם וצ\"ל \"ע\"ז\". וכ\"ה ברמב\"ם (רומי רמ). **) שינוי הצענזור וצ\"ל \"כגויים\" כבדפוס רומי הנ\"ל."]]],[1300281106,"מקושש דוקא, איז מסתבר צו זאגן, אז פ' ע\"א האט א שייכות צו דעם אופן אין חילול שבת ווי עס איז געווען ביים מקושש, \"דלשם שמים נתכוין\".\nויש לומר, וויבאלד אז דאס אלץ איז א טייל פון פ' שלח, וואס עיקרה איז פרשת מרגלים, דארף מען זאגן, אז אויך דער ענין האט א שייכות צו דעם תוכן פון \"מעשה מרגלים\"⁹.\nב. וועט מען דאס פארשטיין בהקדם א ביאור בדברי המדרש וואס תוס' ברענגט: \"דלשם שמים נתכוין שהיו אומרים ישראל כיון שנגזר עליהן שלא ליכנס לארץ ממעשה מרגלים שוב אין מחויבין במצות, עמד וחילל שבת כדי שיהרג ויראו אחרים\".\nלכאורה בכדי ארויסצוברענגען אז מ'איז נאך אלץ מחוייב במצות — פארוואס האט ער געדארפט דוקא מחלל שבת זיין, ובפרט אז דורך דעם קומט צו נאך א חטא גדול ביותר \"את דמכם לנפשותיכם\" — שופך דם עצמו¹⁰ — ער ברענגט דערצו אז \"יהרג\", ער האט עס געקאנט ארויסבריינגען דורך עובר זיין אויף אן אנדער מצוה, ביז א חטא קל ביותר, וועלכער איז מחייב מלקות, ממון וכיו\"ב?\nאויך אין תרגום יונתן¹¹ שטייט דער כללות התוכן אז דער מקושש עצים האט ניט געמיינט מחלל זיין במזיד נאר לשם שמים נתכוין, אבער דער ת\"י באווארנט פארוואס ער האט דוקא מחלל שבת געווען: וויבאלד מ'האט דעמאלט נאר געוואוסט \"גזירת שבתא\" אבער דער עונש פון חילול שבת — \"קנסא דשבתא לא אשתמודע להון\", איז דאס געווען די כוונה פון דעם מקושש עצים אז דורך זיינע מעשים \"אשתמודע קנסא (פון שבת) לכל בית ישראל\".\nאבער לפי המדרש (המובא בתוס') אז ער האט דאס געטאן אויף ארויסצוברענגען אז מ'איז מחוייב במצות, איז ניט מובן פארוואס האט ער אויסגעקליבן חילול שבת, כנ\"ל?\nאיז דער ביאור בזה — ע\"פ דברי המהרש\"א¹² אויף דער שאלה ווי אזוי האט ער מחלל שבת געווען כדי להודיע אין וועלכער מיתה איז מען דן א מחלל שבת? ער איז מסביר¹³: וויבאלד אז ער האט צו דער מלאכה ניט געדארפט אנקומען נאר \"לידע באיזו מיתה כו', ה\"ל מלאכה שאינה צריכה לגופה כמו חופר גומא וא\"צ אלא לעפרה שהוא פטור לר\"ש\", און ער פירט אויס \"וכן י\"ל לפי המדרש שכתבו התוס' כו' דה\"ל נמי מלאכה שאינה צריכה לגופה\".\nועפ\"ז איז מובן לויט דעם מדרש המובא בתוס' פארוואס ער האט דאס ארויסגעבראכט דורך מלאכת שבת דוקא, ווייל ער האט ניט געוואלט טאן א חטא און ביחד דערמיט זאל זיין בירור הנ\"ל, און דאס איז דוקא בא שבת וואס מלאכה שאינה צריכה לגופה איז פטור",[["9","9","ופ' נסכים (טו, ב ואילך) ופ' חלה (שם, יז ואילך) — מובנת שייכותן לפ' מרגלים ע\"פ פרש\"י שם, ב \"בישר להם שיכנסו לארץ\". ובויק\"ר פט\"ו, ו: למה נסמכה פרשת חלה לפרשת ע\"ז כו'."],["10","10","נח ט, ה (ובפרש\"י שם)."],["11","11","פרשתנו עה\"פ טו, לב."],["12","12","חדא\"ג ב\"ב שם."],["13","13","וראה גם ראש דוד ריש פ' פינחס. פני דוד להחיד\"א פרשתנו כאן. עיי\"ש. קדושת לוי פרשתנו עה\"פ."]]],[1300281107,"(לר\"ש)¹⁴, ביז ווי עס שטייט אין קדושת לוי¹⁴* — \"א\"כ לא חילל שבת כלל\".\nג. אעפ\"כ האט דער אויבערשטער געזאגט \"מות יומת האיש רגום אותו גו'\"¹⁵, אז ער איז געווען מחוייב מיתה — אע\"פ אז כלפי שמיא גליא אז ס'איז געווען א מלאכה שאינה צריכה לגופה, און לשם שמים נתכוין, ביז אז \"לא חילל שבת כלל\" [נאכמער: דאס איז א פעולה צוליב שמירת שבת — זיין כוונה איז געווען עס זאל נתחזק ווערן שמירת שבת (ובכלל — תורה ומצות)¹⁶ בא אידן]¹⁷ —\nאיז מבאר דער מהרש\"א¹² אז דאס איז ווייל \"לא ידעו העדים שהתרו בו שהוא עשה על דעת זו ואינן אלא דברים שבלב ודנין היו אותו למיתה ע\"פ העדות\". איז ניט דער פשט אין דעם אז מ'האט אים סוקל געווען בטעות (מצד העדר ידיעת העדים)\n— ווארום תורה איז דאך תורת אמת, איז אויב לפי האמת¹⁸ מצד כוונתו, \"לא חילל שבת כלל\", וואלט דער אויבערשטער ניט געהייסן \"מות יומת האיש גו'\"¹⁹ —\nנאר דער חיוב סקילה \"בדיני אדם\"²⁰ איז ע\"פ תורת אמת אויף דער מעשה ופעולה, און וויבאלד אז זיין מעשה איז געווען א מעשה פון חילול שבת, איז דאס ע\"פ דין ב\"ד שלמטה²¹ א פעולה וואס מ'איז אויף דעם מחוייב סקילה, און ס'איז כלל ניט נוגע זיין כוונה²².\nד. עפ\"ז איז מובן די שייכות פון פ' מקושש צו פ' ע\"ז:\nבנוגע צו ע\"ז געפינט מען אן ענין מיוחד וואס מען געפינט ניט בשאר מצות התורה: יעדער איד אפילו א קל שבקלים, בשעת עס קומט צו א נסיון פון ע\"ז, איז ער זיך מוסר נפש \"אפי' שלא לעשות רק איזה מעשה לבד נגד אמונת ה' אחד כגון להשתחות לעבודה זרה אף שאינו מאמין בה כלל בלבו\"²³.",[["14","14","וראה שו\"ת אור המאיר ס\"ב, שגם לדעת ר\"י (שס\"ל מלאכה שאינה צריכה לגופה חייב) בנדו\"ד פטור, ע\"פ מ\"ש התוס' (שבת עג, ב) דבתולש גם לר\"י פטור כשאין צריך לעצים (וכ\"ה לדעת הרמב\"ם הל' שבת פ\"ח ה\"ד), והרי המקושש \"תליש ועקר קיסין\" (תיב\"ע כאן). 14*) פרשתנו עה\"פ."],["15","15","טו, לה."],["16","16","ולהעיר משו\"ת הרדב\"ז (הובא בגליוני הש\"ס לתוס' ב\"ב שם) ח\"ה סי' א'תסח בעובר בלאו אם מתכוין למצוה אפי' התרו בו אינו לוקה. ובשו\"ת הרדב\"ז ח\"א (סע\"ז) ובזמן שהוא מוחק השם לתקן הספר כו' מאבד הוא ומ\"מ מודה אני שאינו לוקה כיון שהוא סבור לעשות בטוב ולתקן כו'. וע\"ש בגליוני הש\"ס."],["17","17","ובראש דוד ופני דוד שם דזה גופא הי' ספיקו של משה אם חייב מיתה לפי דעשה לשם שמים וגם דה\"ל מלאכה שאינה צריכה לגופה."],["18","18","ולהעיר מרמב\"ן עה\"ת (שופטים יט, יט): שלא יתן ה' השופטים הצדיקים העומדים לפניו לשפוך דם נקי כי המשפט לאלקים הוא כו'. ע\"ש מ\"ש בטעם דעדים זוממין הרגו אין נהרגין."],["19","19","כי אף שזו היתה כוונתו \"כדי שיהרג ויראו\" — הרי כמה דרכים למקום שתתקיים כוונתו, שבנ\"י ידעו שמחוייבים במצות."],["20","20","ראה גם חיד\"א בשו\"ת חיים שאל ח\"ב ס\"ג. עין זוכר מערכת מ' אות כ'."],["21","21","וכן צריך לפרש לכאורה במ\"ש בקדושת לוי שם \"רק סקלוהו עבור העולם שלא ידעו מזה כפשט המדרש\"."],["22","22","ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091111\" data-slug=\"likkutei-sichot\" data-id=\"1300091111\">לקו\"ש ח\"ט (ע' 111</a> ואילך), בטעם ש\"חייבי מיתות ב\"ד . . אם עשו תשובה אין ב\"ד של מטה מוחלין להן\" (מכות יג, ריש ע\"ב) — ראה שו\"ת נודע ביהודה או\"ח מהד\"ק סל\"ה. חיד\"א הנ\"ל. המובא בגליוני הש\"ס מכות שם."],["23","23","<a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא ספי\"ט (כה, ב</a>)."]]],[1300281108,"וצריך ביאור: דער עיקר חטא פון ע\"ז איז די אמונה בלב, ער איז מחשיב אלס מציאות אחד מכל הברואים אויסער דעם אויבערשטן, א מלאך, גלגל או כוכב²⁴, ער איז מקבל (די עבודת כוכבים) אלס אלוה²⁵, און בשעת אז \"אינו מאמין בה כלל בלבו\" איז דאס ניט דער חטא פון ע\"ז, ער האט זיך ניט אפגעריסן פון דעם אויבערשטן, ולאידך, אפילו בשעת ער איז זיך ניט מוסר נפש קומט אים ניט קיין עונש ווייל ס'איז א מעשה באונס²⁶.\nנאר וויבאלד דאס איז א מעשה פון ע\"ז, אע\"פ אז דאס איז ניט דער תוכן החטא של ע\"ז, הייסט דאס בא אידן דא למטה איסור ע\"ז, און ער איז זיך אויף דעם מוסר נפש.\nאון דאס איז דער המשך פון פ' מקושש עצים ביום השבת צו פ' ע\"ז:\nמלאכת שבת איז דאך כל תוכנה פארבונדן מיט מחשבתו וכוונתו — \"מלאכת מחשבת אסרה תורה\", וואס דערפאר²⁷ איז מען ניט חייב אויף א מלאכה שאינה צריכה לגופה [ובפרט בנדו\"ד וואס ער האט דאס געטאן \"לשם שמים\", איז דאס כלל ניט קיין מעשה פון חילול שבת]²⁸ — אעפ\"כ, וויבאלד אז די מעשה מצ\"ע ווי עס זעט אויס אין וועלט איז דאס א מעשה פון חילול שבת (ווארום דאס וואס ס'איז געווען א מלאכה שאינה צריכה לגופה האט זיך דאס כלל ניט אנגעזען אין דער מעשה), איז ע\"פ תורת אמת, קומט אים סקילה אויף דער מעשה.\nה. ע\"פ כל הנ\"ל וועט מען אויך פארשטיין די שייכות בתוכן פון מעשה המקושש צו \"מעשה מרגלים\":\nס'איז מבואר בכ\"מ²⁹ אז דער טעם פארוואס די מרגלים האבן געוואלט בלייבן אין מדבר און ניט אריינגיין אין א\"י, איז ווייל דער עיקר עסק פון אידן אין מדבר (וואו זיי האבן זיך ניט געדארפט פארנעמען מיט עסק הפרנסה וכו') איז געווען אין לימוד התורה (וכמחז\"ל³⁰: לא ניתנה תורה לדרוש אלא לאוכלי המן), וואס לימוד התורה איז עיקרו — די הבנה והשגה³¹ בשכל ומחשבה³² (און אויך — אראפברענגען עס אין דיבור³³); משא\"כ אין א\"י, וואס דארט איז דאך שש שנים תזרע שדך גו' תזמור כרמך³⁴, ובפנימיות — דער עיקר עבודה דארט איז — מעשה, מצות מעשיות (ובפרט קיום המצות התלויות בארץ³⁴*), און מעשים טובים בכלל (עובדין טבין).",[["24","24","ראה רמב\"ם רפ\"ב מהל' ע\"ז. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201017\" data-slug=\"likkutei-sichot\" data-id=\"1300201017\">לקו\"ש ח\"כ ע' 17</a> ואילך."],["25","25","ראה רמב\"ם שם פ\"ג ה\"ו. וראה צפע\"נ שם."],["26","26","רמב\"ם הל' יסודי התורה פ\"ה ה\"ד. וראה תוס' סנהדרין סא, ב."],["27","27","חגיגה י, ריש ע\"ב. וש\"נ."],["28","28","להעיר מתשובות רעק\"א (ח\"א ס\"ח) בההפרש בין פטור מתעסק למלאכת מחשבת \"דהיכא דליכא מלאכת מחשבת אינו בכלל מלאכה ולא נעשית העבירה כלל\"."],["29","29","לקו\"ת ריש פרשתנו (לז, א. לח, ב-ג). אוה\"ת שם. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181162\" data-slug=\"likkutei-sichot\" data-id=\"1300181162\">לקו\"ש חי\"ח ע' 153</a> ואילך. וש\"נ. ובכ\"מ."],["30","30","מכילתא בשלח טז, ד."],["31","31","וכמש\"נ (ואתחנן ד, ו) \"היא חכמתכם ובינתכם\"."],["32","32","ועד ש\"בתורה שבע\"פ אם אינו מבין הפירוש אינו נחשב לימוד כלל\" (הל' ת\"ת לאדה\"ז ספ\"ב, ממג\"א או\"ח ס\"נ)."],["33","33","עירובין נד, א. הל' ת\"ת לאדה\"ז פ\"ב סי\"ב."],["34","34","בהר כה, ב-ג. 34*) ראה בארוכה במקומות שנסמנו בהערה 29."]]],[1300281109,"דערמיט וועט מען פארשטיין דברי המדרש (שהובא בתוס') הנ\"ל: שהיו אומרים ישראל כיון שנגזר עליהן שלא ליכנס לארץ ממעשה מרגלים שוב אין מחויבין במצות. פון פשטות לשון המדרש איז משמע, אז זיי האבן ניט געמיינט מורד זיין אין אויבערשטן ח\"ו דערמיט וואס זיי וועלן ניט מקיים זיין מצות, נאר³⁵ \"אין מחויבין במצות\". ולכאורה תמוה: וואס איז דער טעם פון זייער קס\"ד?\nוואלטן זיי געזאגט \"כיון שנגזר עליהם מיתה\"³⁶ וכיו\"ב — וואלט מען נאך געקענט מסביר זיין זייער קס\"ד (בדוחק גדול — עכ\"פ), אז מכיון שנגמר דינם למיתה, זיינען זיי ווי גברא קטילא און זיי האבן ניט קיינע חיובים. אבער וואס איז די קס\"ד \"כיון שנגזר עליהן שלא ליכנס לארץ כו' שוב אין מחויבין במצות\"?\nנאר ע\"פ הנ\"ל יש לומר אז דאס גופא איז געווען זייער קס\"ד: וויבאלד אז דער ענין פון כניסה לארץ איז דאך (בעיקר) צוליב קיום המצות במעשה, האבן זיי גערעכנט, \"כיון שנגזר עליהן שלא ליכנס לארץ ממעשה מרגלים שוב אין מחויבין במצות\" — צו זיי איז ניט שייך די עבודה פון קיום המצות במעשה [אפילו אט די מצות אין וועלכע זיי זיינען געווען חייב ביז דעמאלט, ובפרט וואס כו\"כ ציווים זיינען דאך געגעבן געווארן אלס הקדמה צו כניסה לארץ³⁷ (אז בזכות פון די מצות וועט מען אריינגיין אין א\"י³⁸)], און זייער גאנצער עבודה באשטייט בלויז אין לימוד התורה (במחשבה ודיבור) — \"אין מחויבין במצות\".\nאון אויף דעם קומט דער המשך פון מעשה מקושש עצים — \"עמד וחילל שבת כדי שיהרג ויראו אחרים\": דאס ברענגט ארויס, אז אויך אין די ענינים וואס כל תוכנם איז \"מלאכת מחשבת\", און ער האט דאך דאס געטאן \"לשם שמים\" ניט אויף עובר זיין אויף רצון השם — פונדעסטוועגן, איז אויך בזה דער עיקר — די מעשה בפועל, וואס דערפאר זאגט תורת אמת אז דער פסק הלכה למטה איז אז דאס איז חילול שבת און עס קומט דערפאר סקילה.\nאון דאס האט געלערנט די אידן וואס זיינען דעמאלט געבליבן אין מדבר, אז אע\"פ \"שנגזר עליהן שלא ליכנס לארץ\", איז דאס נאר אז זיי קומען ניט אן צום עיקר קיום מצות במעשה, ווי ס'איז אין א\"י; אבער אויך זיי, פארבלייבנדיק אין מדבר, איז די עבודה נוגע בעיקר ווי דאס קומט אראפ אין מעשה בפועל (אויף וויפל עס איז שייך במדבר³⁹),\nווייל עיקר ענין המצוה — צוותא וחיבור מיטן אויבערשטן, איז דורך מעשה המצוה.\n(משיחות ש\"פ שלח תשי\"ט, מוצש\"ק ראה תשל\"ט)",[["35","35","בדברי דוד פרשתנו עה\"פ מפרש ע\"פ מדרש הנ\"ל ל' \"במדבר\" שבכתוב, \"דה\"ק אחר מעשה המרגלים נעשו ישראל הפקר כמדבר כו' נהגו הפקר במצות ובא זה כו' לבטל ההפקר\"."],["36","36","עד\"ז הוא הלשון בקדושת לוי כאן."],["37","37","ובפרט ע\"פ ספרי ופרש\"י עקב יא, יז (יח): אף לאחר שתגלו היו מצויינים במצות הניחו תפילין עשו מזוזות כדי שלא יהיו לכם חדשים כו'. וראה בארוכה רמב\"ן אחרי יח, כה: כי עיקר כל המצות ליושבים בארץ ה'."],["38","38","ראה קידושין (לז, סע\"ב) במצות תפילין ופטר חמור."],["39","39","ראה בארוכה לקו\"ש שם."]]],[1300281110,"<h3>קרח</h3>\nא. אין היינטיקער סדרה דערציילט די תורה, אַז איידער דער אויבערשטער האָט מעניש געווען קרח דתן ואבירם — „ותפתח הארץ את פי׳ ותבלע אותם ואת בתיהם גו׳“¹ — האָט השם געזאָגט משה׳ן² „דבר אל העדה לאמר העלו (אסתלקו³) מסביב למשכן קרח דתן ואבירם. ויקם משה וילך אל דתן ואבירם גו׳ וידבר אל העדה לאמר סורו נא מעל אהלי האנשים גו׳ ויעלו מעל משכן קרח דתן ואבירם מסביב גו׳“.\nשטעלט זיך רש״י אויף די ווערטער „ויקם משה“⁴ און איז מפרש⁵: „כסבור שישאו לו פנים ולא עשו“.\nלערנען מפרשים⁶, אַז רש״י קומט דאָ באַוואָרענען: פאַרוואָס איז משה רבינו געגאַנגען צו דתן ואבירם? זיין דיבור (בשליחותו של הקב״ה) איז דאָך געווען (ניט צו דתן ואבירם, נאָר) צו דער עדה („דבר אל העדה לאמר גו׳“).\nאיז רש״י מבאר, אַז די הליכה צו דתן ואבירם איז געווען אַ באַזונדער ענין (ניט דער קיום פון „דבר אל העדה“ נאָר) — צו פועל׳ן אויף דתן ואבירם אַז זיי זאָלן תשובה טאָן; ווי עס שטייט אין מדרש⁷ „אע״פ ששמע משה מפי הגבורה לא אמר להם העלו עד שהלך והתרה בהם שנאמר ויקם משה וילך אל דתן ואבירם“.\nעס איז אָבער שווער צו זאָגן אַז דאָס איז כוונת רש״י⁸ — ווייל ע״ד הפשט איז מעיקרא קיין שאלה ניט צוליב וואָס איז משה געגאַנגען צו דתן ואבירם, וויבאַלד אַז די אידן האָבן זיך דעמאָלט געפונען „מסביב למשכן קרח דתן ואבירם“⁹ (ווי דאָס איז מוכח פון דעם",[["1","1","טז, לב."],["2","2","טז, כג־כז."],["3","3","תרגום. (הובא ב)פרש״י עה״פ."],["4","4","שם, כה."],["5","5","להעיר שבדפוס ראשון ושני דפרש״י, וכת״י רש״י שתח״י — פירוש רש״י זה ליתא. ובדפוס שני וכמה כת״י רש״י שתח״י נעתק במקומו פירוש המדרש (תנחומא פרשתנו ח. במדב״ר פי״ח, יב) „ואע״פ ששמע משה כו׳ להודיע רשעתם כו׳“. וכפי הנראה נוסח זה הי׳ לפני בעל ס׳ זכרון על פרש״י. אבל בדפוסי רש״י הנפוצים הוא כבפנים."],["6","6","ראה ס׳ זכרון (בפסוק כד) ובאר יצחק על פרש״י כאן. פי׳ מהרז״ו לבמדב״ר פרשתנו (פי״ח, ד קרוב לסופו)."],["7","7","תנחומא ובמדב״ר שבהערה 5 (ועד״ז בהנסמן לקמן הערה 19). וכ״ה בתיב״ע עה״פ. וראה פנים יפות כאן ע״ד ההלכה."],["8","8","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131053\" data-slug=\"likkutei-sichot\" data-id=\"1300131053\">נוסף ע״ז</a> שא״כ הו״ל לרש״י להעתיק בהד״ה (גם) התיבות „וילך אל דתן ואבירם“, ועכ״פ הו״ל לרמוז ב„וגו׳“, כדלקמן סעיף ד. ומטעם זה מובן ג״כ שאין לפרש שהוכחת רש״י היא ממש״נ „וילך אל דתן ואבירם“ ולא הלך אל קרח, שמזה מוכח שהלך להחזירם בתשובה [ולכן הלך רק לדתן ואבירם, כי משה חשב שרק „האיש אחד — קרח — הוא החוטא“ (טז, כב ובפרש״י), אבל דתן ואבירם אינם חוטאים ומורדים כ״א רק נתפתו ע״י קרח. וראה בארוכה לקו״ש חי״ג ע׳ 53 ואילך] — כי באם זו היתה הוכחת רש״י הו״ל להעתיק בהד״ה גם התיבות „וילך אל דתן ואבירם“, כנ״ל. והטעם שהלך רק אל דתן ואבירם ולא (גם) לקרח — ראה לקמן הערה 12."],["9","9","אף ש„ויקהל עליהם קרח את כל העדה אל פתח אהל מועד“ — „כל הלילה“ (טז, יט ובפרש״י) — עכצ״ל ד„כל העדה“ לאו דוקא. או שאח״כ בבקר נתפזרו כ״א לאהלו כו׳. *) ודוחק לומר שמעתיק רק התחלת הענין (ע״ד פרש״י תצוה כח, ו. ובכ״מ — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171242\" data-slug=\"likkutei-sichot\" data-id=\"1300171242\">לקו״ש חי״ז ע׳ 242</a>. ועוד)."]]],[1300281111,"אויבערשטנ׳ס אָנזאָג „העלו מסביב וגו׳“), איז בכדי איבערצוגעבן דער עדה דעם ציווי ה׳, האָט משה געדאַרפט גיין¹⁰ צו דעם משכן¹¹ פון (קרח¹² און) דתן ואבירם¹³.\nאויך: ע״פ דרך הפשט האָט לכאורה קיין אָרט ניט צו אָננעמען פירוש המדרש הנ״ל¹⁴ („אע״פ ששמע משה מפי הגבורה לא אמר להם העלו עד שהלך והתרה בהם“), וואָרום וויבאַלד דער אויבערשטער האָט אָנגעזאָגט משה׳ן „דבר אל העדה גו׳“ — ווי איז שייך אַז משה רבינו זאָל אָפלייגן דעם קיום ציווי ה׳ און טאָן פריער עפעס אַנדערש (אפילו אַן ענין טוב)¹⁵ מדעת עצמו¹⁶!\nדאַרף מען לכאורה זאָגן, אַז מיט „ויקם משה וילך גו׳“ איז די תורה אויסן דערציילן (ניט אַז משה האָט מפסיק געווען מיט אַן אַנדער ענין, נאָר פאַרקערט) — ווי משה האָט גלייך אויסגעפאָלגט דעם אויבערשטנ׳ס ציווי „דבר אל העדה גו׳“ — „ויקם משה וילך גו׳ (נאָר הליכה, אָבער ניט דיבור וואָס דורך דעם איז שייך „להתרות“, ולאחרי ובהמשך ל„וילך“) וידבר אל העדה גו׳“.\nאיז אינגאַנצן ניט מובן: פון וואַנעט און ווי אַזוי לערנט דאָ רש״י ע״פ פשוטו של מקרא אַז הליכת משה איז געווען (ניט גלייך צו איבערגעבן דעם ציווי ה׳ צו דער עדה, נאָר) צו דתן ואבירם, כדי „שישאו לו פנים“ (און תשובה טאָן)?\nב. אויך איז ניט מובן לשון רש״י — „כסבור שישאו לו פנים“: אויב כוונת רש״י איז, אַז משה איז געגאַנגען זיי וואָרענען (דורך באַווייזן זיך „פניו“ — כדי זיי זאָלן תשובה טאָן), פאַרוואָס זאָגט עס ניט רש״י¹⁷ בלשון ברור, ע״ד",[["10","10","בחדא״ג מהרש״א לסנהדרין (קי, א) „דמשום דבור סורו נא מעל אהלי האנשים הרשעים וגו׳ לא הוה איצטריך לילך אצלם שהי׳ אפשר ע״י שלוחו . . אבל . . הלך משה בעצמו אליהם לדבר עמם דברי ריצוי אולי ישובו“. אבל לכאורה צ״ע, דמכיון שנצטוה משה „דבר אל העדה גו׳“ — איך אפ״ל ש„הי׳ אפשר ע״י שלוחו“?"],["11","11","ומה שנאמר „אל דתן ואבירם“, ולא „אל משכן דתן ואבירם“ — כי דרך הכתוב לקצר כו׳."],["12","12","והטעם שהוזכרו רק „דתן ואבירם“ ולא קרח — יש לומר: כי ההליכה היתה (בעיקר) בשביל דתן ואבירם שהיו חונים בדגל ראובן רחוק (לכה״פ) אלפים אמה (רש״י במדבר ב, ב) מן המשכן, משא״כ קרח שהי׳ במחנה לוי׳ שהיתה סמוך להמשכן (רש״י שם). וראה ש״ך עה״ת כאן. ואכ״מ."],["13","13","להעיר גם מאברבנאל כאן: ולא היתה הליכתו שמה . . להשיבם למוטב כפרש״י אלא לתת הגזרה והפסק דין לפניהם . . שבפניהם דבר אל העדה כו׳."],["14","14","להעיר מפרש״י ריש פרשתנו „פרשה זו יפה נדרשה במדרש רבי תנחומא“ (וראה ס׳ זכרון על פרש״י שם: שכל מה שכתב בה הרב ז״ל רובו מתנחומא) — וברא״ם שם „כלומר שהוא (רק) קרוב לפשוטו של מקרא ולא נצטרך לפרשו לפי פשוטו כמנהגו בשאר המקומות“. ועפ״ז י״ל דגם כאן העתיק רש״י דרש זה מתנחומא אף שאינו לפי פשוטו ממש. אבל ראה בארוכה שיחת ש״פ קרח תשכ״ה, שכוונת רש״י לדרשות שבתנחומא המיישבות פשוטו של מקרא (כפרש״י בראשית ג, ח. ובכ״מ) באופן „יפה“. ע״ש."],["15","15","ראה רש״י לעיל (יתרו יט, יד): שלא הי׳ משה פונה לעסקיו — אפילו לא לעסקי משה (שבודאי הם רק עניני קדושה כו׳) — אלא מן ההר אל העם (ולהעיר מרש״י שמות ד, כד. בשלח טז, כב). — אבל יש לחלק, כי כאן המדובר (להחזירם בתשובה) בענין זה עצמו."],["16","16","להעיר מרש״י דברים ב, כו (וכן בפרש״י חוקת כא, כב): אע״פ שלא צוני המקום לקרא לסיחון לשלום . . קדמתי את סיחון בדברי שלום — אף שנצטוה לפנ״ז (דברים שם, כד) והתגר בו מלחמה היפך דברי שלום (אלא ששם „למדתי ממדבר סיני . . ממך למדתי“ — רש״י שם). ואכ״מ."],["17","17","ראה לעיל הערה 5. *) בראב״ע (פסוק כד) ואברבנאל כאן, שאהל קרח לאדם שלו ורכושו הי׳ אצל אהלי דתן ואבירם. אבל בפרש״י לא נזכר חידוש זה."]]],[1300281112,"המדרש, — „כסבור שישאו לו פנים וישובו ממחלוקתם“, או כיו״ב? — הלשון „כסבור שישאו לו פנים“ איז דער אינהאַלט . . . געבן כבוד למשה.\nאפילו את״ל אַז רש״י וויל נוצן אַ לשון וואָס ברענגט אַרויס דאָס וואָס זיין הליכה האָט געדאַרפט פועל׳ן אויף זיי¹⁸ —\nהאָט רש״י געדאַרפט מעתיק זיין דעם לשון המדרש¹⁹ — „אולי יתביישו ויחזרו בהם“ (או ע״ד לשון הרשב״ם²⁰: אולי יחזרו בתשובה), וואָס דערמיט ווערט דער תכלית פון דער הליכה אַרויסגעבראַכט קלאָר²¹.\nג. לכאורה וואָלט מען געקענט מסביר זיין לשון רש״י ע״פ מאמר הגמרא²² אויפן פסוק: „ויקם משה וילך אל דתן ואבירם אמר ר״ל מכאן שאין מחזיקין במחלוקת“.\nומהאי טעמא נוצט דאָ רש״י דעם לשון „כסבור שישאו לו פנים“ (און ניט „אולי יתביישו ויחזרו בהם“, וכיו״ב — ווייל דאָ איז די הדגשה ניט אַזוי אַז זיי זאָלן תשובה טאָן אויף זייער חטא כלפי הקב״ה („הנועדים על ה׳“²³), נאָר „לבטל מחלוקת“²⁴ אויף משה — אויף דעם פאַסט מער דער לשון „כסבור שישאו לו פנים“ (היפך זייער פריערדיקער הנהגה באופן פון אָפזאָגן משה׳ן, מחלוקת, „וישלח²⁵ משה לקרא לדתן ולאבירם . . ויאמרו לא נעלה“).\n— איז אָבער רש״י אַליין שולל דעם פירוש: אויף „וישלח²⁵ משה וגו׳“ איז רש״י מפרש „מכאן שאין מחזיקין במחלוקת שהי׳ משה מחזר אחריהם להשלימם בדברי שלום“. וויבאַלד רש״י איז משנה²⁶ פון דער גמרא (וואָס לערנט אָפ דעם ענין פון „אין מחזיקין במחלוקת“ פון אונזער פסוק „ויקם משה וילך גו׳“) און לערנט עס אָפ פון דעם פריערדיקן פסוק „וישלח משה גו׳“ (ובפרט ע״פ דיוק לשון רש״י „מכאן (שאין מחזיקין במחלוקת)“ — און ניט פון אַ צווייטן אָרט²⁷) איז דערפון מוכח, אַז לויט שיטת רש״י בפירושו על התורה, איז הליכת משה לדתן ואבירם ניט געווען מצד דעם ענין פון „אין מחזיקין במחלוקת“.\n[ובפרט — אויב מ׳זאָל זאָגן אַז אויך הליכת משה איז געווען צוליב „אין מחזיקין במחלוקת“, וואָלט דאָך מער מתאים געווען אַז מ׳זאָל דעם לימוד (והוראה) אָפלערנען פון אונזער פסוק „ויקם משה וילך גו׳“²⁸, היות אַז דוקא אין דעם פסוק איז דער חידוש אַז משה",[["18","18","ולהעיר ש„התרה בהם“ (שבמדרש) פירושו (לא דברי ריצוי להחזירם בתשובה, כ״א) כמו התראה לפני העונש — ראה פנים יפות כאן."],["19","19","תנחומא פרשתנו ג. במדב״ר פרשתנו פי״ח, ד."],["20","20","כאן."],["21","21","משא״כ בלשון „שישאו לו פנים“ שלא נזכר שיעשו תשובה, כ״א רק שישאו פנים למשה. אלא שי״ל בדוחק עכ״פ שמובן שזה יגרום שסו״ס יעשו תשובה."],["22","22","סנהדרין קי, א."],["23","23","טז, יא ובפרש״י."],["24","24","לשון רש״י סנהדרין שם."],["25","25","טז, יב."],["26","26","וכמו שהקשה המלקט בס׳ חדא״ג מהרש״א על התורה פרשתנו כאן."],["27","27","וי״ל שבזה שולל רש״י גם הלימוד (סנהדרין שם) ממש״נ (פרשתנו יז, ה) „ולא יהי׳ כקרח וכעדתו“, ד„כל המחזיק במחלוקת עובר בלאו“ — וכפרש״י פרשתנו שם „כדי שלא יהי׳ כקרח“ (וכמ״ש במפרשי רש״י שם) — כי הדין הזה כבר נלמד מן הפסוק „וישלח משה גו׳“."],["28","28","בכת״י רש״י אחדים שתח״י הובא (גם) כאן (עה״פ וילך אל דתן ואבירם) „מכאן שאין מחזיקין במחלוקת“. אבל ליתא בדפוס ראשון ושני דפרש״י, ולא ברוב כת״י רש״י שתח״י, ובדפוסי רש״י הנפוצים."]]],[1300281113,"„מחל על כבודו והוא עצמו הלך לבטל מחלוקת“²⁴, וואָס דערפון דאַרף מען אָפלערנען אויף וויפל עס דאַרף זיין דער „אין מחזיקין במחלוקת“ (משא״כ אין פריערדיקן פסוק וואו דער „מחזר אחריהם להשלימם“ איז בלויז געווען דורך אַ שליח)].\nמוז מען זאָגן, אַז הליכת משה לדתן ואבירם איז (ע״ד הפשט) ניט געווען צוליב דעם ענין פון „אין מחזיקין במחלוקת“²⁹, נאָר, כנ״ל, זיי צו מחזיר זיין בתשובה — והדרא קושיא לדוכתא.\nד. דער „שליסל“ צום ביאור אין דעם פירוש רש״י איז אָנגעדייט אין די ווערטער וועלכע רש״י איז מעתיק פון פסוק אין דעם דיבור־המתחיל\n— און ווי גערעדט כמה פעמים, אַז אין פירוש רש״י זיינען מדוייק ניט נאָר די ווערטער פון זיין פירוש גופא, נאָר אויך די ווערטער וועלכע ער איז מעתיק פון פסוק —\nובנדו״ד: רש״י איז מעתיק פון פסוק בלויז די ווערטער „ויקם משה“ ותו לא; נאָכמער: די ווייטערדיקע ווערטער איז ער אפילו ניט מרמז מיט אַ „וגו׳“.\nולכאורה תמוה: רש״י קומט דאָך לכאורה מפרש זיין דעם טעם פון הליכת משה אל דתן ואבירם — האָט ער זיך געדאַרפט שטעלן אויף די ווערטער „וילך אל דתן ואבירם“³⁰ (ואדרבה, די ווערטער „ויקם משה“ זיינען לכאורה דאָ ניט נוגע³¹); אבל רש״י מעתיק נאָר „ויקם משה“, און איז אפילו ניט מוסיף „וגו׳“!\nנאָר דערמיט וויל רש״י קלאָר מאַכן, אַז די שווערקייט אין פסוק וואָס ער קומט פאַרענטפערן איז בלויז אין די ווערטער „ויקם משה“ און בלויז די ווערטער קומט ער מפרש זיין.\nדאָס וואָס דער פסוק זאָגט „וילך (משה) אל דתן ואבירם“ איז מובן, וכנ״ל אַז דערמיט דערציילט דער פסוק ווי משה האָט גלייך מקיים געווען דעם ציווי ה׳ צו גיין אָנזאָגן „העדה“, די אידן, וועלכע זיינען דאַמאָלס געווען מסביב למשכן דתן ואבירם — „העלו“;\nמ׳דאַרף אָבער פאַרשטיין פאַרוואָס איז דער פסוק מקדים די ווערטער „ויקם משה“³² — וואָס גיט דער וואָרט „ויקם“ צו אינעם סיפור פון „וילך אל דתן ואבירם גו׳“?\nדערפון איז רש״י מכריח, אַז נוסף אויף הליכת משה אל דתן ואבירם, איז געווען אַ באַזונדער פעולה דורך „ויקם משה“.\nאין וואָס באַשטייט די פעולה פון „ויקם“ אַלס אַן ענין פאַר זיך (ניט אַלס הכנה צו דער הליכה שלאח״ז)? איז רש״י מפרש — „כסבור שישאו לו פנים“:\nרש״י האָט שוין פריער מפרש געווען, אויפן פסוק³³ „ויקם שדה עפרון“ — „תקומה היתה לו“. דאָס הייסט, אַז",[["29","29","וההכרח לזה בפשש״מ י״ל — דמשום „אין מחזיקין“ למה חכה משה עד עתה ללכת אליהם ולא הלך תיכף לאחרי שסירבו לבא אליו. וגם: לאחרי שכבר נגזר עליהם דינם מה׳ לא מסתבר שילך (רק) להשלים עמהם (ולא (גם) להחזירם בתשובה על חטאם)."],["30","30","וכתנחומא ובמדב״ר שנסמנו בהערה 7, 19."],["31","31","וברשב״ם כאן לא העתיק „ויקם משה“."],["32","32","ראה גם ס׳ זכרון על פרש״י כאן [אלא שהוא מפרש (לפי גירסתו בפרש״י — ראה לעיל הערה 5) שעל קושיא זו מתרץ רש״י „להודיע רשעתם כו׳ כלומר אע״פ שקם משה בעצמו כו׳“]. אוה״ח עה״פ."],["33","33","חיי שרה כג, יז."]]],[1300281114,"„ויקם“ ווייזט (אויך) אויף אַ קימה ועלי׳ בחשיבות.\nועד״ז בעניננו: דאָס וואָס דער פסוק איז מוסיף „ויקם משה“ קומט לאָזן הערן, אַז משה איז ניט סתם געגאַנגען צו משכן דתן ואבירם, נאָר דאָס איז געווען אינעם אופן פון „ויקם משה (וילך)“ — „תקומה היתה לו“³⁴, אַז ס׳איז געווען ווי די הליכה פון אַ מלך ומרומם מעם, וואָס רופט אַרויס אַ רגש של חשיבות וכבוד — און זיין כוונה דערביי איז געווען — „כסבור שישאו לו פנים“³⁵, אַז דאָס וועט פועל זיין ביי דתן ואבירם „שישאו לו פנים“.\n[דערמיט איז אויך מוסבר בפשטות וואָס דער פסוק איז ממשיך „וילכו אחריו זקני ישראל“ — דלכאורה, פאַרוואָס זיינען זיי מיטגעגאַנגען מיט משה, אשר לא ציווה אותם? אויך — למאי נפק״מ דאָס צו דערציילן?\nנאָר דאָס איז מדגיש אַז ס׳איז געווען אַ הליכה באופן של „ויקם“ — משה איז געגאַנגען אַלס מלך ונשיא ישראל און דערפאַר זיינען אים נאָכגעגאַנגען די זקני ישראל].\nה. לויט דעם ביאור איז אויך פאַרענטפערט די קושיא הנ״ל — ווי אַזוי האָט משה זיך אָפגעהאַלטן פון צו מקיים זיין באַלד דעם ציווי ה׳ און האָט זיך פאַרנומען מיט אַן אַנדער ענין?\n— וההסברה: לויט רש״י איז הליכת משה ניט געווען אויף צו מתרה זיין דתן ואבירם; ואדרבה: לויט פשוטו של מקרא דאַרף אויסקומען, אַז משה האָט גאָר ניט געטאָרט גיין מתרה זיין דתן ואבירם און משתדל זיין זיי מחזיר זיין בתשובה — ווייל דאָס איז היפך ציווי ה׳ „העלו מסביב למשכן קרח דתן ואבירם“ (אַז מען דאַרף זיך מסלק זיין פון זיי);\nנאָר דער מכוון ותכלית פון דער הליכה („וילך אל דתן ואבירם“) איז געווען צו וואָרענען די עדה, אַז זיי זאָלן זיך אָפקערן „מעל אהלי האנשים וגו׳“;\nס׳איז נאָר וואָס די הליכה איז געווען אינעם אופן פון „ויקם משה“, בכדי „שישאו לו פנים“ — טראַכטנדיק אַז אפשר וועט אַזאַ הליכה גורם זיין אַז „ישאו לו פנים“.\nאון דערפאַר איז עס קיין סתירה ניט צום ציווי „העלו גו׳“ — ווייל משה האָט זיך ניט דערנענטערט צו דתן ואבירם צו ווירקן אויף זיי דורך דיבור³⁶ אָדער אויף אַן אַנדער אופן אַז זיי זאָלן תשובה טאָן; ער האָט נאָר געהאָפט, אַז זיין הליכה (באופן של „ויקם“) וועט אויף זיי פועל זיין אַ הכנעה וביטול און „ישאו לו — זיי מצד עצמם — פנים“³⁷.\nו. דערפון האָט מען אַ לימוד נפלא אין דעם ענין פון אהבת ישראל:\nניט געקוקט אויף דעם וואָס דאָ איז שוין געווען נאָכן גזר דין, און נאָכמער: דער אויבערשטער האָט שוין כביכול „פאַרשלאָסן די טיר“ אויף תשובה און אָנגעזאָגט „העלו“, מ׳זאָל זיך פון זיי מסלק זיין —",[["34","34","ראה גם אוה״ח עה״פ."],["35","35","ולכן לא העתיק רש״י לשון המדרש „אולי יתביישו כו׳“ — כי אין לזה שייכות לענין ד„ויקם משה“."],["36","36","שלכן לא דיבר להם משה משהו, אלא רק „כסבור שישאו לו פנים“ — היינו רק בהופעתו באופן ד„ויקם“, כמלך כו׳."],["37","37","ויש לומר ב„יינה של תורה“ שבפרש״י — שמשה סבר דאף שכבר נגזר דינם ולא ישובו, מ״מ ע״י שיפעול עליהם „שישאו לו פנים“ ה״ז יגרום (מדה כנגד מדה) ש„ישא ה׳ פניו“ — „יכבוש כעסו“ (נשא ו, כו ובפרש״י)."]]],[1300281115,"פונדעסטוועגן, האָט משה רבינו — מצד זיין גרויסער³⁸ אהבת ישראל צו יעדן אידן, אין וואָס פאַר אַ מצב ער זאָל נאָר זיין (ווי מען געפינט אַז משה האָט זיך איינגעשטעלט במסירת נפש אפילו פאַר די עושי העגל³⁹) — האָט ער אויך אין דעם מצב געזוכט אַן עצה⁴⁰ ווי צו פועל זיין אויף דתן ואבירם און זיי ראַטעווען מרדת חיים⁴¹ שאולה.\nעאכו״כ אין אַ פאַל ווען עס רעדט זיך וועגן אידן וועלכע זיינען ניט קיין מורדים בה׳ ח״ו, נאָר זיינען עם־הארצים אין אידישקייט, אין דעם סוג פון תינוק שנשבה לבין העכו״ם — אַז עס ליגט אַ חוב אויף יעדערן צו טאָן כל התלוי בו, מיט דער גרעסטער השתדלות, און צו נוצן כל מיני התחכמות ותחבולות, צו געפינען אַן עצה ווי צו ראַטעווען די אידן און זיי צוריק מקרב זיין לאבינו שבשמים,\nאון דורך דעם וואָס מען פועל׳ט אויף זיי דעם „ואתם הדבקים בה׳ אלקיכם“ ווערט „חיים כולכם היום“⁴², חיים אמיתיים ונצחיים⁴³.\n(משיחת ש״פ קרח תש״מ)",[["38","38","דלולא זאת — מאי קמ״ל מחז״ל דאוהב ישראל הי׳ (מנחות סה, סע״א)."],["39","39","תשא לב, לב (ובפרש״י)."],["40","40","ועד״ז היתה הנהגת כ״ק מו״ח אדמו״ר — בעל הגאולה דג׳ תמוז (שחל בכו״כ שנים בסמיכות לפ׳ קרח, או — כבשנה זו (תשמ״ה) — בש״פ קרח עצמה) — לקרב כל יהודי, גם הרחוקים ביותר כו׳ (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011147\" data-slug=\"likkutei-sichot\" data-id=\"1300011147\">לקו״ש ח״א ס״ע 133</a> ואילך)."],["41","41","ולכן אפשרית תשובה. ולהעיר ממחז״ל דבני קורח „מקום נתבצר להם (שם) . . ואמרו שירה“ (סנה׳ קי, סע״א. רש״י פינחס כו, יא)."],["42","42","ואתחנן ד, ד. וראה אבות דר״נ פל״ד, י."],["43","43","ראה קונטרס ומעין מאמר ב בסופו (ואילך)."]]],[1300281116,"<h3>קרח ב</h3>\nא. אויף דעם וואס עס שטייט אין דער פרשה, אז דער אויבערשטער האט די כהונה ומתנות כהונה באשטימט פאר אהרן ובניו „לחק עולם ברית מלח עולם הוא לפני ה' לך ולזרעך אתך . . אני חלקך ונחלתך גו'\"1 — זאגט דער ספרי2 „ג' כתרים3 הם כתר תורה וכתר כהונה וכתר מלכות, כתר כהונה זכה אהרן ונטלו, כתר מלכות זכה דוד ונטלו, הרי כתר תורה מונח כדי שלא יתן פתחון פה לבאי העולם4 כו' הרי כתר תורה מונח לכל באי העולם4 שכל שזכה בו מעלה אני עליו כאילו שלשתם מונחים וזוכה בכולם\". און דער ספרי פירט אויס אז כתר תורה איז גרעסער פון די אנדערע כתרים, ווייל „כל עצמו של שני כתרים אין באים אלא מכחה של תורה וכן הוא אומר5 בי מלכים ימלוכו\".\nכעין דער דרשה ברענגט זיך אין גמרא6 (בקיצור): „שלשה זירים הן של מזבח ושל ארון ושל שלחן של מזבח זכה אהרן ונטלו של שלחן זכה דוד ונטלו של ארון עדיין מונח הוא כל הרוצה ליקח יבוא ויקח שמא תאמר פחות הוא ת\"ל בי מלכים ימלוכו\"7.\nדער רמב\"ם אין הלכות תלמוד תורה8 ברענגט אויך די דרשה, וז\"ל: בשלשה כתרים נכתרו ישראל כתר תורה וכתר כהונה וכתר מלכות, כתר כהונה זכה בו אהרן שנאמר9 והיתה לו ולזרעו אחריו ברית כהונת עולם, כתר מלכות זכה בו",[["1","1","יח, יט-כ."],["2","2","פיסקא קיט."],["3","3","בספרי מתחיל „נמצאת אומר ג' כתרים כו'\". וראה בפרטיות במפרשי הספרי — הפירוש ב„נמצאת אומר\" בהמשך למ\"ש לפנ\"ז שם."],["4","4","הלשון „לבאי העולם\", „לכל באי העולם\" (ועד\"ז הוא במדרש שמואל דלקמן הערה 7) לכאורה אין הכוונה לכל בני אדם, שהרי ג' כתרים אלו נתנו רק לישראל. כפשוט ומפורש ברמב\"ם דלקמן בפנים. ועוד. וכדמוכח גם בספרי שם — כ\"א הכוונה ע\"ד הלשון „כולא עלמא\" שבש\"ס וכיו\"ב. אבל דוחק גדול לפרש כן בהלשון „באי העולם\" (משא\"כ „כולא עלמא\" שבש\"ס שמתייחס לכל בעלי הפלוגתא וכו', שבסוגיא) — ואפ\"ל כפשוטו דאומות העולם פותחים פה ובאים בטענה דעשיית עוול בכלל (וגם בנוגע לכתר תורה דז' מצות דידהו) וע\"ז המענה דמונח לכולם. ומפורש הוא במדרש לקח טוב ר\"פ חוקת: כדי שלא ליתן פתחון פה לאומות העולם. ואכ\"מ. — וראה ר\"ה פ\"א מ\"ב „באי עולם\" וברמב\"ם הל' תשובה פ\"ג ה\"ג (מהמשנה) „מבאי העולם\". ועד\"ז ברמב\"ם שם פ\"ו ה\"ג. סוף הל' שמיטה ויובל. הל' מלכים פ\"ח ה\"י. וברמב\"ם סוף הל' ס\"ת, הל' סנהדרין פי\"ב ה\"ג: כל באי עולם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131236\" data-slug=\"likkutei-sichot\" data-id=\"1300131236\">לקו\"ש חי\"ג ע' 230</a>. וש\"נ. ואכ\"מ."],["5","5","משלי ח, טו."],["6","6","יומא עב, ב."],["7","7","ועד\"ז הוא בקה\"ר פ\"ז, א (ב). מדרש שמואל פכ\"ג. ובשניהם מסיים (ע\"ד לשון הספרי) „כל מי שזוכה לתורה כאילו זוכה לשלשתן וכל שלא זכה כו'\" (קה\"ר. ובאריכות יותר במדרש שמואל שם). בנוגע ג' הכתרים, והמעלה דכתר תורה (שכל הזוכה בו כאילו זוכה בכולם) — ראה ג\"כ שמו\"ר פל\"ד, ב. תנחומא ויקהל ח בסופו. במדב\"ר פ\"ד, יד בסופו (פי\"ד, יוד — ושם אינו מסיים במעלת כתר תורה). יל\"ש משלי רמז תתקמא."],["8","8","רפ\"ג."],["9","9","פינחס כה, יג. *) וראה (באו\"א) <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271260\" data-slug=\"likkutei-sichot\" data-id=\"1300271260\">לקו\"ש חכ\"ז ע' 246</a> ואילך. *) אלא שבמדרש שמואל, במדב\"ר פ\"ד שם (ועד\"ז במדרש לקח טוב) מסיים גם „וכתר שם טוב עולה על גביהן\". וראה גם קה\"ר שם (ג)."]]],[1300281117,"דוד שנאמר10 זרעו לעולם יהי' וכסאו כשמש נגדי, כתר תורה הרי מונח ועומד ומוכן לכל ישראל שנאמר11 תורה צוה לנו משה מורשה קהלת יעקב כל מי שירצה יבוא ויטול שמא תאמר שאותם הכתרים גדולים מכתר תורה כו'.\nדארף מען פארשטיין: אין ש\"ס שטייען ניט קיין ראיות פון פסוקים, אע\"פ אז ער איז בלול פון הלכה, מקרא שקו\"ט וכו' (ועד\"ז בספרי<sup data-n=\"12\">12</sup> — און דוקא דער רמב\"ם בספרו וועלכער איז „הלכות הלכות\"13 בריינגט ראיות פון די פסוקים?\nב. אין הגהות מיימונית14 איז אנגעצייכנט דער מקור פון דברי הרמב\"ם (ניט נאר אין מס' יומא — ווי אין כסף משנה15 — נאר אויך) אין אבות דר\"נ16 — און דארטן ווערן טאקע געבראכט ראיות פון פסוקים אויף אלע דריי כתרים.\nאבער:\nא) דארטן זיינען צוויי פון די פסוקים ניט די וועלכע דער רמב\"ם ברענגט.\nב) ועיקר: אין אדר\"נ זיינען די ראיות פון די פסוקים ניט אויף דעם צד החיוב ווי דער רמב\"ם ברענגט זיי, נאר לצד השלילה, אז כתר כהונה וכתר מלכות קען מען ניט באקומען, משא\"כ כתר תורה, וז\"ל (באבות דר\"נ): „כתר כהונה כיצד אפילו נותן (לו) כל כסף וזהב שבעולם אין נותנים לו כתר כהונה שנאמר9 והיתה לו . . כתר מלכות אפילו נותן כל כסף וזהב שבעולם אין נותנים לו כתר מלכות שנאמר17 ודוד עבדי נשיא להם לעולם18 אבל כתר תורה אינו כן עמלה של תורה כל הרוצה ליטול יבא ויטול שנאמר19 הוי כל צמא לכו למים\"20.\nנאך אן ענין אין רמב\"ם דא איז בולט אין פארגלייך מיט זיין לשון במק\"א (אין הל' מלכים<sup data-n=\"21\">21</sup>: „כיון שנמשח דוד זכה בכתר מלכות והרי המלכות לו ולבניו הזכרים עד עולם שנאמר22 כסאך יהי' נכון עד עולם\" — ניט דער פסוק וואס ער ברענגט דא ביי „כתר מלכות זכה בו דוד — זרעו . . וכסאו וגו'\".\nאויך בנוגע דעם ערשטן פסוק, וועלכן דער רמב\"ם ברענגט דא אלס ראי' אז אהרן האט זוכה געווען צו כתר כהונה — „שנאמר והיתה לו ולזרעו אחריו ברית כהונת עולם\"23 — פאדערט זיך",[["10","10","תהלים פט, לז."],["11","11","ברכה לג, ד."],["12","12","וראה לקמן הערה 27."],["13","13","הקדמת הרמב\"ם לספר היד (סד\"ה ובזמן הזה)."],["14","14","לרמב\"ם הל' ת\"ת שם סק\"א."],["15","15","ועד\"ז הוא בלחם משנה ובשו\"ע אדה\"ז הל' ת\"ת רפ\"ד שהובא לקמן בפנים. ובמגדל עז לרמב\"ם „הכל ביומא פרק בא לו ובמסכת אבות\"."],["16","16","והוא שם רפמ\"א."],["17","17","יחזקאל לז, כה."],["18","18","ראה בנין יהושע לאדר\"נ שם שמסביר הטעם שהובאו באדר\"נ דוקא פסוקים אלה ע\"ד כהונה ומלכות, כי בהם מודגש ששייכים גם בזמן הזה. ע\"ש. אבל לכאורה לא זו (עיקר) ההדגשה באדר\"נ, כ\"א דכתר תורה שייך לכאו\"א, משא\"כ כתר כהונה וכתר מלכות."],["19","19","ישעי' נה, א."],["20","20","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061309\" data-slug=\"likkutei-sichot\" data-id=\"1300061309\">לקו\"ש ח\"ו (ע' 299</a> ושם ע' 301) הביאור בשינוי הפסוקים שברמב\"ם ואדר\"נ שם."],["21","21","פ\"א ה\"ז."],["22","22","ש\"ב ז, טז."],["23","23","להעיר גם שברבינו יונה לאבות פ\"ד מי\"ב הובאו הפסוקים בנוגע לכתר כהונה וכתר מלכות כברמב\"ם. ואולי הי' לפני הרמב\"ם ורבינו יונה"]]],[1300281118,"הסברה: „והיתה לו\" מיינט דאך דער פסוק בפשטות ניט די כהונה (הרגילה) וואס אהרן האט זוכה געווען, נאר די כהונה וואס איז געגעבן געווארן אלס א הוראה מיוחדת צו פינחס בן אלעזר („ולזרעו אחריו\").\nאיז ניט מובן, פארוואס ברענגט דער רמב\"ם דעם פסוק24 וואס רעדט ניט וועגן אהרן25, און ניט פריערדיקע פסוקים אין תורה וועלכע באציען זיך בפירוש צו כהונה הרגילה — אהרן ולכל בניו (ובפרט, אז ער הויבט אן מיטן לשון: „זכה בו אהרן . .\"), וכבפרשתנו „ברית מלח עולם הוא26 גו' לך ולזרעך אתך\"27 (וכיו\"ב)28, ווי רש\"י ברענגט עס טאקע אין גמרא29.\nאויך דארף מען פארשטיין נאך א שינוי לשון אין רמב\"ם לגבי דעם לשון אין ספרי און אין גמרא: דארט שטייט „זכה אהרן ונטלו . . זכה דוד ונטלו\"30,",[["","","מדרש (שלא הגיע לידינו) ששם הובאו פסוקים אלה. או שכן היתה גירסתם באבות דר\"נ — ע\"ד שהמפרשים מתרצים בכ\"מ דברי הרמב\"ם שם. — וראה בהנסמן בהערה 20 וראה הערה הבאה."],["24","24","ואף שפסוק זה הובא גם באדר\"נ, הרי אין זה מכריח שהרמב\"ם יביא הפסוק (ואדרבה, דרכו להביא פסוק שהוא מבואר יותר אע\"פ שזהו דלא כרז\"ל — כידוע בכללי הרמב\"ם (ראה יד מלאכי כללי הרמב\"ם אות ד)), וכבהלכה זו גופא שמביא (בנוגע מלכות ותורה) פסוקים אחרים ולא הפסוקים שבאדר\"נ."],["25","25","ובפרט דלא נתכהן פינחס עד שהרגו לזמרי (זבחים קא, ב. פרש\"י פינחס כה, יג) שהפסוק קאי רק על פינחס ולא בנוגע לשאר בני אהרן הכהנים. וגם לדיעה הב' בזבחים שם מפרש הפסוק „והיתה לו ולזרעו אחריו\" — „בברכה הוא דכתיב\" — שקאי רק על פינחס וזרעו, כפרש\"י שם ד\"ה ההוא „בשרו שלא תפסק כהונה מזרעו\" [וראה תוד\"ה ואידך שם (לדיעה דנתכהן כשהרגו לזמרי), מספרי (ס\"פ בלק) שעמדו ממנו (מפינחס) שמונים כהנים כו' (וראה בהנסמן שם וגירסת הספרי לפנינו), אלא דשם מפיק לה (מהפסוק שלפנ\"ז) „את בריתי שלום\"]."],["26","26","ובמכילתא בתחלתו: עד שלא נבחר אהרן היו כל ישראל כשרים לכהונה משנבחר אהרן יצאו כל ישראל, ומביא ב' פסוקים: דפרשתנו (ברית מלח עולם), ודפ' פינחס (והיתה לו ולזרעו אחריו)."],["27","27","ובספרי שם משמע קצת (אף שאינו מפורש שם), דכתר כהונה שייך להנאמר בפרשתנו — ראה שם בתחלתו: וערער על הכהונה . . למלך ב\"ו כו' (והובא בפרש\"י (ספרי) פרשתנו בתחלת הענין (יח, ח)). וראה גם בספרי שם על הפסוק (שם, יט-כא) ברית מלח . . ולבני לוי: מגיד הכתוב כו'."],["28","28","בפשטות יש לומר הטעם כי בהכתוב דפרשתנו לא הוזכר הלשון כהונה (בנוגע „לו ולזרעו\") כבפינחס. ועד\"ז מובן בנוגע להפסוק בתצוה (כח, מג) „חקת עולם לו ולזרעו אחריו\" ולא נאמר לשון כהונה*. אבל עדיין צ\"ע שהרי לכאורה עיקר הראי' צ\"ל ממקום שבו מפורש יותר הענין דכהונת עולם לאהרן, משא\"כ הפסוק ד„והיתה לו ולזרעו אחריו\" המדובר בפינחס. וראה גם פקודי (מ, טו — הובא בבנין יהושע לאדר\"נ שם) „והיתה להיות להם משחתם לכהונת עולם לדורותם\"."],["29","29","יומא (שבהערה 6) — ד\"ה הכי גרסינן „שהכהונה נתנה לאהרן ברית מלח\". ועד\"ז הובא באדר\"נ נוסחא ב' רפמ\"ח „כתר כהונה זו כתרו של אהרן . . שנאמר ברית מלח עולם היא לפני ה'\". ולהעיר, שבנוגע למלכות כתב רש\"י ביומא שם „וכן המלכות לדוד ולזרעו\" (ולגירסא זו — אין מוכרח שכוונתו לפסוק (כנסמן בדפוסי רש\"י שלפנינו — לתהלים יח, נא. וכ\"ה בש\"ב כב, נא), משא\"כ להגירסא ברש\"י שבע\"י „לדוד ולזרעו עד עולם\"). ובאבות דר\"נ שם נוסחא ב' הובא הפסוק (דה\"ב יג, ה) הלא לכם לדעת כי ה' אלקי ישראל נתן (המלוכה) [ממלכה] לדוד (ולהעיר שגם בפסוק זה מסיים „ברית מלח\"). וכתוב זה הובא גם במכילתא בתחלתו ע\"ז ד„משנבחר דוד יצאו כל ישראל שנאמר הלא לכם לדעת גו'\"."],["30","30","וכ\"ה בקה\"ר ומדרש שמואל שם. מדרש לקח טוב שם. *) וראה פרש\"י שם שהכתוב בכלל לא קאי על עצם הכהונה אלא „גזירה מיד ולדורות\" (לגבי המשמש מחוסר בגדים)."]]],[1300281119,"משא\"כ אין רמב\"ם איז ער משמיט „ונטלו\" און זאגט: כתר כהונה זכה בו אהרן, כתר מלכות זכה בו דוד.\nג. די הלכה הנ\"ל אין רמב\"ם איז דער אלטער רבי מעתיק בהל' ת\"ת שלו31 און ער איז טאקע משמיט די פסוקים הנ\"ל, וואס ווערן געבראכט אין רמב\"ם אויף דעם וואס כתר כהונה זכה בו אהרן און כתר מלכות זכה בו דוד.\nזאת ועוד: ביים ענין פון כתר תורה זאגט דער אלטער רבי דארט „כתר תורה הרי הוא מונח ועומד ומוכן לכל ישראל כל מי שירצה יבוא ויטול שנאמר מורשה קהלת יעקב שהיא ירושה לכל ישראל\". ד.ה. אז אויך ביי כתר תורה (וואו דער אלטער רבי ברענגט יע א פסוק — דעם זעלבן ווי אין רמב\"ם) איז ער (א) משנה ומהפך דעם סדר ווי אין רמב\"ם: פריער זאגט ער „כל מי שירצה יבוא ויטול\", און דערנאך ברענגט ער דעם פסוק — משא\"כ אין רמב\"ם איז עס בסדר הפוך; (ב) דער אלטער רבי איז מוסיף „שהיא ירושה לכל ישראל\" וואס שטייט ניט אין רמב\"ם32.\nד. וועט מען דאס פארשטיין בהקדים הביאור אויף א תמי' אין כללות הענין:\nדער רמב\"ם איז, כנ\"ל, א ספר פון „הלכות הלכות\" — וואס איז נוגע להלכה דא, אין הל' ת\"ת, אז „בשלשה כתרים נכתרו ישראל\", און אז כתר כהונה זכה בו אהרן און כתר מלכות זכה בו דוד?\nלכאורה יש לומר, אז דאס איז א הקדמה וועלכע ברענגט ארויס די מעלה מיוחדת פון (כתר) תורה, אז זי איז העכער פון (כתר) כהונה ומלכות („כתר תורה גדול משניהם\", ווי דער רמב\"ם פירט אויס אין דער הלכה) — און דער ענין איז נוגע להלכה, ווי דער רמב\"ם איז ממשיך33 „אמרו חכמים34 ממזר ת\"ח קודם לכהן גדול עם הארץ שנאמר35 יקרה היא מפנינים מכהן גדול שנכנס לפני ולפנים\".\nדאס איז אבער ניט מספיק, ווארום אי משום הא — איז ניט נויטיק די גאנצע אריכות און ס'איז מספיק צו דערמאנען נאר בקיצור אז עס זיינען דא נאך צוויי כתרים, כתר כהונה וכתר מלכות;\nועוד (ועיקר): אויב דער רמב\"ם איז דא אויסן די הלכה פון „ממזר ת\"ח קודם כו'\", וואלט ער געדארפט מפרט זיין אין וואס עס באשטייט דער ענין פון „קודם\"36 — ווי מ'געפינט עס אין דער משנה37 וואו דאס קומט בהמשך צו די דינים (אין דער משנה שלפני'<sup data-n=\"37\">37</sup> ווער ס'איז קודם להחיותו ולפדותו (און די דינים בריינגט דער רמב\"ם שפעטער ומפורש אין הלכות מתנות עניים<sup data-n=\"38\">38</sup>.",[["31","31","פ\"ד בתחלתו."],["32","32","זה שבשו\"ע אדה\"ז מביא מהפסוק רק „מורשה קהלת יעקב\" ומשמיט תחלת הכתוב שברמב\"ם, לכאורה — כי כן הי' גירסתו ברמב\"ם, וכמו שהוא בכמה דפוסי וכת\"י דהרמב\"ם (נסמנו ברמב\"ם שבהערה 36). — ועפ\"ז תבטל מעיקרא השאלה דתחילת הכתוב אינו מוכרח להביאו כאן."],["33","33","בה\"ב שם."],["34","34","הוריות יג, א — במשנה (והראי' מפסוק — בגמרא שם)."],["35","35","משלי ג, טו."],["36","36","ולהעיר מהגירסא ברמב\"ם (ראה רמב\"ם ספר המדע — ירושלים תשכ\"ד) „חשוב\" במקום „קודם\"."],["37","37","הוריות שם."],["38","38","ספ\"ח."]]],[1300281120,"דערפון איז מובן, אז דער ענין פון די אלע דריי כתרים ופרטיהם — אז „כתר כהונה זכה בו אהרן\", ו„כתר מלכות זכה בו דוד\" — איז א זאך וואס איז נוגע להלכה (אויך) צו דער מעלה פון (כתר) תורה כשלעצמו, ניט נאר אלס הקדמה צו איר מעלה לגבי די אנדערע כתרים39. והדרא קושיא לדוכתא: וואס גיט דאס צו אין דער הסברה פון כתר תורה?\nמען קען ניט זאגן, אז דער רמב\"ם מיינט דערמיט בלויז צו מדגיש זיין די אנדערשקייט פון כתר תורה — אז אין דער צייט וואס כתר כהונה וכתר מלכות זיינען ניט שייך צו אלע אידן (ווייל „זכה בו אהרן . . זכה בו דוד\") איז אבער כתר תורה יע שייך צו אלע אידן (ע\"ד ווי אין אבות דר\"נ) — ווארום דעמאלט וואלט עס דער רמב\"ם געזאגט מיט א לשון יותר מתאים לזה — בלשון של שלילה (ע\"ד ווי אין אבות דר\"נ) או כיו\"ב40.\nה. דער ביאור בזה40*:\nלשונו המדויק דהרמב\"ם — איז מבאר דעם גדר וענין פון כתר תורה.\nדער לשון „כתר תורה\" ווערט געבראכט אין ש\"ס בנוגע לכמה ענינים, בתוכן שונה, ולדוגמא:\nאין מס' נדרים41 „אוי לי שנשתמשתי בכתרה של תורה\", „כל המשתמש בכתרה של תורה\", וואס דערמיט ווערט געמיינט כבוד התורה42;\nאין מס' מגילה43 (לויט דער גירסא שלפנינו<sup data-n=\"44\">44</sup> „ודאשתמש בתגא חלף . . זה המשתמש במי ששונה הלכות כתרה של תורה\" — מיינט דאס „הלכות\"45 שבתורה. ועוד46.\nעד\"ז איז אויך בלשון הרמב\"ם, אז „כתרה של תורה\" האט אין זיך מובנים שונים — בהתאם צום ענין המדובר. מען געפינט אז דער רמב\"ם נוצט דעם לשון „כתרה של תורה\" מיינענדיק בעיקר מעלת47 התורה (או הבנת התורה וכיו\"ב), ווי לדוגמא — אין דער הלכה48 „לא ישא אדם בת עמי הארץ . . שאם מת או גולה בניו עמי הארץ יהיו שאין אמן יודעת כתר התורה\".\nאבער אין דער הלכה שלפנינו, וואו ער ברענגט דעם מאמר רז\"ל בנוגע די ג' כתרים, מיינט עס ניט כבוד התורה און ניט דעם ענין פון הלכות התורה",[["39","39","ולהעיר שהלכה זו (אמרו חכמים ממזר ת\"ח כו') כתבה הרמב\"ם בהלכה בפ\"ע. אבל (א) לכמה גירסאות אינה הלכה בפ\"ע, ובאה בהמשך להלכה א (ראה רמב\"ם הנ\"ל הערה 36, וש\"נ). (ב) בהל' ת\"ת לאדה\"ז שם בא בהמשך אחד. וראה לקו\"ש חל\"ג ע' 42 ואילך."],["40","40","ע\"ד הלשון ביל\"ש משלי שם. ועוד. 40*) וראה בהבא לקמן (באו\"א קצת) לקו\"ש חל\"ג שם."],["41","41","סב, א."],["42","42","ראה רש\"י ור\"ן שם. וכן הובא ומפורש בהל' ת\"ת לאדה\"ז שם סי\"ד-טו. אבל ברמב\"ם שם פ\"ג ה\"י, כשמדבר על „כבוד התורה\", לא הובא הלשון „משתמש בכתרה של תורה\", כ\"א: הנהנה מדברי תורה. וראה לשון הרמ\"א יו\"ד סי' רמו סכ\"א. לקמן הערה 45."],["43","43","כח, ב."],["44","44","וכ\"ה בע\"י לפנינו. וכן הובא באגה\"ק סכ\"ט."],["45","45","כמבואר באגה\"ק שם. ולגירסת הב\"ח (וכ\"ה בכמה גי' — ראה דק\"ס מגילה שם) שליתא התיבות „כתרה של תורה\" לכאורה הפי' שם (כמו בנדרים) שמשתמש במי ששונה הלכות, היינו שמשתמש בכבוד התורה (של מי ששונה הלכות). וראה רמ\"א שם. ובש\"ך שם סקכ\"ב-כג. באר היטב שם סקי\"ד."],["46","46","וראה שו\"ע אדה\"ז או\"ח סנ\"ג סל\"ג."],["47","47","בפיה\"מ להרמב\"ם אבות שם (במשנה „שלשה כתרים הם כו'\"): אלו השלש מעלות טובות נתנו לאומה זו כו', ומשמע דמפרש „כתר\" מלשון „מעלות\" (ובהוצאת קאפח „מעלות הגדולות כו'\")."],["48","48","הל' איסורי ביאה ספכ\"א."]]],[1300281121,"אדער סתם לימוד התורה, נאר א מעלה מיוחדת49 אין ענין התורה בכלל50.\n— און כדי צו ארויסבריינגען קלערער דעם גדר פון „כתר תורה\" (בהלכה זו), ברענגט דער רמב\"ם וועגן כתר כהונה וכתר מלכות און די ראיות פון די פסוקים, כדלקמן.\nו. כתר כהונה און כתר מלכות איז ניט עבודת הכהונה און שלטון המלכות כשלעצמם — ווארום נאך איידער אהרן האט זוכה געווען צו כתר כהונה איז געווען כהן ועבודת הכהונה; עד\"ז בנוגע למלכות, איז מלכות שוין געווען פריער בא שאול'ן, נאך איידער דוד האט זוכה געווען צו כתר מלכות.\nאין וואס באשטייט דער אויפטו פון „כתר כהונה\" און „כתר מלכות\"? זאגט דער רמב\"ם: „כתר כהונה זכה בו אהרן שנאמר והיתה לו ולזרעו אחריו ברית כהונת עולם, כתר מלכות זכה בו דוד שנאמר זרעו לעולם יהי' וכסאו כשמש נגדי\" — ד.ה. אז בשעת מ'איז זוכה צו כתר כהונה און כתר מלכות בלייבט עס אן ענין נצחי, „לו ולזרעו גו' כהונת עולם\", „זרעו לעולם\". און ווי דער רמב\"ם פסק'נט אין הל' מלכים (בנוגע למלכות): „כיון שנמשח דוד זכה בכתר מלכות והרי המלכות לו ולבניו הזכרים עד עולם\".\nמען דארף אבער פארשטיין: דער רמב\"ם פסק'נט דאך אז „המלכות ירושה\"51, ניט נאר מלכות דוד, נאר מלכות בכלל (אפילו ביי מלכי ישראל). נאכמער: „ולא המלכות בלבד אלא כל השררות וכל המינויין שבישראל ירושה לבנו ולבן בנו עד עולם\"52 — איז ווי פארבינדט דער רמב\"ם די מעלה פון „כתר מלכות\" דערמיט וואס „המלכות לו (צו דוד'ן) ולבניו . . עד עולם\" [ועד\"ז כתר כהונה — אז „והיתה גו' ברית כהונת עולם\"]?\nז. איז דער ביאור בזה53:\nבשעת דער רמב\"ם איז מבאר דעם ענין פון מלכות ביי מלכי ישראל, זאגט ער54: „נביא שהעמיד מלך משאר שבטי ישראל והי' אותו המלך הולך בדרך התורה והמצות ונלחם מלחמות ה' הרי זה מלך וכל מצות המלכות נוהגות בו אע\"פ שעיקר המלכות לדוד ויהי' מבניו (פון דעם מלך ישראל) מלך\". ד.ה. אז אפילו ווען ס'איז דא מלכות ביי מלכי ישראל (און אין אן אופן וואס „ויהי' מבניו מלך\", עס גייט איבער בירושה לבניו) — פארבלייבט „עיקר המלכות\" ביי דוד דוקא. „עיקר המלכות\" איז ניטא ביי מלכי ישראל.\nדי הסברה אין דעם: דער מלך און מלכות קען זיין אויף צוויי אופנים54*: א) מען הייסט א מלך דערפאר וואס מען",[["49","49","ועד\"ז ברמב\"ם הל' מלכים שם „כיון שנמשח דוד זכה בכתר מלכות והרי המלכות לו ולבניו כו'\"."],["50","50","וכן הלשון כתר תורה שם ה\"ו; ה\"ז; הי\"ג. וי\"ל שלכן בה\"י שם לא הזכיר הלשון „כתרה של תורה\" בנוגע לכבוד התורה (כנ\"ל הערה 42), כי המושג „כתר תורה\" בפרק זה אינו במובן של כבוד התורה וכיו\"ב, כבענין משתמש בכתרה של תורה."],["51","51","הל' כלי המקדש פ\"ד ה\"כ. הל' מלכים שם."],["52","52","הל' מלכים שם. ועד\"ז בהל' כלי המקדש שם."],["53","53","בהבא לקמן (בנוגע למלכות דוד) — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251110\" data-slug=\"likkutei-sichot\" data-id=\"1300251110\">לקו\"ש חכ\"ה ע' 110</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410163\" data-slug=\"likkutei-sichot\" data-id=\"1301410163\">ח\"ל ע' 99</a> ואילך."],["54","54","הל' מלכים שם ה\"ח. 54*) להעיר מהמשך תער\"ב פרק קכב. *) נת' בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271257\" data-slug=\"likkutei-sichot\" data-id=\"1300271257\">לקו\"ש חכ\"ז ע' 243</a> ואילך. וראה גם לקו\"ש חל\"ד ע' 43 ואילך."]]],[1300281122,"פירט דורך דעם תפקיד פון מלכות, פעולות והנהגות המלוכה (אשר יוציאם ואשר יביאם55, הפרטים שביארם שמואל<sup data-n=\"56\">56</sup> — ולכאורה אפשר גם ע\"י משנה למלך, אויב זיין מינוי איז אז „רק הכסא אגדל ממך\"57. ב) מ'איז בשלימות ובעצם58 א מלך59.\nאון דאס איז „עיקר המלכות\": דאס וואס בית דוד האט מלוכה איז ניט נאר וואס זיי זיינען בפועל מלכים (און פירן דורך דעם תפקיד פון מלוכה)60, נאר ביי זיי איז פאראן „עיקר\" — עצם גדר המלכות.\nאון דאס איז דער ענין פון „כתר מלכות\" — ס'איז (ניט נאר מלוכה בפועל, נאר) עצם גדר המלכות.\nח. עפ\"ז יובן דער אויפטו אין דעם וואס בשעת דוד „זכה בכתר מלכות . . המלכות לו ולבניו . . עד עולם\" — ווייל בהתאם צו דעם שינוי אין דער „חפצא\" של מלוכה, קומט א שינוי אין דעם „גברא\", דעם מלך:\nבשעת די מלוכה איז בלויז אין אן אופן פון א מינוי למילוי תפקיד (אזוי ווי „כל השררות וכל המינויין\"), איז דאס א דבר נוסף אויף זיין מציאות, ער פארמאגט מלוכה (ע\"ד ווי ער פארמאגט נכסים). און דעריבער, דאס וואס זיין מלוכה גיט זיך איבער בירושה לבניו, איז דאס בדומה צו יעדער ירושת נחלה: ע\"ד ווי מען ירש'נט אלע נכסים פון דעם מוריש, אזוי ירש'נט מען זיין תפקיד און מינוי61. און ווי דער רמב\"ם זאגט „וכל הקודם בנחלה קודם לירושת המלוכה\"62, „וכל הקודם לנחלה קודם לשררות המת\"63.\nבשעת אבער מ'איז זוכה צו כתר מלכות — מ'האט דעם „עיקר\" המלכות, ווערט עס אזוי אויך ביים גברא (א שינוי בגברא)64, אז דעמאלט ווערט דער ענין המלכות ביי אים (ניט א הוספה אויף זיין עיקר, נאר דאס ווערט) זיין מהות און עיקר — זיין מציאות איז מציאות ועצם פון מלך65.\nאון דערפאר זאגט דער רמב\"ם אין ספר המצות66, אז יעדער מלך וואס איז",[["55","55","פינחס כז, יז."],["56","56","ש\"א ח, יוד ואילך. רמב\"ם הל' מלכים פ\"ד."],["57","57","מקץ מא, מ."],["58","58","אולי י\"ל נפק\"מ בנוגע למלך כיון שכרע שוב אינו זוקף (ברכות לד, רע\"ב. רמב\"ם הל' תפלה פ\"ה ה\"י) — שבשעת תפלתו אין (ואסורים) פעולות דמלכות."],["59","59","ובנוגע לדוד באותן ששה חדשים דאינו מתכפר כמלך (ראה ירושלמי ר\"ה פ\"א ה\"א. הוריות פ\"ג ה\"ב) — ראה לקו\"ש חכ\"ה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251107\" data-slug=\"likkutei-sichot\" data-id=\"1300251107\">שם ע' 107</a> הערה 21, משו\"ת אבני נזר יו\"ד סשי\"ב — די\"ל דגם אז הי' לו דין מלך אלא דבשעיר יש דין מיוחד. ע\"ש."],["60","60","לא רק לפי מש\"כ הרמב\"ן עה\"ת (ויחי מט, יו\"ד) דשאר המלכים אשר לא ממלכי בית דוד הוי „כמו שופטים ושוטרים\", אלא גם לדעת הרמב\"ם הנ\"ל ד„נביא שהעמיד מלך כו' הרי זה מלך וכל מצות המלך עליו\", הרי כתב שאי\"ז „עיקר המלכות\", וראה השגות הראב\"ד שם ה\"ט."],["61","61","ועד\"ז בנוגע לירושה דכהן גדול המבואר בהל' כלי המקדש."],["62","62","הל' מלכים שם."],["63","63","הל' כלי המקדש שם."],["64","64","להעיר מרמב\"ם הל' תשובה פ\"ח ה\"ב: „וכן זה שאמרו עטרותיהם בראשיהן כלומר דעת שידעו שבגללה זכו לחיי העולם הבא מצוי' עמהן והיא העטרה שלהן . . כך עטרה שאמרו חכמים כאן היא הידיעה\". ומזה מובן שאף שכתר — עטרה כפשוטו הוא למעלה ונפרד מהראש, הרי ענינו ותוכנו שמשנה (נעשה חלק מ)מציאותו."],["65","65","להעיר דעדות הוא לבית דוד שכל הראוי למלכות הולמתו (הכתר) — ע\"ז מד, סע\"א — „ויושבת בראשו יפה כו'\" (פרש\"י שם ד\"ה הולמתו)."],["66","66","מל\"ת שסב."]]],[1300281123,"ניט פון „זה הזרע הנכבד (בית דוד) לענין מלכות נכרי קרינא בי' כמו זרע אחר בלתי זרע אהרן לענין עבודה זר קרינא בי'\".\nובמילא ווערט דאס אן ענין נצחי — לו ולבניו עד עולם.\nוויבאלד דאס איז דער עצם ומהות פון אביו, און דער יורש איז די מציאות פון מוריש איז עס במילא דער עצם ומהות פון בניו און אזוי יורשו (הבן) — עד עולם.\nאון דאס איז די הסברה אין פסק הרמב\"ם (בנוגע למלכות דוד)67: „מלכי בית דוד הם העומדים לעולם . . אבל אם יעמוד מלך משאר ישראל תפסק המלכות מביתו\" — ווייל כאטש אז אויך ביי מלכי ישראל גייט איבער די מלכות בירושה (וכקושיית הראב\"ד<sup data-n=\"67\">67</sup>, פארמאגט עס אבער ניט די מעלה פון נצחיות. משא\"כ „מלכי בית דוד הם העומדים לעולם\" — ווייל „זכה (דוד) בכתר מלכות\" איז עס פארבונדן מיט דעם עצם ומהות פון מלכות ומלך.\nאון כשם ווי דאס איז בנוגע למלכות, עד\"ז איז בנוגע לכהונה: עס איז דא די עבודת הכהונה, שירות הכהונה בפועל; דערנאך איז דא וואס „כתר כהונה זכה בו אהרן\" — אהרן האט זוכה געווען אין כתר כהונה, דער עצם הכהונה. און וויבאלד ער האט דעם עצם הכהונה, איז כהונה פארבונדן געווארן מיט זיין עצם [ע\"ד ווי דער ענין היהדות וואס איז דער עצם ומהות פון א אידן (ועד\"ז בגר וואס נתגייר כהלכה)].\nאון דערפאר איז דער ענין הכהונה ביי אים אין אן אופן פון „לו ולזרעו אחריו ברית כהונת עולם\" — באופן נצחי, כנ\"ל בנוגע למלך.\nט. עפ\"ז וועט מען אויך פארשטיין פארוואס דער רמב\"ם, ריידנדיק וועגן די „שלשה כתרים\", זאגט ער „זכה בו אהרן . . זכה בו דוד\" — און איז משמיט „ונטלו\":\nפעולות הנהגות המלוכה, ועד\"ז עבודת הכהונה — איז שייך דערויף זאגן „ונטלו\", מען נעמט און טוט (בפועל). אבער „כתר כהונה\" און „כתר מלכות\" — דער „עיקר\" כהונה ומלכות, וואס פועל'ט דעם שינוי הגברא ווערט פארבונדן מיטן עצם האדם און — אין דעם קען ניט זיין קיין „נטלו\" (מעצמם), נאר „נכתרו\" דורך דעם אויבערשטן.\nוע\"פ כל זה איז אויך מובן פארוואס דער רמב\"ם ברענגט די פסוקים דוקא — (בנוגע כתר כהונה) „והיתה לו ולזרעו אחריו ברית כהונת עולם\", און (בנוגע כתר מלכות) „זרעו לעולם יהי' וכסאו כשמש נגדי\" — ווייל אין די פסוקים זיינען מודגש די גדרי הנ\"ל:\nפון פסוק „והיתה לו ולזרעו אחריו ברית כהונת עולם\" איז מוכח:\nא) אז דאס קומט פון אויבערשטן, וואס דאס איז מודגש ביי כהונת פינחס וואס דער אויבערשטער האט אים געגעבן דעם ענין הכהונה68 דעמאלס69 באופן מיוחד70;",[["67","67","הל' מלכים שם ה\"ט."],["68","68","משא\"כ בהפסוק דפרשתנו „ברית מלח עולם גו' לך ולזרעך אתך\", שנעשה ע\"י מתנות כהונה (כספרי ופרש\"י שם יח, ח)."],["69","69","ראה לעיל הערה 25."],["70","70","וזכה לזה כהמשך הכתוב „תחת אשר קנא לאלקיו ויכפר גו'\", משא\"כ בפרשתנו שבא רק אחר זה שערער קרח על הכהונה. ופשיטא בנוגע לשאר"]]],[1300281124,"ב) אז דאס איז געווארן זיין מהות, וואס דערפאר איז עס „לו ולזרעו אחריו ברית כהונת עולם\" — ס'איז דער זעלבער „ברית . . עולם\" בא „לו\" און בא „זרעו\"71. ביז עס קומט די הלכה, ווי דער ראגאטשאווער איז מבאר אויף דעם פסוק, אז „כאן72 נתחדש דגם זרע פסול העבודה כשרה\"73, וואס דערפון איז מוכח אז דאס איז ניט קיין ירושה פון א מילוי פעולה, נאר פון א זאך שבמהותו, דער בן בעיקר74 מהותו איז דער זעלבער מהות פון דעם אב.\nוכעין זה איז עס מוכח פון פסוק „זרעו לעולם יהי' וכסאו כשמש נגדי\" — וואס קומט בהמשך צו די פסוקים75 „אם יעזבו בניו תורתי ובמשפטי לא ילכון גו' ופקדתי בשבט פשעם ובנגעים עונם וחסדי לא אפיר מעמו גו'\", וואס „הקב\"ה הבטיחו בכך\" אז „לא תכרת המלוכה מזרע דוד לעולם\"76, און נאך דעם פירט ער אויס אין די פסוקים „אחת נשבעתי בקדשי אם לדוד אכזב, זרעו לעולם יהי' וכסאו כשמש נגדי\" — די מלוכה איז באופן אז ס'איז ניט שייך אין איר קיין הפסק, דאס איז א כסא נצחי („כשמש נגדי\"), די נצחיות איז בא „זרעו לעולם\"77.\nיו\"ד. ע\"פ כל הנ\"ל וועט ווערן מוסבר וואס איידער דער רמב\"ם איז מסביר ומפרט דעם ענין פון כתר תורה, איז ער מקדים די פרטים בשייכות צו כתר כהונה וכתר מלכות און די ראיות פון די פסוקים — ווייל דוקא דורך דעם ווערט מוסבר דער גדר פון כתר תורה ביי אידן, אז „כתר תורה הרי מונח ועומד ומוכן לכל ישראל שנאמר תורה צוה לנו משה מורשה קהלת יעקב כל מי שירצה יבא ויטול\".\nובהקדם עכ\"פ בקיצור נמרץ:\nע\"ד בכתר מלך כפשוטו — זיינען דא78 כו\"כ חפצי המלך ביז „לבוש מלכות . . וסוס אשר רכב עליו\" און אויך „כתר מלכות\" בפני עצמם\nאון דערנאך ווי דער מלך (נוצט זיי און) ווערט נשתנה עי\"ז\nאזוי אויך בתורה (וכהונה<sup data-n=\"79\">79</sup> איז דא כתרה של תורה (פאר זיך) — ע\"ד",[["","","הפסוקים שלפנ\"ז (הנ\"ל הערה 28), שאינו שייך בכלל לענין ומאורע מיוחד."],["71","71","משא\"כ בפקודי (הנ\"ל הערה 28) „והיתה להיות להם משחתם לכהונת עולם לדורותם\", שאינו מפורש „עולם\" בנוגע לזרעם."],["72","72","צפע\"נ עה\"ת ר\"פ פינחס (מקידושין סו, ב). ע\"ש."],["73","73","„ור\"ל דאף דהעושה הוא שלא כדין דהוא כזר לכל דבריו מ\"מ העבודה כשרה\" (צפע\"נ שם). ואף שברמב\"ם הל' ביאת מקדש פ\"ו ה\"י הביא (ומקורו מקידושין שם) הכתוב (ברכה לג, יא) ברך ה' חילו גו' — אולי י\"ל להצפע\"נ דהלימוד הוא משם, אבל כאן (במעשה פינחס) נתחדש זה. וצ\"ע."],["74","74","דהפעולה שנתחלל על ידה — אין משנה אותו — ע\"ד ביהדות דאע\"פ שחטא (איזו חטא שיהי') ישראל הוא (סנה' מד, רע\"א)."],["75","75","תהלים פט, לא ואילך."],["76","76","רמב\"ם הל' מלכים שם ה\"ז."],["77","77","משא\"כ בהפסוק „כסאך יהי' נכון עד עולם\" שהביא בהל' מלכים שם, שנאמר „עד עולם\" רק בנוגע ל„כסאך\", ואינו מפורש הלשון „לעולם\" בנוגע לזרעו, כי שם (ועד\"ז בה\"ט שם), נוגע בנצחיות דכסא דוד, אבל כאן בהלכות ת\"ת, הרי\"ז הקדמה לכתר תורה דהוי באופן דמורשה קהלת יעקב (כדלקמן בפנים), ולכן הביא דוקא פסוק הנ\"ל."],["78","78","אסתר ו, ח. וראה בפרש\"י (שם, ט) דכתר (דוקא) לא הזכיר כו'."],["79","79","חפץ דכתר כהונה י\"ל שזוהי קטורת — ולכן דוקא עי\"ז הבירור דכהונה כבפרשתנו. ואכ\"מ."]]],[1300281125,"להפירוש הנ\"ל80 אז דאס מיינט הלכות שבתורה (ניט די שקו\"ט וכו') — און עס איז דא דער גברא (וואס ניט נאר ער איז שונה הלכה — וואס אויף דעם דארף אויך זיין „ויטול\" עכ\"פ דאמאלס נאר) הנכתר בכתר תורה.\nכשם ווי דאס איז בא כתר כהונה און כתר מלכות, אז דער גדר ה„כתר\" איז: א) מצד החפצא. ב) מצד הגברא — דאס ווערט (פארבונדן מיט) זיין מהות. ג) אין דעם „יחס\" צווישן דעם חפצא והגברא — עס קומט אן דער „כתר\" צום גברא, אין אן אופן פון „נכתרו\"81 (מצד דעם אויבערשטן) און נאכדעם קען זיין „ויטול\" און טאן מיט דעם — נטילה ועשי' בשלימותן — ועד\"ז איז עס בנוגע צו „כתר תורה\".\nועפ\"ז קומט צו אן עומק אין דעם וואס מען זאגט „כתר תורה הרי מונח ועומד ומוכן לכל ישראל . . כל מי שירצה יבא ויטול\": ס'איז נוסף אויף דעם פירוש אז דער אויבערשטער האט געגעבן תורה אין אן אופן אז יעדערער וואס וויל לערנען תורה האט די יכולת אויף דעם (כל מי שירצה יבוא ויטול) — נאר „נכתרו ישראל\"82, תורה איז זיי געגעבן געווארן פון דעם אויבערשטן אין אן אופן אז דאס איז געווארן פארבונדן מיט זייער עצם מהות, עס איז „מורשה קהלת יעקב\".\nאין אנדערע ווערטער: „מורשה קהלת יעקב\" מיינט אז תורה איז „מונח ועומד ומוכן לכל ישראל\" — ניט אז ס'איז גרייט „ערגעץ אנדערש\" און די בעלות דערויף קומט דורך זיין נטילה („יבוא ויטול\") — נאר דאס איז מונח און געווארן זיין עצם. דער „יבוא ויטול\" איז בלויז אז דער כתר תורה (וואס נכתרו בו) זאל שטיין אין אן אופן83 אז ער זאל קענען פועל בשלימות זיין מיט (דורך) עם.\nיא. עפ\"ז יש לבאר — בדרך אפשר — הטעם וואס דער אלטער רבי (בהל' ת\"ת שלו) איז משמיט די פסוקים און איז משנה מלשון הרמב\"ם בהמשך ההלכה (כנ\"ל), וואס יש לומר אז הא בהא תליא:\nמיט דעם וואס ער איז משנה און זאגט פריער „כל מי שירצה יבוא ויטול\", און דערנאך ברענגט ער די ראי' פון פסוק „שנאמר מורשה קהלת יעקב\" און איז מוסיף „שהיא ירושה לכל ישראל\", איז מער מודגש אז די ירושה איז ניט נאר וואס ס'איז „מונח ועומד ומוכן לכל ישראל\" און יעדערער קען דאס נעמען, נאר אויך אז דאס נעמען גופא איז א ירושה לכל ישראל (ניט א זאך וואס ווערט אויפגעטאן לגמרי דורך זיין מעשה, נאר), וואס קומט מלמעלה און",[["80","80","סעיף ה."],["81","81","ומ\"ש הרמב\"ם בנוגע לכתר כהונה וכתר מלכות „זכה בו אהרן . . זכה בו דוד\" — ולא „ניתן לאהרן כו' ניתן לדוד\" (וכברבינו יונה לאבות שם) — כי בזה מודגש יותר ש„נקנה\" להם, שנתעצם ונעשה חלק ממציאותם (וראה לשון הרמב\"ם הל' ת\"ת שם ה\"ז „אין אתה זוכה לכתרה של תורה\"; שם הי\"ג „מי שרצה לזכות בכתר התורה\")."],["82","82","לשון זה — „נכתרו ישראל\" — אינו לא בספרי ולא ביומא, וליתא בכל הנ\"ל הערה 7 (ובכל הנ\"ל ג' כתרים הם וכיו\"ב). אבל מפורש כן בספר הבהיר אות קנב „בשלשה כתרים נכתרו ישראל\" (ושם ממשיך: כתר כהונה וכתר מלכות וכתר תורה על גביהם). ובבמדב\"ר פי\"ד שם: ג' כתרים שנתן הקב\"ה לישראל על זאת."],["83","83","להעיר מג' המדריגות שבתורה, בחי' ירושה ובחי' מכר (יגיעה) ובחי' מתנה — נסמן ונתבאר בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131115\" data-slug=\"likkutei-sichot\" data-id=\"1300131115\">לקו\"ש חי\"ג ע' 115</a> ואילך. וראה לקמן ע' 176 ואילך."]]],[1300281126,"ווערט זיין מציאות, כנ\"ל — דער תוכן וואס דער רמב\"ם ברענגט ארויס דורך די פסוקים בכתר כהונה וכתר מלכות.\nיב. ועפ\"ז איז אויך מובן דער ענין ההלכה שבזה אין רמב\"ם:\nדער רמב\"ם איז דא אויסן צו ארויסברענגען ניט בלויז די מעלה פון כתר תורה, וואס צוליב דעם (ווי ער זאגט אין די הלכות שלאח\"ז) איז „ממזר ת\"ח קודם לכה\"ג עם הארץ\" און „אין לך מצוה בכל המצות כולן שהיא שקולה כנגד ת\"ת\"84 וכו' (און דערפאר מאנט זיך ע\"פ הלכה דער ענין הזריזות וכו' אין לימוד התורה),\nנאר אויך ובעיקר ווי דער כתר תורה האט א שייכות און פארבונד מיט יעדער אידן אלס זיין ירושה, וואס דערפון איז מובן, אז דאס צוקומען דערצו דורך די דרכים וואס דער רמב\"ם ברענגט ווייטער אין די הלכות85 [„. . לא יסיח דעתו לדברים אחרים ולא ישים על לבו שיקנה תורה עם העושר והכבוד כאחת כך היא דרכה של תורה כו'\" און „עשה תורתך קבע ומלאכתך ארעי וכו'\" ועוד], איז ניט אן ענין פון הידור מצוה וכיו\"ב, נאר דאס איז דער קיום פון „מצוה86 זו כראוי\".\n(משיחות ש\"פ קרח תשכ\"ח, ש\"פ אמור תש\"מ)",[["84","84","רמב\"ם שם ה\"ג."],["85","85","ה\"ו ואילך. — וראה לקו\"ש חכ\"ז הנ\"ל בשוה\"ג להערה 50."],["86","86","רמב\"ם שם ה\"ו. ולהעיר שבהל' ת\"ת לאדה\"ז פ\"ג רס\"ג כתב „ולכן מי שנשאו לבו לקיים מצוה זו כראוי\", ולא הביא המשך לשון הרמב\"ם „ולהיות מוכתר בכתר תורה\". ואולי אפ\"ל, דכיון שסדר ההלכות בשו\"ע אדה\"ז הוא באופן שונה מהל' ת\"ת להרמב\"ם, ואדה\"ז כתב הענין דכתר תורה רק ברפ\"ד, לכן לא הזכיר לשון זה לפני זה, כאן. ולהעיר משינוי לשון אדה\"ז שם פ\"ד ס\"ח — בנוגע ללימוד התורה בלילה — „לפיכך מי שרצה לזכות זכות בכתר תורה\", וברמב\"ם שם פ\"ג הי\"ג (בנוגע הנ\"ל) „לפיכך מי שרצה לזכות בכתר התורה\"*. ואכ\"מ. וראה לקו\"ש חל\"ד ע' 42 ואילך. *) ראה רמב\"ם הנ\"ל הערה 36 — כמה שינויי נוסחאות בהלשון „בכתר התורה\"."]]],[1300281127,"<h3>קרח ג</h3>\nא. אין סוף פון דער פרשה, וואו די תורה רעכנט אויס די מתנות כהונה וואס מ׳גיט צו די כהנים1, שטייט נאכדעם אין פסוק2 „ויאמר ה׳ אל אהרן בארצם לא תנחל וחלק לא יהי׳ לך בתוכם אני חלקך ונחלתך בתוך בני ישראל״.\nדערנאך — הויבט זיך אן א באזונדער פרשה3 „ולבני לוי הנה נתתי כל מעשר בישראל לנחלה גו׳״ און אין די פסוקים בנוגע ללויים שטייט ניט דער לשון „אני חלקך ונחלתך״, עס שטייט נאר „בתוך בני ישראל לא ינחלו נחלה״4.\nדער טעם, לכאורה, פארוואס רש״י שטעלט זיך ניט אפ אויף דעם חילוק צווישן די פסוקים הנ״ל איז, ווייל דאס איז מובן מעצמו, ע״פ פשוטו של מקרא5:\nפון תוכן הכתובים בפרשתנו איז קלאר, אז מתנות כהונה זיינען ענינים וואס בעצם באלאנגען זיי „לה׳״ און דער אויבערשטער גיט זיי צו די כהנים — ווי עס שטייט גלייך בתחילת הפרשה6 „ואני הנה נתתי לך את משמרת תרומותי לכל . . לך נתתים גו׳״. און ס׳איז מפורש אין די פסוקים, אז ניט נאר קדשי קדשים7 וואס די כהנים באקומען, נאר אויך קק״ל8, און אויך „כל חלב יצהר גו׳ ראשיתם אשר יתנו לה׳ לך נתתים, בכורי כל אשר בארצם אשר יביאו לה׳ לך יהי׳״9 (ועד״ז ביי די אנדערע זאכן וואס כהנים באקומען10, ווי דער פסוק פירט אויס (נאכאמאל) ביים סוף (— כללה<sup data-n=\"11\">11</sup> פון דער פרשה: „כל תרומת הקדשים אשר ירימו בני ישראל לה׳ נתתי לך גו׳״<sup data-n=\"12\">12</sup> — וכלשון הש״ס13 „מתנות כהונה (ד)כי קא זכו משלחן גבוה קא זכו״14.\nמשא״כ בנוגע די מעשרות וואס לויים באקומען זאגט די תורה15, אז דאס איז „חלף עבודתם16 אשר הם עובדים את עבודת אהל מועד״ און ניט באופן אז „משלחן גבוה קא זכו״17.",[["1","1","יח, ח ואילך."],["2","2","שם, כ."],["3","3","שם, כא (ואילך)."],["4","4","שם, כג. כד."],["5","5","וכמ״ש באוה״ח עה״פ — שם, כד."],["6","6","שם, ח."],["7","7","שם, ט־י."],["8","8","שם, יא (ובפרש״י שם). טו. ועוד."],["9","9","שם, יב־יג."],["10","10","ראה פרש״י שם, ט: אשר ישיבו לי — זה גזל הגר. ובפרש״י נשא (ה, ח) „קנאו השם ונתנו לכהן״."],["11","11","ראה פרש״י שם, יט."],["12","12","שם."],["13","13","ב״ק יג, רע״א. שם יב, ב. וש״נ."],["14","14","וראה רמב״ם הל׳ תרומות (פי״ב הי״ט) לגבי תרומות (וראה גם יד רמ״ה סנהדרין קיב, א). ובספרי פרשתנו (יח, כא) „כל מצות כהונה קנאו לשם [השם] ונתנו לכהונה כו׳״. ושם לפנ״ז (שם, כ) „על שולחני אתה אוכל ועל שולחני אתה שותה וכה״א כו׳״. וראה שו״ת הרשב״א (ח״א סי״ח) ועוד, דאין מברכין על מת״כ משום דמשולחן גבוה קא זכו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181232\" data-slug=\"likkutei-sichot\" data-id=\"1300181232\">לקו״ש חי״ח ע׳ 223</a> ואילך. וש״נ."],["15","15","פרשתנו שם, כא."],["16","16","שעובדים במקום בנ״י, כי „נתונים המה לו מאת בנ״י״ לתכלית זו (במדבר ג, ח־ט). וראה לקמן ס״ה."],["17","17","וראה גם פרש״י שהובא לקמן ס״ה. וכ״ה לדעת ר׳ יאשי׳ בספרי שם, דכ״ד מתנות כהונה קנאו השם ונתנו לכהונה וזו (בלוים) חלף עבודתם. ולר׳ יונתן גם בלוים קנאה השם ונתנה ללוים — ראה מפרשי הספרי — רבינו הלל, תולדות אדם, ספרי דבי רב. וראה הערה 61."]]],[1300281128,"און דאס וואס דער פסוק18 זאגט: כי את מעשר בני ישראל אשר ירימו לה׳ תרומה נתתי ללוים לנחלה, י״ל אז ס׳איז פארשטאנדיק פון פרש״י — „הכתוב קראו תרומה עד שיפריש ממנו תרומת מעשר״ — אז דאס וואס די תורה רופט עס אן „אשר ירימו לה׳ תרומה״ איז ניט מצד דעם מעשר גופא, נאר צוליב דעם חלק פון „תרומת מעשר״ וואס געפינט זיך (נאך) אינעם מעשר, וועלכן מ׳דארף געבן צום כהן.\nועפ״ז איז אויך פארשטאנדיק אז דער לשון הכתוב15 „ולבני לוי הנה נתתי כל מעשר בישראל לנחלה חלף עבודתם גו׳״, מיינט ניט צו זאגן אז די עצם נתינה קומט (פון דעם וואס אידן גיבן דעם אויבערשטן ובמילא איז דערנאך) „משולחן גבוה (קא זכו)״, נאר „נתתי . . לנחלה״ צו די לויים — די נתינה צו די לויים איז מלכתחילה באופן של „נחלה״, ווי עס שטייט אויך אין די שפעטערדיקע פסוקים19 „נתתי ללוים לנחלה״ „כי תקחו מאת בני ישראל את המעשר אשר נתתי לכם מאתם בנחלתכם״.\nאון דעריבער זעט מען, אז בנוגע לכהנים שטייט „אני חלקך ונחלתך״, זיי באקומען דעם אויבערשטנ׳ס חלק ונחלה — משא״כ ביי די לויים שטייט ניט „אני חלקך ונחלתך״ — דאס וואס זיי באקומען איז ניט אלס „חלק ה׳״20, נאר ווי א טייל וואס אידן שיידן אפ, „חלף עבודתם״ (כנ״ל). און ווי עס שטייט אויך שפעטער אין פסוק21 „ואכלתם אותו בכל מקום אתם וביתכם כי שכר הוא לכם חלף עבודתכם באהל מועד״.\nב. מען דארף אבער פארשטיין דעם המשך וסיום הכתוב בשייכות צו כהנים „אני חלקך ונחלתך בתוך בני ישראל״ [ולאידך, בנוגע די לויים שטייט אין פסוק (צוויי מאל) א פארקערטע הדגשה: „בתוך בני ישראל לא ינחלו נחלה״].\nדער אור החיים22 איז מסביר אז מיט „אני חלקך ונחלתך גו׳״ איז כוונת הכתוב צו זאגן — דאס וואס איז „מיוחד לי״; „אני נחלתך״ איז עס „בתוך בני ישראל״ — „שאין לך דבר בעם ישראל שאין להקב״ה חלק עמהם ונוטלו הכהן בתבואות הארץ בפירות האילן בלחם בבשר ביין בשמן ושאר הכ״ד מתנות״.\nדאס איז אבער דורש ביאור נוסף: וואס איז נוגע דא די הדגשה אז די מתנות כהונה זיינען „בתוך בני ישראל״? אדרבה, די מתנות כהונה בפרשתנו איז דאך עיקר תוכנן, אז זיי זיינען זאכן וואס דער אויבערשטער גיט23 צו די כהנים: און דאס איז דאך דער טעם אויף דער סמיכות פון פרשת מתנות כהונה צו מחלוקת קרח, להשמיענו אז דער אויבערשטער האט געגעבן „כ״ד מתנות כהונה בברית מלח עולם״24 — וואס איז נוגע דא די הוספה אז דאס איז „בתוך בנ״י״?\nג. אויך דארף מען פארשטיין: אין פ׳ עקב, וואו עס רעדט זיך וועגן גאנץ שבט לוי — „בעת ההיא הבדיל ה׳ את שבט הלוי גו׳״25 — שטייט אין פסוק26 „על כן לא הי׳ ללוי חלק ונחלה עם אחיו ה׳ הוא נחלתו״, אז אויך ביי לויים איז",[["18","18","שם, כד."],["19","19","שם. שם, כו."],["20","20","ל׳ האוה״ח שבהערה 5."],["21","21","שם, לא ובאוה״ח שם."],["22","22","בפסוק כ."],["23","23","וא״כ „בתוך בנ״י״ ה״ז מיעוטא, וכאילו כתוב „אף שהם בתוך בנ״י״."],["24","24","ל׳ רש״י בתחלת הענין — שם, ח."],["25","25","י, ח."],["26","26","שם, ט."]]],[1300281129,"„ה׳ הוא נחלתו״, און ווי רש״י טייטשט „נוטל פרס מזומן מבית המלך״. און אזוי שטייט אויך אין פ׳ שופטים27 „ה׳ הוא נחלתו״ בנוגע „כהנים הלוים כל שבט לוי״28.\nלויט פרש״י יש לומר, אז די פסוקים (סיי אין פ׳ עקב און סיי אין פ׳ שופטים) ריידן וועגן כהנים: אויפן פסוק „על כן לא הי׳ ללוי חלק ונחלה עם אחיו״ איז רש״י מפרש „לפי שהובדלו לעבודת מזבח ואינן פנויין לחרוש ולזרוע״, וואס „הובדלו לעבודת מזבח״ איז אן ענין וואס איז שייך צו כהנים. ועד״ז בפ׳ שופטים, איז התחלת הכתוב „לא יהי׳ לכהנים הלוים״ מיינט לויט פרש״י „הכהנים שיצאו משבט לוי״\n(ווי ער טייטשט אפ מיט עטלעכע פסוקים פריער29, וואס פון דעם איז פארשטאנדיק, אז דער לשון „הכהנים הלוים״ וואס שטייט אין די אלע אנדערע ערטער, מיינט אויך „הכהנים שיצאו משבט לוי״, און רש״י דארף עס ניט מפרש זיין נאכאמאל),\nאון דער המשך הלשון „כל שבט לוי״ איז רש״י מפרש: „בין תמימין בין בעלי מומין״, ד.ה. דער פסוק איז דא ניט כולל גאנץ שבט לוי, נאר „בין תמימין בין בעלי מומין״ צווישן די כהנים.\nאון ווי דער תרגום יונתן טייטשט בפ׳ שופטים30, אז די פסוקים רעדן וועגן כהנים.\nאבער פון דעם וואס די תורה זאגט דאך אין ביידע ערטער דעם לשון „שבט לוי״ — „בעת ההיא הבדיל ה׳ את שבט הלוי״, „כל שבט לוי״ [און אין ביידע פרשיות שטייען ענינים בשייכות צו לוים: בפ׳ עקב — „לשאת את ארון ברית ה׳״, טייטשט רש״י „הלוים״, ובפ׳ שופטים „אשי ה׳ ונחלתו יאכלון״ — אלו קדשי הגבול תרומות ומעשרות] — איז מובן, אז כאטש בעיקרו ווערן דא געמיינט די כהנים, זיינען אבער אין דעם כלול אויך לויים.\nוצריך ביאור: וואס איז דער טעם החילוק והשינוי וואס איז מודגש אין די פסוקים בפרשתנו, אז ביי כהנים שטייט „אני חלקך ונחלתך בתוך בני ישראל״ משא״כ בנוגע הלויים?\nד. נאך אן ענין הצריך ביאור: דער רמב״ם — אין דרך (און לויט) ההלכה — איז מפרש אז די פסוקים בפרשתנו און אין פ׳ שופטים באציען זיך צו גאנץ שבט לוי. וז״ל31: כל שבט לוי מוזהרין שלא ינחלו בארץ כנען כו׳ שנאמר לא יהי׳ לכהנים הלוים כל שבט לוי . . בארצם לא תנחל כו׳, ובהמשך לזה זאגט ער32 „ולמה לא זכה לוי בנחלת א״י כו׳ מפני שהובדל כו׳ והוא ב״ה זוכה להם שנאמר אני חלקך ונחלתך״.\nס׳איז טאקע פשוט, אז מ׳קען ניט פרעגן אויפן רמב״ם פון פשטות הכתובים, אבער דאך איז יש לעיין, וואס איז דער חילוק צווישן דעת רש״י (לויט פשטות הכתובים) און דעת הרמב״ם (וע״פ הלכה).\nה. ויש לומר ההסברה בזה, בהקדם — אז דער חילוק צווישן כהנים און לויים, קען מען לערנען אויף צוויי אופנים:\nא) ביידע סיי לויים און סיי כהנים, טיילן זיך אויס (זיינען העכער) פון אלע",[["27","27","יח, ב."],["28","28","שם, א."],["29","29","יז, ט."],["30","30","יח, א־ב."],["31","31","הל׳ שמיטה ויובל פי״ג ה״י."],["32","32","שם הי״ב."]]],[1300281130,"אידן אין איין דעמזעלבן אופן בכללות — זיי זיינען מובדל ומופרש פון כלל ישראל, נאר אין דעם גופא זיינען כהנים מער מובדל לה׳ ווי די לויים.\nב) כהנים און לויים זיינען צוויי באזונדערע גדרים אין דער הבדלה לה׳.\nאון די הסברה בזה:\nדי אויסגעטיילטקייט פון די כהנים איז געזאגט געווארן בר״פ תצוה33 „ואתה הקרב אליך את אהרן אחיך גו׳״ צוזאמען ובהמשך מיט מלאכת המשכן; משא״כ דאס וואס די לויים זיינען מובדל לעבודת המשכן שטייט אין דער תורה צום ערשטן מאל אין פ׳ במדבר34, נאך הקמת המשכן, און אויך — דער ציווי איז געווען35: הקרב את מטה לוי והעמדת אותו לפני אהרן הכהן ושרתו אותו36.\nקומט אויס, אז לויט פשטות הכתובים איז פאראן א חילוק עיקרי אין דעם גדר השירות צווישן כהנים און לויים:\nכהנים, וואס לשון כהונה איז שירות37, זיינען אויסגעקליבן געווארן אלס משרתים פון אויבערשטן אין משכן, „לכהנו לי״38; „לקדשו לכהנו לי״39.\nמשא״כ לויים זיינען ניט אין דעם גדר פון משרתי ה׳ באופן ישר, נאר „ושרתו אותו״, „מסייעין״40 להכהנים — „זו היא השירות״40. נאכמער: אלע זייערע עבודות אין משכן, אויך די וואס בגלוי האט מען ניט געזען ווי זיי זיינען א סיוע להכהנים, ווערן גערופן „משמרת בני ישראל״41, ופרש״י „שכולן היו זקוקין לצרכי המקדש אלא שהלוים באים תחתיהם בשליחותם לפיכך לוקחים מהם המעשרות בשכרן״ — זיי זיינען געווען ע״ד ווי געדונגענע שלוחים פון בני ישראל42.\nבסגנון אחר: לויט פרש״י בפשוטו של מקרא קומט אויס, אז די כהנים האט דער אויבערשטער מבדיל געווען באופן אז ער האט זיי באשטימט פאר זיינע משרתים; לויים האט דער אויבערשטער אויסגעטיילט אויף דעם אז אידן זאלן זיי דינגען — „שיהיו ישראל שוכרין אותן לשירות שלי״43.\nדער רמב״ם אבער זאגט אין הל׳ כלי המקדש44 „זרע לוי כולו מובדל לעבודת המקדש שנאמר25 בעת ההיא הבדיל ה׳ את שבט הלוי״, דערנאך, אין א באזונדער פרק, זאגט דער רמב״ם45 „הכהנים הובדלו מכלל הלוים לעבודת הקרבנות שנאמר46 ויבדל אהרן להקדישו קדש קדשים״. ד.ה. אז שיטת הרמב״ם איז ווי דער ערשטער אופן הנ״ל: די זעלבע",[["33","33","כח, א."],["34","34","א, נ ואילך. ג, ו ואילך."],["35","35","ג, ו."],["36","36","משא״כ הפסוקים שלפנ״ז (שם א, נ ואילך) אינם הפרשה דעבודת הלוים כ״א פרט במנין הלוים, כהתחלת הפרשה (א, מט) „אך את מטה לוי לא תפקד ואת ראשם גו׳״. ולהעיר דגם הציוויים שנאמרו שם מדובר (בעיקר) ע״ד נשיאת המשכן, הורדת והקמת המשכן, חניית הלוים סביב לאהל מועד, שכ״ז הוי רק במשכן ולא מצות לדורות."],["37","37","רש״י תצוה כח, ג. וראה פרש״י ויגש מז, כב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181028\" data-slug=\"likkutei-sichot\" data-id=\"1300181028\">לקו״ש חי״ח ע׳ 19</a> ואילך."],["38","38","תצוה שם, א־ד."],["39","39","תצוה שם, ג."],["40","40","רש״י במדבר ג, ו."],["41","41","שם, ח."],["42","42","וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131012\" data-slug=\"likkutei-sichot\" data-id=\"1300131012\">לקו״ש חי״ג ע׳ 12</a> ואילך שזהו ב׳ ענינים בעבודת הלוים, עבודה החיובית ועבודה בשמירה — שלילית. ע״ש בארוכה."],["43","43","רש״י במדבר שם, יב."],["44","44","רפ״ג."],["45","45","רפ״ד."],["46","46","דה״א כג, יג."]]],[1300281131,"הבדלה בא ביידן, דער חילוק איז נאר צי לעבודת המקדש, אדער לעבודת הקרבנות.\nו. ע״פ זה, איז דער חילוק צווישן דעת רש״י (בפשש״מ) מיט דעת הרמב״ם בספרו היד (להלכה) — בשתים:\nא) לדעת רש״י איז אין תורה פאראן א באזונדער הבדלה והקרבה לה׳ פון כהנים מתוך בני ישראל — ניט פארבונדן מיט זייער הבדלה אלס שבט לוי; משא״כ לדעת הרמב״ם (בהלכה) איז פריער דא די הבדלה כללית פון גאנצן שבט לוי (כולל די כהנים) און (דערנאך — אין דעם גופא) „הכהנים הובדלו מכלל הלוים״47.\nב) לדעת רש״י זיינען עס צוויי באזונדערע גדרים (סוגים) אין שירות: ביי א כהן איז דער ענין השירות א דבר עצמי (אין עם), דאס איז שמו — „כהן״ לשון שירות און — שירות לה׳; ביי א לוי אבער איז זיין שירות ניט (דירעקט) לה׳, נאר שירות וטפל (וילוו אליך) צו כהנים, און — דער שירות שבו איז ניט אן ענין עצמי, נאר ער איז א מענש וואס מ׳האט אים געדונגען.\nמשא״כ לדעת הרמב״ם זיינען ביידע אין דעם זעלבן כללות׳דיקן גדר פון שירות48, און דער חילוק ביניהם איז נאר וואס „זרע לוי (איז) כולו מובדל לעבודת המקדש״ בכלל, און „הכהנים הובדלו מכלל הלוים לעבודת הקרבנות״49.\nז. דערפון איז פארשטאנדיק בפרשתנו, אז נאך דער מחלוקת קרח, ווען ס׳איז געווען אן ערעור על הכהונה50 און ס׳האט געדארפט ווידער איינגעשטעלט ווערן דער סדר הכהונה והלוי׳, איז אין דעם אויך פאראן א חילוק בין שיטת רש״י והרמב״ם:\nלדעת רש״י (בפשוטו של מקרא), איז דאס איינגעשטעלט געווארן אין זעלבן אופן ווי פריער: צו די כהנים איז געווען די אזהרה „אתה ובניך גו׳ תשאו את עון כהונתכם״ („שאינה מסורה ללוים, ותזהירו הלוים השוגגים שלא יגעו אליכם בעבודתכם״), און בנוגע די לויים — „וגם51 את אחיך מטה לוי . . הקרב אתך וילוו עליך וישרתוך״52 (ועד״ז ווערן אין די פסוקים בהמשך הפרשה אויסגערעכנט בפרטיות די חילוקי עבודות פון די כהנים און די לויים, אז „אל כלי הקודש ואל המזבח לא יקרבו ולא ימותו גם הם גם אתם״ נאר „ונלוו (הלויים) עליך״<sup data-n=\"53\">53</sup>.\nמשא״כ לדעת הרמב״ם לערנט מען אפ פון די פסוקים אז „כשם54 שהלוים",[["47","47","להעיר מהשקו״ט האם יש בכהן מקדושת לוי. ולכאורה י״ל שזה שייך לפלוגתת רש״י והרמב״ם שבפנים. וראה חקרי לב או״ח סי׳ לה. ולקמן בפנים. ואכ״מ. ולהעיר מצפע״נ מהד״ת בסופה (ע׳ 182) ובכ״מ, שמבאר דפליגי גמ׳ דידן וירושלמי אם כהן שנעשה חלל אם יש עליו שם לוי. וראה צפע״נ עה״ת פרשתנו יח, כא. וש״נ."],["48","48","ולהעיר משו״ע אדה״ז או״ח סקכ״ח ס״י (וש״נ) דמה שנוהגים שהלוי יצוק מים על ידי הכהנים כדי שהכהנים יוסיפו קדושה על קדושתם. וראה שם סי״א בלוי ת״ח וכהן ע״ה „ואין בזה איסור משום זלזול תורתו כיון שאינו משרת את הכהנים דרך חק ומשפט כהונה אלא מתכוין להוסיף קדושה כו׳״."],["49","49","בכללות החילוק בין כהן ולוי — ראה בסגנון אחר <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181201\" data-slug=\"likkutei-sichot\" data-id=\"1300181201\">לקו״ש חי״ח ע׳ 192</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191329\" data-slug=\"likkutei-sichot\" data-id=\"1300191329\">חי״ט ע׳ 316</a> ואילך. ועוד."],["50","50","לשון רש״י פרשתנו יח, ח."],["51","51","זה על הכהן לעשות."],["52","52","יח, א־ב ובפרש״י."],["53","53","ג־ד. ע״ש בפרש״י."],["54","54","שם פ״ג ה״י."]]],[1300281132,"מוזהרין שלא לעבוד עבודת הכהנים55 כך הכהנים מוזהרין שלא לעבוד עבודת הלוים שנאמר56 גם הם גם אתם״. ווארום כאטש די כהנים זיינען לכתחילה געווארן אויסגעטיילט צוזאמען מיטן גאנצן שבט לוי, וויבאלד אבער אז מ׳האט זיי מבדיל געווען בהבדלה מיוחדת אויך פון כלל הלויים, טארן זיי ניט טאן עבודת הלוים.\n[דאס איז אבער נאר לדעת הרמב״ם אז ביידע זיינען א גדר שירות; משא״כ לדעת רש״י (בפשש״מ) י״ל אז מען געפינט ניט אז כהנים זאלן זיין מוזהר לעבוד עבודת הלוים57, ווייל דאס איז ניט אין דעם גדר, דער שם שירות ביי לויים איז לגמרי אן אנדער גדר (וע״ד לשון הגמרא58 „דלאו מינה59 לא מחריב בה״<sup data-n=\"60\">60</sup>].\nח. ועפ״ז מובן אז לשיטתייהו אזלי אין דעם המשך הפרשה פון מתנות כהונה, וואו די תורה פירט אויס בנוגע כהונה אז דאס איז „ברית מלח עולם״:\nלדעת רש״י (בפשש״מ) איז דער ענין „אני חלקך ונחלתך״ געזאגט געווארן נאר צו כהנים, ווארום היות אז ענינם איז שירות לה׳, דערפאר איז בהתאם לזה אויך ביי די מתנות, זיי באקומען דאס אינעם אופן פון „אני חלקך גו׳״ — „משלחן גבוה קא זכו״.\nמשא״כ די לויים, וועלכע זיינען אין גדר פון (ניט „משרתי ה׳״ ממש, נאר) „וילוו עליך וישרתוך״ און שלוחים מאת בנ״י, דערפאר זיינען אויך זייערע מתנות אין סוג פון (ניט „אני חלקך ונחלתך״ נאר) מעשר „חלף עבודתם״61.\nלדעת הרמב״ם אבער, אז כהנים און לויים זיינען ביידע צוזאמען מובדל לעבודה — מלכתחילה איז „זרע לוי כולו מובדל״ (און דערנאך ערשט „הכהנים הובדלו מכלל הלוים״) — אויך די לויים זיינען אין גדר פון שירות לה׳, ובמילא זיינען אויך זיי נכלל אין „אני חלקך ונחלתך״.\nט. עפ״ז איז אויך מובן בנוגע צו די פרשיות אין משנה תורה (בפ׳ עקב און שופטים), אז דער חילוק צווישן רש״י און דעם רמב״ם, איז בהתאם לפירושם פריער:",[["55","55","וי״ל שיש חילוק עקרי בין אזהרה זו לאזהרת שוער שלא ישיר כו׳ בלוים גופא (ערכין יא, ב. ספרי פרשתנו יח, יג. רמב״ם שם פ״ג ה״י) — ומהם: א) עבודות דכהנים או דלוים — אחד בעבודת הב׳ זר (ואולי י״ל דעד״ז הוא הישראל שבמעמד)* — משא״כ שוער ומשורר דרק אסור (לא מטעם זרות). ב) החפצא אחרת — מקדש או קרבן. ועוד. ולהעיר מצפע״נ (המלוקט) על ס׳ עבודה שם. ואכ״מ."],["56","56","פרשתנו שם, ג."],["57","57","וראה חקרי לב שם בתחלתו."],["58","58","זבחים ג, א ובפרש״י שם. שם, ב."],["59","59","משא״כ בשוער ומשורר (הערה 55) את״ל דגם עפפש״מ — אסור."],["60","60","להעיר (ע״ד ההלכה) ממנ״ח (מצוה שפט) דאזהרה זו שלא יתעסקו הלוים בעבודת כהנים וכן להיפך „אינו רק בשני המשפחות כהנים ולוים כו׳ אבל ישראלים אינם בכלל באזהרה זו וישראל ששורר או שוער לא מצינו איסור כלל״. וצע״ג הרי ישראל ששורר או שוער ה״ה זר ובמיתה וכו׳. וכמפורש בערכין שם (ובפרש״י שם). *) ולהעיר מהשקו״ט במנ״ח מצוה שפט (הובא לקמן הערה 60)."],["61","61","להעיר דגם להדיעות ע״ד ההלכה דגם בכהנים הוי „חלף עבודתם״ (ראה אור זרוע ח״א סקי״ג. ועוד) — שאני כהנים מלויים, דבלויים ה״ז מה שישראל שוכרים אותם ונותנים להם מעשר חלף עבודתם, כלשון רש״י בפ׳ במדבר (כנ״ל בפנים ס״ה); משא״כ בכהנים ה״ז מה שהקב״ה נותן להם חלף עבודתם לה׳. וראה לשון רש״י ערכין לד, א ד״ה הכא ברשותו. וראה יד אפרים יו״ד סי׳ סא ס״ט. שו״ת בית יצחק סי״ג אות יד. ועוד. ואכ״מ."]]],[1300281133,"לדעת הרמב״ם, זיינען אויך די לויים נכלל אין דער פרשה פון „בעת ההיא הבדיל ה׳ את שבט הלוי״ שבפ׳ עקב, און „לא יהי׳ לכהנים הלוים כל שבט לוי״ שבפ׳ שופטים62, ווארום די הבדלה לה׳ איז כולל דעם גאנצן שבט לוי.\nאבער לויט פרש״י (בפשוטו של מקרא), וויבאלד אז במקומו (אין פ׳ במדבר און בפרשתנו) איז קלאר (בפשש״מ) אז ס׳איז א חילוק צווישן דעם גדר שירות פון כהנים און לויים, איז ניט מסתבר אז (אין די פסוקים הנ״ל: „בעת ההיא גו׳״ און „לא יהי׳ לכהנים גו׳״) אין משנה תורה (וואס כשמו כן הוא — ענינים וואס משה רבינו האט איבערגע׳חזר׳ט צו אידן) — זאל תורה זאגן א נייעם גדר אין כהנים ולויים, לערנט רש״י אז דאס רעדט זיך באופן כללי, און „ה׳ הוא נחלתו״ רעדט זיך בעיקר וועגן כהנים.\n[ועוד י״ל, אז לויט רש״י זיינען די צוויי פסוקים בפ׳ עקב — באזונדערע ענינים:\n„בעת ההיא הבדיל ה׳ את שבט הלוי לשאת את ארון ברית ה׳ לעמוד לפני ה׳ לשרתו ולברך בשמו עד היום הזה״ — דאס וואס די תורה איז מצרף צוזאמען די לויים וועלכע זיינען נושאי ארון ברית ה׳ און די כהנים — „לעמוד לפני ה׳ לשרתו ולברך בשמו״ איז ווייל דא רעדט זיך ניט וועגן עצם שירות פון די כהנים, ומהאי טעמא יומתק63 פרש״י אין דעם ערשטן פסוק אז „לעמוד לפני ה׳ לשרתו ולברך בשמו״ מיינט „נשיאת כפים״64, ניט זייער שירות ועבודה במקדש וועלכע איז עיקר ענינם.\nאון דעם צווייטן פסוק „על כן לא הי׳ ללוי חלק ונחלה עם אחיו ה׳ הוא נחלתו כאשר דבר ה׳״ איז רש״י מפרש, אז דאס איז אן ענין בפ״ע: „לפי שהובדלו לעבודת מזבח״, וואס דאס איז דער עיקר שירות פון כהונה — און דערפאר ווערט דא געזאגט: ה׳ הוא נחלתו65 — „נוטל פרס מזומן מבית המלך״].\nיו״ד. ע״פ כל זה יש לבאר לפרש״י דעם חילוק צווישן כהנים ולויים שבפרשתנו, וואס ביי כהנים שטייט „אני חלקך ונחלתך בתוך בני ישראל״, משא״כ ביי לויים שטייט (הפכו, לכאורה) „בתוך בני ישראל לא ינחלו נחלה״ — אין דעם באשטייט דער חילוק צווישן די נחלה פון די כהנים און די נחלה פון די לויים:\nדי נחלה פון די כהנים איז „בתוך בני ישראל״ — צוזאמען (אין דעם זעלבן אופן) ווי אידן האבן א נחלה: כשם ווי דער אויבערשטער האט געגעבן אידן, צו אידן א נחלה — ארץ ישראל, עד״ז האט דער אויבערשטער געגעבן א חלק",[["62","62","ראה רמב״ם שם ה״ב (מערכין יא, א) „שנאמר (שופטים יח, ז) ושרת בשם ה׳ אלקיו ככל אחיו הלוים, אי זהו שירות שהוא בשם ה׳ הוי אומר זו שירה״. אבל בפרש״י שופטים שם (ו־ז. מספרי עה״פ) דקאי על כהן ולא לוי ד„יצאו לויים שאין ראוין לשירות״."],["63","63","אע״פ שבלאה״כ מוכרח מדכתיב „ולברך בשמו״. אבל ראה הערה הבאה."],["64","64","שמזה שרש״י העתיק בהד״ה לא רק התיבות „ולברך בשמו״ אלא גם „לעמוד לפני ה׳ לשרתו״ משמע, דמפרש גם תיבות אלו על נשיאת כפים (או, דהעיקר כאן הוא נשיאת כפים). ועצ״ע."],["65","65","אלא די״ל, שמכיון שעל הלויים נאמר „ושרתו אותו״ שהם מסייעים להכהנים — בעבודת המזבח, לכן בכללות הרי גם הלויים נכללים בפסוק הב׳ „ע״כ לא הי׳ ללוי גו׳ ה׳ הוא נחלתו״. אלא שהכתוב מסיים „כאשר דבר ה״א לו״, והכוונה לכאורה להפסוק שבפרשתנו בנוגע לכהנים. וצ״ע למה לא פירש זה רש״י על פסוק זה (בפ׳ עקב), כ״א לאחרי זה בפ׳ שופטים יח, ב (בסופו)."]]],[1300281134,"ונחלה צו די כהנים „כל תרומות הקדשים אשר ירימו בני ישראל לה׳״66;\nמשא״כ די לויים האבן ניט באקומען א נחלה (באופן ישר) פון דעם אויבערשטן — ווי די אידן האבן באקומען א נחלה, ארץ ישראל — נאר דער אויבערשטער האט געהייסן אז אידן זאלן געבן בני לוי שכר, „חלף עבודתם״. און דאס איז די תורה מדגיש, אז „ובתוך בני ישראל לא ינחלו נחלה״ — זייער נחלה איז ניט צוזאמען (און אין דעם אופן) ווי אידן האבן א נחלה67.\nיא. מ„יינה של תורה״ אין פירוש רש״י:\nדער רמב״ם זאגט68: לא שבט לוי בלבד אלא כל איש ואיש כו׳ אשר נדבה רוחו כו׳ לעמוד לפני ה׳ כו׳ הרי זה נתקדש קדש קדשים ויהי׳ ה׳ חלקו ונחלתו.\nדערפון איז מובן אויך לדעת רש״י אין דעם גדר פון כהן ולוי, אז ביי כאו״א בעבודה רוחנית איז פאראן סיי די דרגא פון כהן און סיי די דרגא פון לוי. און וויבאלד אז לעתיד לבא וועלן די לויים ווערן כהנים, לויים וועלן זיין העכער פון כהנים69, איז פארשטאנדיק אז אויך בזמן הזה איז פאראן א מעלה אין א לוי לגבי כהן.\nויש לומר ע״פ הנ״ל: לוי איז מלשון ילווה, התקשרות והתחברות70 — דביקות בה׳71. לאידך גיסא זאגט מען „וילוו עליך וישרתוך״, אז זיי זיינען משרתים צו די כהנים ומסייעים שלהם, ועד״ז — שלוחים פון די בני ישראל לשרת.\nולכאורה ווי שטימען די צוויי ענינים — וויבאלד זייער ענין איז התקשרות והתחברות לה׳ וואלטן זיי דאך געדארפט זיין ווי כהנים, משרתי ה׳, לקדשו לי, נתקדש קדש קדשים?\nנאר דער ביאור אין דעם — אז היא הנותנת: דער אמיתית הענין פון עבודת השם איז ווען מ׳איז קיין מציאות ניט בפ״ע כלל וכלל.\nבני ישראל וועלכע האבן א נחלה וואס איז זיי געגעבן געווארן פון אויבערשטן, ועד״ז די כהנים אויף וועמען מ׳זאגט „אני חלקך ונחלתך בתוך בני ישראל״, זיינען זיי אלע משרתי א־ל, וואס דאס אלעס גופא מיינט אז זיי זיינען אין א געוויסן גדר פון מציאות;\nמשא״כ לויים72 פילן זיך כלל וכלל ניט ווי א מציאות (בפני עצמם), אפילו ניט אלס א מציאות דקדושה, זיי זיינען אפילו ניט קיין מציאות דמשרתים פון אויבערשטן (נאר מסייעים צו די כהנים (אז דער צווייטער זאל קענען טאן זיין שירות), און געדונגענע שלוחים פון די אידן) — און דוקא אין דער עבודה,",[["66","66","פרשתנו יח, יט."],["67","67","וגם המ״ח ערים שניתנו ללויים — ע״פ פשוטו של מקרא אינן נחלה להם בתוך בנ״י, כ״א כלשון הכתוב (מסעי לה, ב־ג) ונתנו ללוים מנחלת אחוזתם ערים לשבת גו׳ והיו הערים . . לשבת (ראה אוה״ח שם). וראה רמב״ן פרשתנו בסופה. לקמן ע׳ 217. ע״ד ההלכה — ראה ירושלמי מע״ש פ״ה ה״ט. ובארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251093\" data-slug=\"likkutei-sichot\" data-id=\"1300251093\">לקו״ש חכ״ה ע׳ 93</a> ואילך. וש״נ."],["68","68","בסוף הל׳ שמיטה ויובל. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081356\" data-slug=\"likkutei-sichot\" data-id=\"1300081356\">לקו״ש ח״ח ע׳ 345</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181203\" data-slug=\"likkutei-sichot\" data-id=\"1300181203\">חי״ח ע׳ 194</a>. וש״נ."],["69","69","<a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא פ״נ</a>, מל״ת להאריז״ל (יחזקאל). וראה בארוכה לקו״ת פרשתנו נד, סע״ב ואילך."],["70","70","כמ״ש בפ׳ ויצא (כט, לד)."],["71","71","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370206\" data-slug=\"torah-or\" data-id=\"3901370206\">תו״א ויחי מה, סע״ב</a> ואילך. ובכ״מ."],["72","72","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו״א בשלח סב, ג</a>."]]],[1300281135,"ביטול לגמרי73, ווערט דער אמת׳ער „ילוה אישי אלי״74, התקשרות והתחברות צווישן אידן מיטן אויבערשטן.\n(משיחות ש״פ קרח תשמ״ה, ש״פ נצו״י וכ״ט אלול תשד״מ)",[["73","73","ראה עד״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221012\" data-slug=\"likkutei-sichot\" data-id=\"1300221012\">לקו״ש חכ״ב (ע׳ 12</a> ואילך) — שדוקא בנדבת העצים, שאינם חלק מהקרבן עצמו רק הכשר קרבן (ובמילא אין להאדם ה„שביעת רצון״ שהוא פעל ה„ריח ניחוח לה׳״, וכל פעולתו היא רק שמסייע לאחר להקריב קרבנו) בא בגילוי יותר הביטול ומסנ״פ לה׳."],["74","74","ויצא שם."]]],[1300281136,"<h3>ג' תמוז</h3>\nא. ג' תמוז — דער טאג ווען כ\"ק מו\"ח אדמו\"ר איז באפרייט געווארן פון בית האסורים — פאלט אויס (בכמה שנים) בסמיכות צו שבת פרשת חוקת (אמאל אין דער וואך פון פ' חוקת, ולפעמים¹ אין די טעג וועלכע ווערן „מתברך\" פון שבת פ' חוקת).\nאון לויטן באוואוסטן ווארט פון של\"ה², אז אלע מועדי השנה — כולל אויך מועדים דרבנן — זיינען נרמז אין די פרשיות התורה וועלכע מען לייענט אין די שבתות ווען זיי זיינען חל, איז פארשטאנדיק, אז עס איז דא א רמז אין פרשת חוקת אויף דער גאולה פון ג' תמוז.\nב. אין דער גאולה פון רבי'ן זיינען געווען צוויי (כללות'דיקע) שלבים: ג' תמוז איז ער באפרייט געווארן פון בית האסורים, אבער מ'האט אים דאן פארשיקט אין גלות אויף דריי יאר; ערשט דערנאך, בי\"ב־י\"ג תמוז איז ער אינגאנצן באפרייט געווארן, אויך פון דער פארשיקונג, און ער האט זיך געקענט אומקערן לביתו.\nקומט אויס, אז בג' תמוז איז געווען די התחלת הגאולה, און י\"ב־י\"ג תמוז איז געווען די שלימות הגאולה.\nאון מהאי טעמא איז פאראן אן עילוי אין ג' תמוז לגבי י\"ב־י\"ג תמוז:\nאע\"פ אז דער חג הגאולה איז נקבע געווארן אויף י\"ב־י\"ג תמוז דוקא, איז דאס ווייל דער ענין פון א „חג\" (ושמחה גלוי') איז מען קובע ווען די גאולה איז בשלימות,\n[ע\"ד ווי ברכת הגומל וואס דער רבי האט געמאכט ערשט נאך דער גאולה בי\"ב תמוז³, ווייל מען קען ניט מאכן די ברכה „עד שיצא מהסכנה לגמרי . . עד שיחזור לבוריו לגמרי\"⁴],\nאבער אין עצם ענין הגאולה איז דא אן עילוי אין התחלת הגאולה לגבי שלימות הגאולה. ווייל (נוסף לזה וואס אין דער התחלה איז דא די מעלה וואס מען ברעכט דורך די שוועריקייט פון „כל התחלות קשות\"⁵, היות אז) ביי דער התחלת הגאולה טוט זיך אויף דער שינוי (ועד — להפכו —) המצב פון גלות (גולה) צו גאולה,\n[ובפרט בנדו\"ד, וואס⁶ דער שינוי המצב בפשטות וואס האט זיך אויפגעטאן דורך דער גאולה בג' תמוז — די באפרייאונג פון בית האסורים (ובפרט אין די אומשטענדן פון דער מדינה ההיא בימים ההם⁷) און איבערגיין (אפילו) אין א מצב פון גלות אין אן עיר רחוקה — איז געווען (בכמה פרטים) גרעסער ווי דער שינוי וחילוק פון זיין בגולה און ארויסגיין חפשי לביתו (ובפרט אז אויך זייענדיק נאכדעם בביתו",[["1","1","כן הי' בשנת תרפ\"ז (שנת המאסר והגאולה), וכן בקביעות שנה זו (תשד\"מ)."],["2","2","חלק תושב\"כ ר\"פ וישב."],["3","3","סה\"מ קונטרסים ח\"א קעה, א. ס' התולדות אדמו\"ר מהוריי\"צ ח\"ג ע' 221. — וכן אמר אז (לאחרי הגאולה די\"ב תמוז) מאמרי ד\"ה ברוך הגומל (נדפסו בסה\"מ קונטרסים שם; סה\"מ תרפ\"ז)."],["4","4","סדר ברכת הנהנין לאדה\"ז פי\"ג, ס\"ה."],["5","5","מכילתא (ורש\"י) יתרו יט, ה."],["6","6","ראה בזה — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041314\" data-slug=\"likkutei-sichot\" data-id=\"1300041314\">לקו\"ש ח\"ד ע' 1315</a>. ועוד."],["7","7","שאז היתה סכנת נפשות ממש, כדלקמן ס\"ה."]]],[1300281137,"איז ער געווען אונטער א „השגחה\" פון ממשלה ההיא)],\nאיז דאך ידוע, אז אין דער התחלה פון יעדן ענין איז כלול די גאנצע זאך. ע\"ד ווי מען געפינט אין דעם ענין פון ראשי־תיבות — אן ענין ע\"פ תורה און אויך בתורה⁸ — אז דער ערשטער אות פון א ווארט איז מרמז אויף דעם גאנצן ווארט⁹, וכדומה¹⁰; ועד\"ז בעניננו: אז די גאנצע גאולה פון רבי'ן איז געווען נרמז און „כלול\" אין דער התחלת הגאולה פון ג' תמוז.\nג. דער תוכן כללי פון דעם מאסר וגאולה פון רבי'ן איז דאך פארבונדן מיט זיין עבודה פון הרבצת התורה והחזקת היהדות והפצתם אין מדינה ההיא, וואס די עבודה בימים ההם האט געפאדערט מסירת נפש בפועל.\nאון נאכמער: ווי גערעדט כמה פעמים¹¹, איז דאס געווען ניט סתם א מסירת נפש, נאר א מסירת נפש בלי הגבלות און חשבונות. ווען מ'וואלט זיך אריינגעלאזט אין א חשבון צי עס זיינען דא אויסזיכטן על פי טבע צו מצליח זיין אין דער עבודה (וכיו\"ב), וואלט ניט געווען קיין ארט צו אנגיין מיט דער ארבעט, ועאכו\"כ ניט צו מוסר נפש זיין זיך אויף דעם (ומכ\"ש וק\"ו¹² — ניט צו איינשטעלן די לעבנס פון תלמידיו ושלוחיו צוליב דער עבודה).\nאון דעם אופן פון מסירת נפש אן קיינע חשבונות האט מען געזען בגלוי ביים רבי'ן אין זיין אויבנדערמאנטער הנהגה בכלל, ובפרט בקשר צו זיין גאולה בג' תמוז, ביז אז דער עצם „תאריך\" פון ג' תמוז (בשייכות צו דער גאולה) דערמאנט אויף זיין מסירת נפש, כדלקמן.\n— ויש לומר, אז דאס וואס די גאולה פון ג' תמוז איז געווען פארבונדן מיט דער דרגא פון מסירת נפש — אן קיינע הגבלות פון „חשבון\" — איז ווייל אין דער התחלה פון דער גאולה האט זיך געדארפט אויסדריקן דער תוכן כללי פון דעם מאסר וגאולה.\nד. דער רבי, בעל הגאולה והשמחה, האט דערציילט¹³, אז דאנערשטיק ר\"ח תמוז פאר מיטאג האט מען אים אנגעזאגט די ידיעה אז מ'לאזט אים ארויס פון בית האסורים און מ'פארשיקט אים אויף דריי יאר גלות אין דער שטאט קאסטראמא. דערביי האט מען אים געלאזט וויסן, אז באטאג וועט מען אים באפרייען פון תפיסה, מ'האט אים דערלויבט צו פארברענגען זעקס שעה מיט זיינע בני בית און אנגעזאגט אז ביינאכט וועט ער מוזן פארלאזן די שטאט און פארן קיין קאסטראמא.\nאזוי ווי דאס איז געווען דאנערשטיק, האט דער רבי געפרעגט: ווען וועט ער אנקומען אין קאסטראמא? האט מען אים געענטפערט אז ער וועט אהין אנקומען שבת. האט דער רבי געזאגט, אז שבת וועט ער בשום אופן ניט פארן. און ערשט נאך א ספעציעלער השתדלות אין די קרייזן פון דער ממשלה האט מען גע'פועל'ט אז דער רבי זאל קענען פארן",[["8","8","ראה שבת קה, רע\"א: מנין ללשון נוטריקון מן התורה כו'. ובכ\"מ."],["9","9","עיין שער היחוד והאמונה פי\"ב. ועוד."],["10","10","כמו ענין „ראש השנה\" שבו כלול החיות של כל השנה (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380934\" data-slug=\"likkutei-torah\" data-id=\"4001380934\">לקו\"ת ר\"ה נג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">שם נח, א</a>. עטרת ראש בתחלתו בארוכה. ועוד)."],["11","11","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181311\" data-slug=\"likkutei-sichot\" data-id=\"1300181311\">לקו\"ש חי\"ח ע' 302</a> ואילך. ועוד."],["12","12","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181313\" data-slug=\"likkutei-sichot\" data-id=\"1300181313\">לקו\"ש שם ע' 304</a>."],["13","13","ראה ספר השיחות תש\"א ע' 139. ס' התולדות שם ע' 212 ואילך. לקו\"ש ח\"ד ע' 1063."]]],[1300281138,"זונטיק, ג' תמוז (און ביז דעמאלט איז ער געבליבן אין טורמע).\nאיינער פון די וואס האבן בפועל דורכגעפירט דעם ארעסט פון רבי'ן האט געזאגט דעם רבי'ן, אז אויב ער וועט ניט מסכים זיין צו פארן דאנערשטיק ביינאכט און אנקומען שבת אין קאסטראמא, וועט ער אים ניט ארויסלאזן פון טורמע. האט דער רבי אים געענטפערט, אז ער איז גרייט צו בלייבן אין טורמע וויפל עס זאל ניט זיין, אבער שבת וועט ער בשום אופן ניט פארן!\nה. אזא הנהגה, צו שטעלן זיך מיט אזא תוקף ניט צו פארן אום שבת, פאדערט הסברה:\nדורך זיין אפזאגן זיך אויסצופאלגן דעם באפעל צו פארן גלייך אין קאסטראמא (ווען מ'איז שוין געווען מוכן אים צו באפרייען פון טורמע) און בלייבן אין טורמע — האט דער רבי זיך אריינגעשטעלט גלייך אין א מצב פון ודאי סכנה:\nמלכתחילה איז דאך אויף אים געווען א גזר דין פון היפך החיים ר\"ל, נאר דורך השתדלות האט מען די גזירה מבטל געווען און עס פארביטן אויף דעם לייכטערן עונש פון (צען יאר, און דערנאך) דריי יאר אין גלות; און אויך נאכדעם, האבן די וועלכע האבן מלכתחילה ארויסגעגעבן דעם גזר דין הראשון הנ\"ל זייער דיעה ניט געביטן, מ'האט זיי געצוואונגען (פון די העכערע ממשלה־קרייזן) אז בלייבנדיג בתפקידם ובתקפם זאלן זיי אבער מבטל זיין דעם פרט (אורטייל) און באפרייען דעם רבי'ן פון טורמע — איז דאך מובן, אז באופן זה איז זיין בלייבן ברשותם אין טורמע געווען סכנת נפשות ממש; ובפרט אז דאס גופא, וואס דער רבי האט זיך אפגעזאגט צו פארן אום שבת, האט ביי זיי ארויסגערופן א כעס נוסף וגדול: א מרידה געגן זייער פקודה, מפרסם געווען אין זייער טורמע שמירת שבת ובפרסום הכי גדול (הפקידים והאסורים), ניט קענען דורכפירן זייער מזימה צו גורם זיין אז דער רבי זאל פארן שבת¹⁴.\nלאידך, וויבאלד די יציאה מבית האסורים האט געדארפט זיין דאנערשטיק בייטאג, איז דאך דער ענין פון חילול שבת געווען (א) ניט באותו זמן כלל, און (ב) בלויז בגדר ספק — וכמה ספקות. ווארום עס איז דאך נאך דער באפרייאונג ביום החמישי געווען נאך א גרעסערע מעגליכקייט פון השתדלות ובהנהגתו פון רבי'ן — אז ער זאל ניט דארפן ארויספארן גלייך ביינאכט; און אפילו אויב מ'וואלט עס ניט געקענט באווייזן אין דער קורצער צייט, איז געבליבן א גאנצער מעת־לעת (פון נסיעה) ביז שבת, וואס במשך זמן זה איז געווען די מעגליכקייט להשתדלות גדולה אז ער זאל זיך אפשטעלן אין מיטן וועג ביז נאך שבת.\n[און אפילו אויב ער וואלט געווען געצוואונגען בלייבן אין באן־וואגאן ביום השבת — איז ער דאך אן אנוס, און בלויז אין אן איסור דרבנן — איסור תחומין¹⁵ (דער געפינען זיך אין א",[["14","14","ראה ס' התולדות שם."],["15","15","ראה שו\"ת חתם סופר ח\"ו סי' צז (ובעוד אחרונים) דברכבת ליכא אלא משום איסור תחומין, וראה שו\"ע אדה\"ז סת\"ד ס\"ב „שנהגו כהאומרים שעכשיו אין לנו רשות הרבים גמורה\", ובמילא אין איסור תחומין של תורה, אלא דרבנן. אבל אין לומר דכאן מותר, דכיון שהוא למעלה מיו\"ד שהוא רק ספק, ובספק דרבנן מקילין (שו\"ע אדה\"ז סרמ\"ח ס\"ג. סת\"ד ס\"ג) — כי ברחב ד' יש תחומין גם למעלה מיו\"ד (שו\"ע אדה\"ז סת\"ד ס\"א),"]]],[1300281139,"(פארנדיקן) באן איז ניט אן עשיית מלאכה)].\nאיז דאך לכאורה תמוה ביותר: פארוואס האט זיך דער רבי געשטעלט מיט אזא תוקף קעגן דעם פארן און זיך אריינגעשטעלט תיכף אין א מצב פון סכנה — לכאורה האט ער די ערשטע זאך געדארפט גלייך ארויסגיין פון (דער סכנה —) בית האסורים, און דערנאך זוכן עצות ווי ער זאל ניט דארפן פארן שבת?\nו. אזא מסירת נפש הנהגה האט מען געזען ביים רבי'ן אין דעם גאנצן צוגאנג צו דער עבודה פון הרבצת התורה וחיזוק היהדות במדינה ההיא.\nווי גערעדט כמה פעמים¹⁶, האט דעם רבי'נס מסנ\"פ ארומגענומען (ניט בלויז ענינים אויף וועלכע מ'איז מחויב זיך מוסר נפש זיין, נאר) אויך ענינים וועלכע זיינען בגדר פון „הרשות בידו\". נאך מער: ווי גערעדט אמאל בארוכה¹⁷, איז זיין מסירת נפש געווען אויך אויף אזעלכע ענינים וואס כמה גדולי וחכמי ישראל האבן געהאלטן אז מען דארף זיך אויף זיי ניט מוסר נפש זיין.\nאיז ווען עס רעדט זיך וועגן כללות העבודה פון רבי'ן במדינה ההיא, קען מען נאך פארשטיין פארוואס זיין הנהגה איז געווען באופן כזה. ווייל זעענדיק אז דער מצב פון אידן במדינה ההיא איז אזא, אז דער עצם קיום פון אידן און אידישקייט איז געשטאנען אין גרויס סכנה — שלא יכבה נר ישראל ח\"ו, און וויסנדיק זיין שליחות אלס נשיא ישראל וואס דארף זארגן פארן קיום פון עם ישראל, האט דער רבי אין זיין מסירת נפש פאר אידן זיך ניט גערעכנט מיט קיינע חשבונות און קיינע הגבלות.\nבנדו\"ד אבער, וויבאלד אז דא איז דער מדובר ניט וועגן אן ענין וואס רירט אן עכ\"פ „טובת\" רבים וציבור, נאר וועגן א שאלה (לכאורה) בנוגע זיין הנהגה באופן פרטי — צי ער זאל פארן דעמאלט אין קאסטראמא אדער ניט — פארוואס האט דער רבי אויך אין דעם פאל זיך אריינגעשטעלט אין אזא מסירת נפש?",[["","","שלכן הולך בקרון אע\"פ שגבוה י\"ט יש בו משום תחומין (שו\"ע אדה\"ז סרס\"ו ס\"ז). וראה גם שו\"ת חת\"ס שם, שו\"ת שואל ומשיב חמישאה ס\"ג ועוד (כמה מהם נסמנו בכף החיים סת\"ד אות ה). אבל להעיר משו\"ת חת\"ס שם סצ\"ח שמחלק בין קרון ע\"י בהמות, שרק בזה אמרינן כארעא סמיכתא משום שא\"א שתלך י\"ב מיל כו' בלי שתעמוד — וקרון שהקיטור מוליכו שאין אומרים בזה (כשאינו עומד*) כארעא סמיכתא, והאיסור ברכבת הוא רק משום ספיקא [אי משום כל תיקו דאיסורא (בנדו\"ד, אי יש תחומין למעלה מיו\"ד) לחומרא אפי' בדרבנן, או מפני שלהרמב\"ם חוץ לי\"ב מיל דאורייתא וספיקא לחומרא]. ולסברא זו, מכיון שאדה\"ז פסק (כנ\"ל) אשר (א) בזמן הזה שאין רה\"ר גמורה אין תחומין של תורה, (ב) למעלה מיו\"ד בספק דרבנן מקילין** — לכאורה מותר להפליג לפני השבת (ראה סרמ\"ח שם). ולהלכה כבר אסרו באחרונים בפשטות הנסיעה ברכבת הברזל וכיו\"ב בשבת (כנ\"ל). ואכ\"מ. *) וצריך בירור בנדו\"ד (נסיעת כ\"ק מו\"ח אדמו\"ר לקאסטראמא) — האם היתה הרכבת עומדת באמצע הדרך (בשבת). **) ולהעיר משו\"ע אדה\"ז סרמ\"ח בקו\"א סק\"ג דאף גבי קרון אף למ\"ד י\"ב מיל דאורייתא אין איסור דאורייתא דלכ\"ע לא שייך תחומין כשהספינה הולכת. ע\"ש. וכבר העיר בס' זכרון יוסף (ברדיוב, תרפ\"ט) אות ריא שלכאורה זה סותר פסק אדה\"ז בסי' רסו שם דבקרון יותר מי\"ב מיל (להאומרים שהוא מה\"ת) יש תחומין מה\"ת. ואכ\"מ."],["16","16","ראה הנסמן בהערה 11."],["17","17","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181330\" data-slug=\"likkutei-sichot\" data-id=\"1300181330\">לקו\"ש חי\"ח ע' 321</a>. וראה שם שי\"ל שמסנ\"פ דכ\"ק מו\"ח אדמו\"ר אז היתה כעין קנאות דפינחס, שמלכתחילה היתה „שלא ברצון חכמים . . אלולי (שראו שצדק מלכתחילה — ע\"י) שקפצה עליו רוה\"ק ואמרה והיתה לו גו'\" (ירושלמי סנהדרין פ\"ט ה\"ז), שכמה חכמי וגדולי ישראל סברו שאין לו למסנ\"פ כו'. עיי\"ש."]]],[1300281140,"ואדרבה: דורך דער הנהגה שטעלט ער איין אין סכנה די גאנצע עבודה שלו בהרבצת התורה וחיזוק היהדות!\nז. וי\"ל די הסברה בזה:\nנקודת ענין זה — האט זיך דא ניט געהאנדלט צי מ'זאל זיך יא אדער ניט מוסר נפש זיין צוליב שבת, נאר דא איז געשטאנען די שאלה פון קידוש השם אדער חילול השם:\nדי מטרה פון די וואס האבן ארעסטירט דעם רבי'ן איז געווען כדי צו צעשטערן די ארבעט פון רבי'ן בהחזקת היהדות. אילו יצוייר אז דער רבי וואלט ניט גלייך קעגנגעשטעלט זיך די פקודה צו פארן באלד נאך זיין באפרייאונג, כרצונם (אז דער רבי זאל פארן שבת) — וואלט דאס פאר זיי געווען א נצחון: דער רבי האט „מסכים\" געווען צו פארן בשבת.\nדי אלע הערער פון דער הסכמה — וואלטן דאך ניט געוואוסט די אלע חשבונות האמורים לעיל (אז מען איז זיך משתדל בחשאי און מען איז זיכער צו פועל זיין אז דער רבי זאל ניט דארפן פארן שבת כו') —\n[און ווי גערעדט כמה פעמים, אז בשעת עס רעדט זיך וועגן קידוש השם און חילול השם, איז ניט נוגע צי די זאך וועגן וועלכער עס רעדט זיך איז פארבונדן מיט אן איסור הכי חמור אדער אן איסור הכי קל — מען רעכנט זיך נאר מיט דעם צי די מענטשן ארום זיינען עלול צו אויסטייטשן דאס אלס אן ענין הפכי¹⁸].\nח. און דאס איז אויך די שייכות פון ג' תמוז צו פ' חוקת:\nאין פ' חוקת¹⁹ ווערט דערציילט וועגן דעם חטא פון „מי מריבה\" וואס צוליב דעם זיינען משה ואהרן נענש געווארן אז „לא תביאו את הקהל הזה אל הארץ גו'\"²⁰.\nאיז לכאורה ניט פארשטאנדיק²¹: מיט וואס איז דער חטא געווען אזוי הארב, אז צוליב דעם זאל משה ניט אריינגיין אין א\"י? — ובפרט אז די תורה דערציילט וועגן נאך ענינים ביי משה'ן וואס משה איז צוליב זיי נענש געווארן — און פונדעסטוועגן איז ער פאר זיי ניט נענש געווארן מיט אזא הארבן עונש. און דוקא דער חטא — דער שינוי צו שלאגן דעם סלע אנשטאט ריידן צו אים — האט געבראכט די גזירה חמורה אז ער זאל ניט אריין אין א\"י?!\nנאר דער טעם דערויף ווערט אנגעדייט אין פסוק²⁰ „יען לא האמנתם בי להקדישני לעיני בנ\"י\", און ווי רש\"י איז דאס מבאר, אז דערפאר איז דער חטא מער חמור ווי די טענה פון משה רבינו צום אויבערשטן „הצאן ובקר ישחט להם\"²² — ווייל דארט „לפי שבסתר חסך עליו הכתוב, וכאן שבמעמד כל ישראל לא חסך עליו הכתוב מפני קידוש השם\".\n— ד.ה. אז ווען עס רעדט זיך וועגן אן ענין פון קידוש השם אדער הפכו, איז נוגע בלויז ווי אזוי דאס ווערט אויסגעטייטשט דורך אנדערע.\nט. א טיפערער ענין י\"ל אין דעם:",[["18","18","ראה רמב\"ם הל' יסודי התורה פ\"ה הי\"א (אבל לא נאמר שיש למסור נפשו על הענינים שהובאו שם)."],["19","19","כ, ז ואילך."],["20","20","שם, יב."],["21","21","וכבר האריכו במפרשי התורה בזה."],["22","22","בהעלותך יא, כב."]]],[1300281141,"דער אופן ההנהגה הנ\"ל פון רבי'ן — וואס ער האט זיך קעגנגעשטעלט די פקודה פון די וועלכע האבן אים ארעסטירט — איז געווען ניט נאר ווען עס האט אנגערירט (בגלוי) א זאך פון אידישקייט, נאר ווי דער רבי האט דערציילט²³, אז ער האט ביי זיך געמאכט א פעסטן באשלוס, אז ער זאל כלל ניט נתפעל ווערן פאר זיי. ניט נאר ער זאל זיך ניט רעכענען מיט זיי אין זאכן וואס זיינען נוגע (בגלוי) צו יראת שמים.\nאון צוליב דער הנהגה האט מען דעם רבי'ן באשטראפט מיט יסורי הגוף ר\"ל, אים געשלאגן וכו'.\n— אין אזא הנהגה איז דאך ניט שייך די חשבונות הנ\"ל פון קידוש השם אדער אז עס וועט אנרירן די ארבעט פון הרבצת התורה כו' — איז וואס איז דער טעם פון דעם אופן ההנהגה פון רבי'ן?\n— איז אויך דער ביאור אין דער הנהגה נרמז אין פרשת חוקת, גלייך אין שם הסדרה: „חוקת\":\nיו\"ד. דער אלטער רבי איז מבאר²⁴ אז „חוקה\" איז מלשון חקיקה (איינקריצן).\nדער יתרון פון חקיקה לגבי כתיבה:\nביי כתיבה זיינען די אותיות א צוגעגעבענע זאך צום קלף, אויף וועלכן זיי זיינען געשריבן. דורך דער כתיבה ווערן טאקע די אותיות פאראייניקט מיטן קלף, דאס איז אבער באופן ווי צוויי זאכן וואס ווערן פאראייניקט. און דעריבער, קען אין דעם זיין א שינוי ביז ביטול — מען קען אפטיילן (אפמעקן) די אותיות פון דעם קלף.\nמשא\"כ ביי חקיקה, זיינען די אותיות ניט קיין באזונדער מציאות פון דער זאך אין וועלכע זיי זיינען אויסגעקריצט, נאר זיי זיינען מיני' ובי', זיי זיינען א טייל פון דער מציאות פון דעם אבן (טוב) אין וועלכן זיי זיינען אויסגעקריצט. און דערפאר איז אוממעגלעך אפצוטיילן די אותיות פון דעם אבן — דער אנרירן די אותיות — איז אנרירן דעם אבן (טוב).\nדי זעלבע זאך איז ברוחניות: ווען עבודת השם איז בלויז ווי א צוגעגעבענע זאך צו דער מציאות האדם, איז מעגלעך אז אין דעם זאלן זיין שינויים. עס קען זיין א מצב אז מ'זאל ניט מקיים זיין אן ענין פון עבודת ה' (מאיזו סיבה שתהי', כולל אויך — אז מ'איז אן אנוס), און זיין מציאות זאל דערביי ניט ווערן „אנגערירט\".\nבשעת אבער עבודת השם ווערט איינגעקריצט אין זיין מציאות — עבודת השם ווערט א טייל פון אים אליין — דעמאלט איז ניט שייך צו פאנאנדערטיילן אים פון עבודת השם. צונעמען פון אים אן ענין פון עבודת השם מיינט צונעמען (צעשטערן) זיין מציאות (ע\"ד איינער וואס וויל צעשטערן די צורת האותיות פון אבן טוב, דארף זיין שבירת האבן טוב²⁵).\nאון דערפאר בא א אידן וואס עבודת השם איז ביי אים חקוק בנפשו, איז ער זיך מוסר נפש אויף כל פרט ופרט פון אידישקייט, אן חשבונות²⁶, ווייל ס'איז",[["23","23","ראה תחילת הסיפור — במקומות שנסמנו בהערה 13."],["24","24","לקו\"ת פרשתנו (נו, א). וראה שם בחוקותי מה, א ואילך."],["25","25","ושאני שבירת הלוחות דאירע בזה נס ד„לוחות נשברו ואותיות פורחות\" (פסחים פז, סע\"ב. חדא\"ג מהרש\"א שם) — אף שהיו אותיות החקיקה. ואכ\"מ."],["26","26","וזוהי ג\"כ השייכות לתיבת „חוקת\" כפי פירושה הפשוט, חוקה שלמעלה מטעם. וראה בארוכה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181309\" data-slug=\"likkutei-sichot\" data-id=\"1300181309\">לקו\"ש חי\"ח ע' 300</a> ואילך."]]],[1300281142,"אוממעגלעך פאנאנדערטיילן צווישן אים און וועלכן ענין עס זאל זיין פון עבודת השם.\nיא. עד\"ז איז געווען די הנהגה פון רבי'ן:\nוויבאלד אז ענינים פון תורה ומצות זיינען ביי אים געווען באופן של חקיקה²⁷, איז דעריבער זיין מסירת נפש ניט געווען פארבונדן מיט קיינע חשבונות²⁷ (צי אין דעם פאל ההלכה אז מען דארף זיך מוסר נפש זיין, אדער צי עס לוינט זיך כו', וכיו\"ב),\nביי אים איז דאס ניט געווען אן ענין פון מסירת נפש צוליב אן אנדער זאך (שחוץ הימנו), ביי וועלכער עס איז שייך א חשבון צי מ'זאל זיך מוסר נפש זיין — נאר דאס איז געקומען כאילו ווי בדרך ממילא: וויבאלד אז עבודת השם איז געווען א טייל פון זיין מציאות גופא, ביז אז עס איז אוממעגלעך צו פאנאנדערטיילן צווישן זיי, איז בדרך ממילא ביי אים געווען אלע ענינים פון עבודת ה' ביז צו מסירת נפש.\nומהאי טעמא איז זיין מסנ\"פ געווען ניט נאר אויף זאכן וואס האבן בגלוי אנגערירט זיין עבודה, נאר ער האט זיך מוסר נפש געווען אויף ניט „נכנע\" ווערן (פאר די וועלכע האבן אים ארעסטירט) באיזה אופן שהוא:\nזיין ניט רעכענען זיך מיט זיי איז ניט נאר געווען אן ענין פון חשבון כו', נאר ער האט בעצם ניט געקענט נכנע ווערן באיזה אופן שהוא — פאר אזעלכע וואס שטערן די ארבעט פון הרבצת התורה כו', וויבאלד אז די עבודה איז ביי אים אין אן אופן פון „חוקת\", חקיקה מיני' ובי'.\n(משיחות ש\"פ חוקת תשמ\"א, תשמ\"ג)",[["27","27","להעיר מלקו\"ת פרשתנו שם (נז, רע\"ג): משה . . ונחנו מה ח\"ע . . אותיות החקיקה."]]],[1300281143,"<h3>חוקת</h3>\nא. אין הלכות פרה אדומה¹ זאגט דער רמב״ם: ותשע פרות אדומות נעשו משנצטוו במצוה זו עד שחרב הבית בשניי׳ ראשונה עשה משה רבינו שניי׳ עשה עזרא ושבע מעזרא עד חורבן הבית והעשירית יעשה המלך המשיח² מהרה יגלה אכי״ר.\nדער מקור פון רמב״ם איז אין משנה³ וואו עס ווערט געבראכט א פלוגתא וויפל פרות אדומות עס זיינען געמאכט געווארן ביז חורבן בית שני — צי שבע אדער תשע (און די משנה רעכנט אויס „מי עשאם״), און דער רמב״ם פסק׳נט (כדעת חכמים) אז עס זיינען געווען תשע און איז דערנאך מוסיף „והעשירית יעשה המלך המשיח כו׳״.\nמען דארף אבער פארשטיין: דער ספר היד איז ניט א ספר פון דברי ימי ישראל, נאר א ספר פון הלכה (ווי דער רמב״ם זאגט בהקדמת הספר) — איז למאי נפק״מ אין א ספר של הלכה⁴ דער מספר הפרות וואס זיינען געמאכט געווארן במשך הדורות? ובפרט (בלשון הש״ס⁵) „מאי דהוה הוה״.\nנאך מער איז די תמי׳ בנוגע דעם סיום דברי הרמב״ם „והעשירית יעשה המלך המשיח מהרה יגלה אכי״ר״ — וואס דאס ווערט ניט דערמאנט אפילו במדרז״ל שי״ל שהם המקור דהרמב״ם⁶!\nבנוגע דער עצם ההוספה „והעשירית יעשה המלך המשיח״ קען מען מסביר זיין (עכ״פ בדוחק), וויבאלד אז דער רמב״ם ברענגט בספרו אויך הלכתא למשיחא, זאגט ער אז מלך המשיח וועט אויך מאכן א פרה אדומה⁷; אבער עס בלייבט תמוה וואס דער רמב״ם איז דערנאך מוסיף „מהרה יגלה אכי״ר״ — אריינשטעלן בספר הלכה⁸ א בקשה ותפלה אויף ביאת המשיח?",[["1","1","ספ״ג."],["2","2","ע״ד „עשה משה רבנו״ (והבפועל — ע״י אלעזר הכהן) כי הוא „רבנו״ והורה וציווה כו׳, ועד״ז הבפועל דפרה העשירית ע״י כהן אבל ההוראה והציווי ע״י יו״ח דדוד כי הוא המלך המשיח."],["3","3","פרה פ״ג מ״ה."],["4","4","משא״כ במשנה שלפעמים הובאו ענינים שאינם הלכה. — אבל ראה משנה אחרונה שם (שמתרץ למאי נפק״מ „מי עשאן״). ולהעיר מתוי״ט שם מ״ג (ד״ה וזורקו). וי״ל שידיעת מספר הפרות נפק״מ (בזמן בית שני) בההלכה (פרה שם מ״א) ד„מזין עליו . . מכל חטאות שהיו שם״ (אלא שאם „לא מצאו משבע עושין משש כו׳ ומאחת״ — שם מ״ה). — וברמב״ם ראה לקמן סוס״ב (ובהערה 25)."],["5","5","יומא ה, ב. ועוד."],["6","6","וצ״ע וחיפוש מקורו דהרמב״ם. ולהעיר מאוה״ת שה״ש בתחלתו: וראיתי בספר א׳ שהעשירית תהי׳ לימות המשיח (ראה הערה 2). ולהעיר מכו״כ ענינים שהעשירי בימוה״מ (או ע״י משיח) — שירה העשירית, מנין העשירי דבנ״י וכו׳, כיבוש ארץ עשר אומות, עשר נימין דכינור דביהמ״ק וכו׳. וראה מדרש מעשה תורה אות יו״ד. — ובקרית ספר (להמבי״ט) על הרמב״ם כאן, מוסיף (על ל׳ הרמב״ם — „והעשירית . . מהרה יגלה״): כנגד עשרה פסוקים שיש מתחלת פרשת פרה עד לחוקת עולם שהם בעניין עשיית הפרה."],["7","7","אבל לכאורה דוחק, כי מאי קמ״ל שמלך המשיח יצוה שיקוים ציווי התורה לעשות פרה אדומה?"],["8","8","משא״כ כשמוסיף הרמב״ם בפיה״מ (סנהדרין פ׳ חלק ד״ה וכת שני׳), וכן באגרת תימן (וכ״ה גם במקור הערבי שם — ראה הוצאת קאפח) תפלה זו"]]],[1300281144,"[אין ספר היד דארף דער רמב״ם זאגן דעם דין אז א איד דארף מתפלל זיין אויף ביאת המשיח⁹ (און ער ברענגט טאקע אין סדר תפלות שלו¹⁰ דעם נוסח פון תפלת י״ח, וואס אנטהאלט („שאלת¹¹ כל הדברים שהן כמו אבות לכל חפצי איש ואיש ולצרכי הציבור כולן״, כולל) די תפלות אויף ביאת המשיח) — אבער וואס פאר אן ארט האט עס אז דער רמב״ם זאל אריינשטעלן בספר היד⁸ זיין תפלה אויף ביאת המשיח?].\nאפילו את״ל אז עס האט יע אן ארט, וואלט דאס געהאט, לכאורה, מער ארט ווען דער רמב״ם טוט עס אין די פרקים וואו די „סוגיא״ איז וועגן מלך המשיח — אין די לעצטע צוויי פרקים פון (הלכות מלכים¹² —) ספר היד, וועלכע ריידן וועגן משיח וימות המשיח¹³ (ביז אז עס זיינען פאראן דרוקן פון רמב״ם¹⁴ וואו די כותרת פון די צוויי פרקים איז „הלכות מלכים ומלחמות ומלך המשיח״)\n— איז דארטן געפינט מען ניט אז דער רמב״ם זאל אריינשטעלן א בקשה ותפלה אויף ביאת המשיח; און דוקא דא אין הלכות פרה אדומה, וואו די „סוגיא״ איז ניט וועגן משיח׳ן נאר וועגן פרה אדומה (און דער ענין פון משיח קומט אריין נאר בדרך אגב) — איז דער רמב״ם מוסיף אט די תפלה?!\nב. וועט מען דאס פארשטיין בהקדם א שינוי אין דעם אופן ווי דער רמב״ם ברענגט דעם ענין — לגבי ווי עס שטייט אין משנה:\nאין משנה ווערט געבראכט וועגן די שבע (או תשע) פרות אדומות בהמשך צום דין „לא מצאו משבע עושין משש כו׳״. אין אנהויב פרק¹⁵ זאגט די משנה אז מ׳איז מפריש דעם כהן השורף את הפרה מביתו שבעת ימים און „מזין עליו כל ז׳ הימים מכל חטאות שהיו שם״ (מאפר כל פרות אדומות אשר נעשו מימות משה כו׳¹⁶). און בהמשך לזה¹⁷ זאגט די משנה „לא מצאו משבע עושין משש וכו׳״, און דערנאך איז די משנה ממשיך „ומי עשאם הראשונה עשה משה כו׳״:\nדאקעגן אין רמב״ם קומט דער ענין בהמשך צו אן אנדער דין¹⁸ — „ושלשה¹⁹ חלקים היו חולקין את כל אפרה, אחד ניתן בחיל ואחד בהר המשחה ואחד מתחלק לכל המשמרות, זה שמתחלק לכל המשמרות היו הכהנים מקדשין ממנו וזה שניתן בהר המשחה היו ישראל מזין ממנו וזה שניתן בחיל הי׳ מוכן ומוצנע שנאמר²⁰ והיתה לעדת",[["","","„מהרה יגלה״. וראה בחיי ריש פרשתנו, שמונה עשר הפרות כו׳ ומסיים „עשירית עתיד לשרוף מלך המשיח במהרה בימינו״. ולהעיר מרמב״ן פרשתנו (יט, טז בסופה) „ואנחנו בעונותינו טמאי הגלות כו׳ עד יערה עלינו כו׳ אמן וכן יהי רצון במהרה בימינו״."],["9","9","ראה פיה״מ סנהדרין שם (היסוד הי״ב) — בתרגום קאפח (משא״כ בפיה״מ לפנינו) — „ולהתפלל לבואו״."],["10","10","בסו״ס אהבה. וראה הל׳ תפלה פ״ב ה״ג."],["11","11","ל׳ הרמב״ם שם פ״א ה״ד."],["12","12","פי״א־יב."],["13","13","או לפנ״ז — בהלכות תשובה פ״ט ה״ב."],["14","14","ויניציאה (רפד. שי)."],["15","15","שם מ״א."],["16","16","ל׳ הרמב״ם בפיה״מ שם. ועד״ז בר״ש ורע״ב שם. רש״י יומא ד, רע״א."],["17","17","ראה מפרשי המשניות שם."],["18","18","ודין הנ״ל שבמשנה (שמזין מכל החטאות כו׳) הובא ברמב״ם לפנ״ז (פ״ב ה״ו)."],["19","19","והוא ממשנה פרה ספ״ג ותוספתא שם ספ״ג."],["20","20","פרשתנו יט, ט."]]],[1300281145,"בני ישראל למשמרת מלמד שמצניעין ממנו, וכן היו מצניעין מאפר כל פרה ופרה ששורפין בחיל״ — ובהמשך לזה זאגט דער רמב״ם „ותשע פרות כו׳״.\nוואס דאס איז א חילוק עיקרי אין תוכן הענין:\nלויטן סדר אין משנה, קומט דער ענין (וועגן די פרות שנעשו במשך הדורות) בהמשך צו עשיית הפרה צוליב דעם שימוש באפר הפרה (אז מ׳איז מזה פון דעם אפר הפרה אויף דעם כהן השורף את הפרה²¹);\nמשא״כ אין רמב״ם קומט עס בהמשך צום דין אז מען מוז מצניע זיין „מאפר כל פרה״ עס זאל זיין למשמרת. דער דין פון „למשמרת״ איז — אין מקרא יוצא מידי פשוטו — ניט נאר בכדי עס זאל זיין מוכן להזאה²², נאר עיקר ענינו איז (כשמו) — אז דער אפר זאל זיין מוצנע למשמרת. דער חלק פון אפר איז ניט נאר א חיוב אלס א טייל פון הזאת פרה אדומה, נאר ס׳איז א באזונדער דין אז דער אפר פון יעדער פרה מוז זיין מוצנע למשמרת (אפילו ווען מ׳וואלט עס ניט געדארפט צוליב הזאה לטהר מטומאת מת).\nבסגנון אחר (ובעומק יותר): דער תוכן החיוב פון „למשמרת״ איז — אז עס זאל שטענדיק זיין אפר „מוכן ומוצנע״²³, ובלשון הרס״ג²⁴ „ופרה למשמרת בתדר״ [ווארום דאס איז דער מושג ותוכן פון „למשמרת״, אז די זאך איז משומר באופן אז עס איז שטענדיק פאראן]. קומט אויס, אז „למשמרת״ איז ניט (נאר) א באזונדער חיוב אויף יעדער פרה אז מען דארף מצניע זיין א טייל פון איר אפר למשמרת (ע״ד ווי מען דארף פון דעם אפר נעמען א חלק פאר די כהנים און א חלק פאר כל ישראל) — נאר דאס איז (אויך) א חיוב כללי",[["21","21","וכן על הכה״ג לפני יוהכ״פ (ראה פרה שם מ״א. יומא ח, א. וש״נ)."],["22","22","אף שלכאורה ג״ז נכלל בו, כדיוק לשון הרמב״ם „מוכן ומוצנע״ (וראה הערה הבאה) — ראה מפרשים למשנה פרה שם (וכן בפיה״מ להרמב״ם) שהיו מזין על הכה״ג וכהן השורף את הפרה מן האפר המוצנע (בחיל) למשמרת. וכ״ה בפרש״י יומא שבהערה 16. וראה בארוכה ביאור הרי״פ פערלא לסהמ״צ הרס״ג פרשה מה (קצא, א). אבל להעיר שבס׳ היד (הל׳ פרה אדומה פ״ב ה״ד ואילך. וכן בהל׳ עבודת יוהכ״פ פ״א ה״ד) לא נזכר (בפירוש) שהוא מהאפר הנתון בחיל. וראה פרש״י עה״ת פרשתנו (יט, ט). תוי״ט שם ספ״ג. וראה ס׳ השיחות תשמ״ט ח״א (קה״ת תש״נ) ע׳ 343 הערה 10. וש״נ. ואכ״מ."],["23","23","ולהעיר מלשון הרמב״ם בסהמ״צ (מ״ע קיג) שמצות פרה אדומה היא „שיהי׳ אפרה מזומן למי שיצטרך אליו״ (וכ״כ במנין המצות בריש ספר היד „להיות אפרה מוכן״). אבל שם הכוונה שיהי׳ מוכן (כלשונו בסהמ״צ שם) „לטהרת טומאת מת״ (היינו השימוש בו בפועל, שזהו עיקר מטרת עשיית פרה אדומה); משא״כ החלק שמוצנע למשמרת, עיקר ענינו הוא — עצם מציאותו במקום מוצנע כו׳."],["24","24","בסהמ״צ שלו שם*. — ולהעיר מפרש״י פרשתנו מר׳ משה הדרשן (בסוף פרשת פרה אדומה) „למשמרת, כמו שפשע העגל שמור לדורות״. *) וראה בביאור הרי״פ פערלא שם, שכוונת הרס״ג היא לחלק שנתון בחיל (כדחז״ל שעל חלק זה נאמר „למשמרת״). אלא ששם ביאר שזהו עיקר המצוה כי ממנו מזים על הכה״ג. ע״ש. וזה דוחק כמשנ״ת ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161431\" data-slug=\"likkutei-sichot\" data-id=\"1300161431\">לקו״ש חט״ז ע׳ 418</a> ואילך. אבל ע״פ המבואר בפנים י״ל, שכוונת הרס״ג (גם) לחלק שנתון בחיל למשמרת (ולא לשימוש), שזהו ענין עיקרי בפרה אדומה, כבפנים. וראה גם ס׳ השיחות תשמ״ט שם בארוכה."]]],[1300281146,"(בהפרה) ותמידי²⁵, אז עס דארף שטענדיק זיין אפר הפרה מוצנע „למשמרת״.\nג. עפ״ז יש לומר, אז דאס איז אויך כוונת הרמב״ם מיט זיין ברענגען וועגן די „תשע פרות״ וואס מ׳האט געמאכט מזמן משה ביז חורבן בית שני:\nנאך דעם ווי דער רמב״ם ברענגט אז ס׳איז דא דער חיוב פון מצניע זיין אפר פרה „למשמרת״, וואס איז א חיוב תמידי (כנ״ל) — וויל דער רמב״ם ברענגען א חיזוק לדבריו, אז מ׳האט מקיים געווען אט דעם חיוב במשך כל הדורות; און דערפאר ברענגט ער אראפ וואס עס שטייט אין משנה וועגן די תשע פרות, פון וואס מען זעט, אז מ׳האט תמיד געהאט אפר הפרה²⁶ (וכדיוק לשון הרמב״ם — „תשע פרות אדומות נעשו משנצטוו במצוה זו עד שחרב הבית בשניי׳״ — ס׳איז תמיד געווען אפר הפרה „למשמרת״).\n[וע״ד ווי דער רמב״ם ברענגט אין אנהויב הלכות בית הבחירה²⁷ וועגן דעם „משכן שעשה משה רבינו״ און די פרטי השתלשלות שבזה (משכן שהעמידו בגלגל, משכן שילה, נוב גבעון) ביז נבנה המקדש בירושלים — דלכאורה איז אויך דארטן די שאלה „מאי דהוה הוה״?\nהאט מען שוין אמאל מבאר געווען²⁸, וויבאלד אז דער רמב״ם²⁹ האלט אז דער ציווי אויף בנין בית המקדש ווערט אפגעלערנט פון פסוק³⁰ „ועשו לי מקדש״ (וואס איז אנגעזאגט געווארן אין מדבר, איידער אידן זיינען אריין אין א״י), קומט אויס, אז דאס איז א מצוה תמידית אויף אלע זמנים. און דעריבער ברענגט דער רמב״ם די אריכות וועגן דעם משכן וואס מ׳האט אויפגעשטעלט במשך הדורות (ביז „נבנה המקדש בירושלים״) — צו באווייזן אז „ועשו לי מקדש״ איז א מצוה תמידית און מ׳האט",[["25","25","ועפ״ז נמצא, שלגבי החיוב ד„למשמרת״ כל העשר פרות אדומות הן כמו חפצא אחת, שע״י כולם יש אפר פרה „למשמרת״ תמיד [ויומתק עפ״ז טעם החיוב להזות על הכהן השורף את הפרה „מכל חטאות שהיו שם״ (ורק אם לא מצאו מכולם מזין (עכ״פ) מאחת, כנ״ל הערה 4)]. ובזה יומתק (ע״ד הרמז) שמביא הרמב״ם גם מספר הפרות (ולא רק מתי נעשו כו׳) — כי בזה שהן עשר פרות, שהוא מספר (אחד) שלם, עשירי׳ אחת*, מודגש שכולן יחד הן חפצא אחת. ולהעיר מלשון הרמב״ם „והעשירית יעשה כו׳״ (ולא — „והמלך המשיח יעשה עשירית״)."],["26","26","ולהעיר ממחז״ל (במדב״ר פרשתנו פי״ט, ו (ובידי משה ופי׳ מהרז״ו שם). הובא גם בפרש״י יומא שבהערה 16) דאפר פרה של משה קיים לעולם. וראה תוי״ט פרה שם מ״ג. משנה אחרונה שם מ״ה. גו״א ושפ״ח לפרש״י פרשתנו (יט, ב). של״ה חלק תושב״כ דרוש לפ׳ פרה (שנט, ב). ועפ״ז יומתק זה שהרמב״ם הזכיר רק משה ועזרא (ולא כל אלה שעשו שאר הפרות, אף שנזכרו במשנה שם) — כי משה ועזרא מדגישים ענין הנצחיות, דמעשה ידי משה נצחיים (ראה סוטה ט, סע״א), וכנ״ל דאפר פרה שלו לא כלה — וראה לקו״ש חל״ג ע׳ 127 ואילך; ועזרא שקול כמשה (ראה סנהדרין כא, סע״ב). ולהעיר מרמב״ם הל׳ ביהב״ח (ספ״ו) שדוקא כיבוש וקידוש עזרא קדשה לעתיד לבא."],["27","27","פ״א ה״א־ב."],["28","28","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161304\" data-slug=\"likkutei-sichot\" data-id=\"1300161304\">לקו״ש חט״ז ע׳ 304</a>. ע״ש באורך."],["29","29","שם ה״א."],["30","30","תרומה כה, ח. — ולא מן הפסוק „לשכנו תדרשו גו׳״, „והי׳ המקום אשר יבחר ה׳ גו׳״ (פ׳ ראה יב, ה. שם, יא) — ראה כס״מ לרמב״ם שם. לח״מ ריש הל׳ מלכים. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161298\" data-slug=\"likkutei-sichot\" data-id=\"1300161298\">לקו״ש שם ע׳ 298</a> ואילך ובהנסמן שם. *) להעיר מהראב״ע לשמות ג, טו. ס׳ הפרדס שער ב. ועוד."]]],[1300281147,"דעם ציווי מקיים געווען במשך כל הדורות (אויך לפני שבאו לירושלים)].\nאון וויבאלד אז דער רמב״ם האט אריינגעשטעלט בספרו אויך הלכתא למשיחא, כנ״ל — מוז ער דאך אויך ברענגען (ניט נאר ווי ס׳איז געווען „עד שחרב הבית בשניי׳״, נאר אויך) ווי מ׳וועט מקיים זיין דעם ציווי ב„בנין העתיד להבנות״³¹ — „והעשירית יעשה המלך המשיח״³².\nדערמיט וואלט מען אויך געקענט מבאר זיין פארוואס דער רמב״ם איז מוסיף „מהרה יגלה״: וויבאלד עס איז דא א חיוב תמידי אז עס זאל זיין אפר פרה „למשמרת״, קומט אויס, אז מצות פרה אדומה „מאנט״ אז עס זאל וואס שנעלער זיין גילוי המשיח, כדי מ׳זאל קענען מאכן אפר הפרה³³. ווארום בכל רגע ורגע ווען ס׳איז ניטא אפר פרה אין קיין ארט ניט וואו אידן געפינען זיך און היטן עס, פעלט אין דעם (שלימות) קיום הציווי אז עס דארף תמיד זיין אפר פרה „למשמרת״³⁴.\nד. דאס איז אבער נאך ניט קיין ביאור מספיק — ווייל פשטות לשון הרמב״ם איז דאך — אז דאס איז א בקשה ותפלה אויף גילוי המשיח, און ווי דער רמב״ם זאגט בפירוש „אכי״ר״³⁵. בלייבט די תמי׳: ווי פאסט אריין אין ספר היד א תפלה אויף ביאת (וגילוי) המשיח?\nמוז מען זאגן, אז דערמיט איז דער רמב״ם מרמז אן ענין של הלכה. וכידוע אז דרכו של הרמב״ם איז צו מרמז זיין הלכות בדיוק לשונו ודיוק סדר ההלכות (ובפרט ווען די הלכה איז א חידוש פון רמב״ם וואס שטייט ניט בפירוש אין ש״ס וכו׳).\nועד״ז בנדו״ד: דאס וואס דער רמב״ם איז (א) מוסיף א תפלה וועגן ביאת (וגילוי) המשיח, און (ב) שטעלט עס אריין ניט במקומו (לכאורה) אין „הלכות משיח״ נאר דוקא אין הלכות פרה אדומה (וואו דער ענין פון משיח קומט בדרך אגב) — קומט לערנען אן ענין של הלכה.\nה. ויש לומר הביאור בזה:\nבנוגע דעם חיוב צו גלויבן אין ביאת המשיח פסק׳נט דער רמב״ם אין הלכות מלכים³⁶ „וכל מי שאינו מאמין בו או מי",[["31","31","ל׳ הרמב״ם הל׳ ביהב״ח שם ה״ד."],["32","32","וראה לעיל הערה 25 בסופה."],["33","33","עפ״ז יומתק שנקט הרמב״ם ל׳ „מהרה יגלה״ (ולא — „יבוא״*) — כי** גילוי המשיח מורה על המצב ד„משיח ודאי״, שזהו דוקא לאחרי בנין ביהמ״ק כו׳ (רמב״ם הל׳ מלכים פי״א ה״ד), ומכיון שלעשיית האפר צ״ל ביהמ״ק (ראה רמב״ם הל׳ פרה אדומה פ״ד ה״ה), הרי שבשביל עשיית האפר צ״ל „מהרה יגלה״ דוקא."],["34","34","וע״פ הנ״ל הערה 25 שכל הפרות הן כמו חפצא אחת — נמצא, שכל זמן שחסר אפר פרה מסוימת — חסר בה„למשמרת״ של הפרות הקודמות. ואכ״מ."],["35","35","אבל להעיר שבדפוס רומי רמ ליתא. וכן ליתא במדרש הגדול פרשתנו יט, ט. קרית ספר על הרמב״ם כאן."],["36","36","פי״א ה״א. *) כלשון הרגיל בכ״מ ביאת המשיח. וכ״ה לשון הרמב״ם הל׳ תשובה פ״ג ה״ו. הל׳ נזירות פ״ד הי״א. הל׳ מלכים רפי״א. פי״ב ה״ב. — משא״כ בהנסמן לעיל הערה 8. וי״ל שהוא ע״פ ל׳ חז״ל (סוכה נב, א) „משיח בן דוד שעתיד להגלות במהרה בימינו״. **) ואולי מרמז בזה הרמב״ם לזה שאפרו של פרת משה קיים לעולם ולעת״ל יגלה האפר (ויקדשו (גם) ממנו כו׳) — ראה הנסמן בהערה 26."]]],[1300281148,"שאינו מחכה לביאתו . . הוא כופר . . בתורה ובמשה רבינו״. ד. ה. ס׳איז ניט גענוג צו גלויבן אין ביאת המשיח, נאר מ׳איז מחוייב צו האפן און ווארטן אויף ביאת המשיח.\nוא״כ הוא מובן, אז כשם ווי דער ענין האמונה בביאת המשיח איז אן ענין תמידי, עד״ז איז דער חיוב פון „מחכה לביאתו״ א חיוב תמידי, א איד דארף שטענדיק האפן און ווארטן אויף משיח׳ן, און נאכמער, ווי מען זאגט אין דאווענען — „כי לישועתך קוינו כל היום״.\nדער ענין פון „מחכה לביאתו״ וואס כפשטות לשון ההלכה איז עס א הרגש (ניט א ידיעה בעלמא) קומט דערפון וואס א איד פילט אז ער קען ניט האבן קיין שלימות בלי ביאת המשיח, ובמילא שטייט ער אין א תקוה תמידית לביאת המשיח, פילנדיק אז אין דעם איז ער א „חסר״. און דערפון פארשטייט מען, אז בשעת איינער — וועלכער איז מחכה אויף ביאת המשיח — דערמאנט אן ענין בשייכות צו משיח׳ן, אפילו עס זאל זיין בדרך אגב — קען ער דאס ניט „פארבייגיין״, נאר דאס איז ביי אים גלייך מעורר רגשי הצפי׳ צו משיח׳ן, ווערט עס צרכו³⁷, דארף ער מתפלל זיין ע״ז, זאגן א תפלה אויף מילוי חסרונו³⁸ — ער זאל זוכה זיין מהרה, בהקדם, תיכף צו ביאת המשיח.\nאון דאס איז כוונת הרמב״ם מיט (א) אריינשטעלן די תפלה „מהרה יגלה אכי״ר״ בכלל, און (ב) אריינשטעלן „מהרה״, וואס פריער, און (ג) דוקא שלא במקומה, אין הלכות פרה אדומה — דערמיט איז דער רמב״ם מדגיש א הלכה, אויף וויפל עס דארף זיין דער „מחכה לביאתו״, אז אפילו ווען דער ענין פון משיח קומט ארויף בדרך אגב, אין אן אנדער ענין³⁹, דארף עס גלייך ארויסרופן ביי א אידן א תפלה „מהרה יגלה אכי״ר״!\n[וכמובן האט ניט קיין ארט צו פרעגן: פארוואס איז דער רמב״ם מוסיף די תפלה („מהרה יגלה אכי״ר״) דוקא אין הלכות פרה אדומה און ניט יעדער מאל ווען ער דערמאנט אין ס׳ היד וועגן משיח׳ן? — ווייל, כנ״ל, דער רמב״ם איז א ספר הלכה, ד. ה. אויף צו מודיע זיין הלכות התורה. ועד״ז בעניננו: דאס וואס דער רמב״ם איז מוסיף די תפלה איז (ניט א פרט אין הנהגת הרמב״ם — וואס דעמאלט האט אן ארט די שאלה אז דער רמב״ם האט זיך אזוי געדארפט פירן בכל פעם ופעם — נאר) כדי צו מודיע זיין די הלכה שבזה; ובמילא טוט מען דאס איין מאל (אזוי ווי אלע אנדערע הלכות אין ספר היד וועלכע מען זאגט בלויז איין מאל)⁴⁰].",[["37","37","ראה רמב״ם הל׳ תפלה פ״א ה״ב „חיוב מצוה זו כך הוא שיהא אדם כו׳ ואח״כ שואל צרכיו שהוא צריך להם בבקשה ובתחנה״ (וראה שם ה״ד — נעתק לעיל סעיף א). וראה סהמ״צ להצ״צ שורש מצות התפלה בתחלתו (וש״נ)."],["38","38","שזוהי מצות (ותוכן ענין) התפלה — בקשת צרכיו — כבהערה הקודמת."],["39","39","ומה שהודיע הלכה זו דוקא כאן בהל׳ פרה אדומה (ולא כשנזכר ביד ע״ד משיח בפעם הא׳) — כי בוחר במקום שיש שייכות בתוכן כו׳, כדלקמן סעיף ו."],["40","40","דוגמא לדבר — גם בפרש״י עה״ת (פשוטו של מקרא): אלה תולדת נח נח איש צדיק (ר״פ נח), ובפרש״י „הואיל והזכירו ספר בשבחו שנאמר (משלי י, ז) זכר צדיק לברכה״ — ומ״מ לא מצינו שבכל"]]],[1300281149,"ו. אלע עניני התורה זיינען מדוייק בתכלית. דארף מען זאגן, אז דאס וואס דער רמב״ם איז מודיע די הלכה (בנוגע דעם אופן החיוב פון „מחכה לביאתו״) אין הלכות פרה אדומה — כאטש דער ענין פון משיח׳ן ווערט שוין דערמאנט אין רמב״ם לפני הלכות פרה אדומה⁴¹ (אויך דארט בדרך אגב) — איז עס צוליב א תוכנ׳דיקער שייכות⁴¹* וואס איז פאראן צווישן דעם ענין פון אפר פרה מיט ביאת (וגילוי) המשיח.\nדי הסברה בזה⁴²:\nדער כללות ענין הגלות איז א מצב פון טומאת מת. נוסף אויף דעם ענין כפשוטו, וואס מיר זיינען טמאי מתים⁴³, איז דאס אויך דער תוכן הרוחני פון ענין הגלות: סיבת הגלות איז דאך „חטאינו״ — אז עס פעלט אין דעם „ואתם הדבקים בה׳ אלקיכם״ — במילא⁴⁴ פעלט⁴⁵ אין דעם „חיים כולכם היום״.\nאון אפר הפרה — די טהרה פון טומאת מת — איז מרמז אויף דער גאולה פון גלות, די טהרה פון דעם מצב של פירוד מדבקות בה׳ אלקים חיים.\nוי״ל אז דאס איז דער דיוק אין נבואת הגאולה⁴⁶ „וזרקתי עליכם מים טהורים וטהרתם״ — זריקה דוקא, דאס הייסט, די טהרה על ידי הזאה — „הזית מי חטאת המעבירין טומאת המת״⁴⁷, וואס די טהרה קומט בגלוי בביאת משיח צדקנו,\nיבוא ויגאלנו במהרה בימינו ממש, ובלשון הרמב״ם — „מהרה יגלה אמן כן יהי רצון״.\n(משיחת ז׳ מרחשון תשמ״ו)",[["","","פעם שנזכר צדיק בתורה „ספר בשבחו״*! והתירוץ בפשטות — כי כוונת התורה (לשון הוראה) היא ללמדנו הנהגה זו, ולזה די לכתוב כן במקום אחד. וק״ל."],["41","41","ראה הנסמן בשוה״ג הא׳ להערה 33. ועוד. 41*) היינו שנוסף ע״ז שמצות פרה אדומה „מחייבת״ גילוי המשיח (כנ״ל סוס״ג) — הרי תוכן המצוה עצמה שייך להגאולה."],["42","42","ראה ג״כ <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600523\" data-slug=\"or-hatorah-hb\" data-id=\"8316600523\">אוה״ת נ״ך ח״א ע׳ תקכג</a>־ד. וראה לקו״ש חל״ג ע׳ 128."],["43","43","כהלשון „כולנו טמאי מתים״ (ל׳ היראים סשכ״ה (בהשלם — סרע״ז). רדב״ז הל׳ בכורים פ״ה ה״ט. ב״ח יו״ד סשכ״ב. מג״א סתקס״א סק״ב. ובכ״מ). — וראה טיו״ד סשל״א „שהכל טמאים״; ראב״ד הל׳ נזירות (פ״ה הט״ו־יז) „והכהנים בזמן הזה טמאי מת הן״. ועוד. וראה אנציקלופדי׳ תלמודית מע׳ אפר פרה בסופו (וש״נ). ועוד."],["44","44","ואתחנן ד, ד. וראה אדר״נ פל״ד, י."],["45","45","ובכמה ענינים נאמר מה לי קטלא פלגא מה לי קטלא כולי׳ (ב״ק סה, א. ב״מ צה, רע״א. חולין לה, סע״ב. וש״נ)."],["46","46","יחזקאל לו, כה."],["47","47","פרש״י עה״פ שם. חדא״ג מהרש״א יומא פה, ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171179\" data-slug=\"likkutei-sichot\" data-id=\"1300171179\">לקו״ש חי״ז (ע׳ 179</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171184\" data-slug=\"likkutei-sichot\" data-id=\"1300171184\">שם ע׳ 184</a>) — סיומים על מס׳ יומא. *) ראה השקו״ט במפרשי רש״י שם. לקו״ש חי״ה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151037\" data-slug=\"likkutei-sichot\" data-id=\"1300151037\">ס״ע 37</a> ואילך. ואכ״מ."]]],[1300281150,"<h3>חוקת ב</h3>\nא. בפרשתנו, דערציילט די תורה (די פרשה פון נחש הנחושת)¹: „וידבר העם באלקים ובמשה גו׳ וישלח ה׳ בעם את הנחשים גו׳ ויבא העם אל משה ויאמרו חטאנו גו׳ התפלל אל ה׳ ויסר מעלינו את הנחש ויתפלל משה בעד העם“.\nשטעלט זיך רש״י אויף די ווערטער „ויתפלל משה“ און איז מפרש: מכאן למי שמבקשים ממנו מחילה² שלא יהא אכזרי מלמחול. וי״ג „אכזרי למחול“³.\nדער מקור פון דעם פירוש איז אין תנחומא⁴ און דארט ווערט געזאגט: „להודיע ענותנותו של משה שלא נשתהה לבקש עליהם רחמים ולהודיעך כח התשובה כיון שאמרו חטאנו מיד נתרצה להם שאין המוחל נעשה להם אכזרי וכה״א⁵ ויתפלל אברהם אל האלקים וירפא האלקים⁶ את אבימלך ואת גו׳“ (און דערנאך ברענגט ער נאך א פסוק וואס שטייט ביי איוב).\nועפ״ז צריך להבין: פארוואס זאגט רש״י „מכאן למי שמבקשים ממנו מחילה“ בשעת מען קען דאס שוין אפלערנען פון דעם פריערדיקן פסוק „ויתפלל אברהם גו׳“, ווי ס׳איז מוכח פון תנחומא⁷?\n[ועוד: אט דער לימוד פון אברהם איז א משנה אין מסכת ב״ק⁸, אז „אע״פ שהוא נותן לו (בשעת איינער האט חובל געווען בחבירו איז כאטש אז ער האט אים באצאלט אלע חמשה דברים⁹) אין נמחל לו (מן הצער של הבושת שביישו¹⁰) עד שיבקש ממנו שנאמר¹¹ ועתה השב אשת וגו׳¹² ומנין שאם לא מחל לו שהוא אכזרי¹³ (אדער ווי די",[["1","1","כא, ה־ז."],["2","2","בדפוס שני ובכמה כת״י רש״י (שתח״י) „שמבקשים ממנו מטו“. ובכת״י א׳ „רחמים להתפייס“."],["3","3","כן הוא בדפוס ראשון ובכמה כת״י רש״י (שתח״י). ונראה יותר כדלקמן ס״ו."],["4","4","פרשתנו יט. ועד״ז בבמדב״ר פי״ט, כג. וראה לקמן הערה 7."],["5","5","וירא כ, יז."],["6","6","כ״ה בתנחומא. ובכתוב: אלקים."],["7","7","במ״כ לבמדב״ר שם: בתנחומא גרס מכאן שלא יהי׳ המוחל אכזרי. ולפנינו בתנחומא ליתא (וכמו שהעיר בעץ יוסף לתנחומא שם). אבל כ״ה ביל״ש עה״פ (כא, ז). וליתא שם ההמשך „וכה״א ויתפלל אברהם גו׳“. ובתנחומא (באבער) פרשתנו מו: ללמדך שאין המוחל נעשה אכזרי. וגם שם ליתא ההמשך „וכה״א ויתפלל אברהם גו׳“. אבל בכל אופן צריך ביאור דהרי רש״י לא כתב כאן רבותינו דרשו וכיו״ב, ובפשטות הכתובים ה״ז מוכח לכאורה גם מאברהם."],["8","8","צב, א."],["9","9","כ״ה ברמב״ם הל׳ חובל ומזיק פ״ה ה״ט. טושו״ע חו״מ סי׳ תכב. וראה לקמן הערה 27 — פי׳ הראב״ד והמאירי."],["10","10","ל׳ הטור חו״מ שם (וראה ב״ח ופרישה שכ״ה הנוסחא המדוייקת) — ע״פ ברייתא ב״ק שם (וראה פרש״י שם. ועד״ז במאירי שם). וראה פרישה שם, ובסמ״ע לשו״ע חו״מ שם עוד גירסא „מן הצער והבושת“. ואכ״מ."],["11","11","וירא כ, יז."],["12","12","כ״ה במשנה שבמשניות (פ״ח מ״ז), שבש״ס בבלי ובע״י. ובירושלמי (פ״ח ה״ז) הובא גם ההמשך „האיש כי נביא הוא“. וראה שינויי נוסחאות למשניות ב״ק שם."],["13","13","כ״ה במשנה בש״ס בבלי ובע״י. וכ״ה במפרשי הש״ס."]]]]});
